export type BikeOverview={years:number[];generation:string;summary:string;points:{aspect:string;verdict:string;statement:string;years:number[];support:number;strength:string}[];common_fixes:{problem:string;fix:string;result:string;support:number}[];disagreements:{topic:string;sides:string[]}[]};
export const bikeOverviews:Record<string,BikeOverview[]>={"Kawasaki|KX250":[{"years":[2020],"generation":"2020 (last year of the earlier engine, Showa coil fork)","summary":"The 2020 KX250 revs freely with good mid-to-top pull and was one of the most stable 250s, but testers found it short on bottom end compared with the YZ250F and slightly down on low end versus 2019. An ECU remap was the main engine fix. Notes include a grabby rear brake, a tall bar and soft seat, a clutch that slips on hard exits and stock springs that suit a middleweight rider.","points":[{"aspect":"engine_low","verdict":"weakness","statement":"Short on bottom-end grunt; needs a downshift more often than a YZ250F and feels slightly weaker down low than 2019.","years":[2020],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"neutral","statement":"Stock springs suit a middleweight: a 140 lb rider found them too stiff in braking bumps, while a 170 lb tester found the fork soft and pitchy on deceleration.","years":[2020],"support":2,"strength":"consensus"},{"aspect":"engine_mid","verdict":"strength","statement":"More mid-to-top pull and rpm recovery than 2019; revs freely.","years":[2020],"support":1,"strength":"single source"},{"aspect":"stability","verdict":"strength","statement":"Straight-line stability and bump absorption among the best in its class.","years":[2020],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"weakness","statement":"Rear sits low under acceleration and the end of the shock stroke is soft.","years":[2020],"support":1,"strength":"single source"},{"aspect":"brakes","verdict":"weakness","statement":"Front brake is strong, but the larger rear rotor is grabby and the pedal sits low with a long stroke.","years":[2020],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Stock bar feels tall and wide and the soft seat centre lets the rider sink in.","years":[2020],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"weakness","statement":"Stock clutch slips on hard exits with good grip.","years":[2020],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"weakness","statement":"Wide gap from second to third makes skipping third common.","years":[2020],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"neutral","statement":"Stock map is conservative and the bike feels weighed down.","years":[2020],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Weak bottom and mid","fix":"Custom ECU map on the stock ECU","result":"Stronger low and mid, freer revving, less engine braking and some exit torque back; quicker laps reported","support":2},{"problem":"Narrow rear tire lacks bite","fix":"110/90-19 rear tire","result":"More bite and stability with no real downside","support":1},{"problem":"Shock low under acceleration","fix":"Sag from 105 to about 103 mm and a quarter turn more high-speed compression","result":"Better traction and front bite; rear held up on G-outs","support":1},{"problem":"Light rider in braking bumps","fix":"Softer fork and shock springs","result":"Better braking-bump comfort; valving was close","support":1},{"problem":"Grabby rear brake","fix":"Fit the 2019 240 mm rear disc and hanger","result":"Easier to modulate","support":1},{"problem":"Tall bar","fix":"Lower-bend bar","result":"Better front feel","support":1},{"problem":"Clutch slip","fix":"Aftermarket clutch basket and pack","result":"No slip and longer life","support":1}],"disagreements":[{"topic":"Which coupler is aggressive","sides":["Most describe white as aggressive and black as mellow.","One tester found white helped low-end recovery but fell off earlier on top, and another magazine called black the most aggressive low-end."]}]},{"years":[2021,2022,2023,2024],"generation":"2021-2024 (big engine update, KX450-based frame, KYB coil fork)","summary":"Testers describe a top-end engine: strong mid and top that revs very high, but weak initial response and low-end torque that hurt corner exits. It is stable in a straight line yet tends to push in flat turns because the engine sits far back in the 450 frame. The KYB fork was widely found stiff and harsh, especially for riders under about 165 lb. Long-term tests list many small quality problems (soft threads, fast-wearing chain rollers, cracking muffler tab), and the usual fixes are fork revalving or lighter springs, an aftermarket linkage, exhaust, ECU mapping and a bigger rear sprocket.","points":[{"aspect":"engine_top","verdict":"strength","statement":"Strong mid and top that revs very high; it rewards being ridden at high rpm.","years":[2021,2022,2023,2024],"support":4,"strength":"strong consensus"},{"aspect":"engine_low","verdict":"weakness","statement":"Weak initial response and low-end torque hurt corner exits; it feels empty after the shift to third in deep dirt.","years":[2021,2022,2023,2024],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"KYB fork is stiff and harsh in the midstroke, especially for riders under about 165 lb.","years":[2021,2022,2023,2024],"support":3,"strength":"strong consensus"},{"aspect":"engine_mid","verdict":"strength","statement":"2023 engine has more midrange pull and a stronger top than 2022.","years":[2023,2024],"support":2,"strength":"consensus"},{"aspect":"turning","verdict":"weakness","statement":"Pushes in flat or off-camber corners and can feel vague mid-corner; the engine sits far back in the frame and the fork rides high.","years":[2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"reliability","verdict":"weakness","statement":"Soft threads strip easily (airbox bolt, fork-guard bolts, seat nuts).","years":[2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"maintenance","verdict":"weakness","statement":"Chain rollers, guides and sliders wear quickly; the front roller can come apart around 10 hours.","years":[2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"reliability","verdict":"weakness","statement":"Coolant loss in sand and a weak stock radiator cap.","years":[2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"stability","verdict":"strength","statement":"Stable in a straight line.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Muffler subframe tab cracks at the weld (worse with aftermarket exhaust) and a front engine-mount frame tab can crack after about 50 hours.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"weakness","statement":"Steering-head bearings come with little grease and can fail within 20 hours.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"neutral","statement":"A 2022 long-term bike broke clutch fibres and a main bearing in 75 hours; the 2023 reached 56 hours with no clutch-plate breakage.","years":[2022,2023],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Skinny levers cause blisters and the clutch feels on/off; grips are bonded to the throttle tube.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"tires","verdict":"weakness","statement":"Stock 100/90 rear lacks bite.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Stiff, harsh KYB fork","fix":"Revalve, lighter springs for light riders (about 4.7 N/mm) or remove fork oil","result":"Most of the midstroke harshness removed; one revalve with springs cured about 85-90% of it","support":3},{"problem":"Pushes in flat corners","fix":"Run less sag (about 100-103 mm), sit forward; avoid raising the forks","result":"Weight onto the front and sharper turning","support":2},{"problem":"Rear unsettled or lacking traction","fix":"Aftermarket linkage, with sag reset to about 102-104 mm","result":"Rear more planted and straighter in acceleration bumps, calmer on deceleration","support":2},{"problem":"Weak low end","fix":"Aftermarket exhaust and engine work (porting with ECU mapping)","result":"More bottom and mid pull; some corners taken a gear higher","support":2},{"problem":"Weak low end","fix":"One or two teeth larger rear sprocket (51-52T)","result":"Better pull out of corners","support":2},{"problem":"Wants more midrange","fix":"Custom map using the aggressive coupler's ignition with the mellow coupler's fuel, or Kawasaki's optional map","result":"More midrange and longer pull, noticeable but not huge","support":1},{"problem":"Wants more low response","fix":"Cut the snout off the side panel to open the airbox","result":"Sharper low-end response","support":1},{"problem":"Grabby clutch that burns fibres","fix":"Auto-clutch style pack and a longer-ratio lever","result":"Smoother engagement and longer life","support":1},{"problem":"Steering bearings fail early","fix":"Grease them when new","result":"Normal life","support":1},{"problem":"Narrow rear tire","fix":"110/90-19 rear on the stock rim","result":"More bite","support":1}],"disagreements":[{"topic":"2023 low end","sides":["One tester found more low grunt than 2022.","A magazine found initial response detuned versus 2022, with weaker bottom snap but stronger mid and top."]}]},{"years":[2025,2026],"generation":"2025-2026 (new engine and frame, Showa fork)","summary":"The 2025 KX250 split testers: faster riders found the engine heavier off the bottom with a narrow powerband, little recovery and less over-rev than 2024, while some novice and vet testers found it more usable. The new Showa fork is more compliant than the old KYB but soft for heavier or faster riders. The chassis turns more easily but feels stiffer and less stable at speed. Exhaust, airbox, ECU and gearing changes help response, though owners say it still feels slower-revving than the 2021-2024 bike.","points":[{"aspect":"power_delivery","verdict":"weakness","statement":"Narrow powerband that feels heavy off the bottom, with little recovery after a mistake and less over-rev than 2024; measured weaker than 2024 above about 6,500 rpm on one dyno.","years":[2025,2026],"support":5,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Fork is soft, sits low and turns harsh for heavier or faster riders, and can feel busy at the top of the stroke on fast tracks.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"turning","verdict":"strength","statement":"Turns more easily with better front contact than 2024.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"stability","verdict":"weakness","statement":"Chassis feels stiffer, twitchy and slightly less stable at speed, deflects and gets nervous when chopping the throttle.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"mapping","verdict":"neutral","statement":"Maps can be changed through the phone app; Kawasaki's optional maps cut engine braking and add low-mid response but shorten the pull in second and third.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"strength","statement":"Switch to the Showa fork made it far more compliant on corner entry.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"weight_feel","verdict":"weakness","statement":"Heaviest 250F in one comparison.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"other","verdict":"weakness","statement":"Most vibration of the 250Fs despite a new balancer.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"brakes","verdict":"weakness","statement":"Rear brake is hard to modulate and locks easily.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"weakness","statement":"Shifting is notchy under load.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Brittle plastics, a strip-prone airbox bolt, a seat T-plate that can fall out, a low-pressure radiator cap and a restrictive airbox with a hard-to-seat filter.","years":[2025,2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Restricted intake","fix":"Aftermarket air filter kit and trimming or opening the airbox","result":"Sharper response","support":3},{"problem":"Flat engine","fix":"Aftermarket full exhaust","result":"Stronger mid-to-top pull, smoother over-rev and faster recovery; second held longer and third usable in corners; small low-end gain","support":2},{"problem":"Flat engine","fix":"Stock-ECU reflash or mapped aftermarket ECU","result":"Better response and second-third pull; owners say it still revs slower than the 2021-2024 bike","support":2},{"problem":"Weak pull out of corners","fix":"51-tooth rear sprocket","result":"Better low-end pull","support":2},{"problem":"Oversteer and instability","fix":"Lower the forks to flush (or about 3 mm), run the rear wheel back and speed up rebound","result":"More stable into corners and less oversteer","support":2},{"problem":"Fork too soft for heavier or faster riders","fix":"Revalve with stiffer springs; an aftermarket linkage needs a shock spring about 0.1 kg/mm stiffer","result":"Plush top, firm controlled midstroke, predictable bottoming and a more planted rear","support":1},{"problem":"Stiff, nervous chassis","fix":"Aftermarket engine mounts","result":"More flat-corner lean grip, planted off throttle, better slap-downs","support":1},{"problem":"Weak radiator cap","fix":"1.8 kg/cm2 cap","result":"Holds coolant","support":1}],"disagreements":[{"topic":"2025 engine versus 2024","sides":["Faster riders and two magazines found it heavier, narrower and weaker on top than 2024.","Other launch tests found more usable low-to-mid power and easier starts, and novice and vet riders tended to prefer it."]}]}],"Kawasaki|KX250X":[{"years":[2021,2022,2023,2024],"generation":"2021-2024 (off-road version of the 2021 KX250)","summary":"Off-road testers found the KX250X engine clean and happiest revved, with a strong top but limited bottom-end torque for technical terrain. The small tank, the stock front tire, the bulky kickstand and some head shake at speed were the main complaints. ECU remapping and gearing changes were the common upgrades.","points":[{"aspect":"engine_low","verdict":"weakness","statement":"Clean and stall-free down low but short of bottom-end torque for off-road; a remap still left low end lacking.","years":[2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"engine_top","verdict":"strength","statement":"Strong top end that keeps pulling a long way before the limiter.","years":[2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"gearing","verdict":"weakness","statement":"First gear so short it is rarely used, and fifth runs out quickly.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"other","verdict":"weakness","statement":"Small tank ran dry around 55 minutes into a one-hour race.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"tires","verdict":"weakness","statement":"Stock front tire has weak traction and stiff sidewalls.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"stability","verdict":"weakness","statement":"Some head shake at speed; testers wanted a steering stabilizer for fast sections.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Bulky kickstand sits against the left leg.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"neutral","statement":"Heavier vet riders found it under-sprung.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Missing low-end power","fix":"ECU remap (one tester also preferred the aggressive coupler)","result":"More power everywhere, though low-end torque was still lacking","support":2},{"problem":"Gearing for desert racing","fix":"Tried 14/48, which was too tall and hard on the clutch in rocks; settled on 14/50","result":"Workable gearing for fast terrain","support":1},{"problem":"Runs out of fuel","fix":"Larger aftermarket tank","result":"Full race distance","support":1},{"problem":"Harsh in slow terrain","fix":"Soften low-speed compression 2-3 clicks at both ends and speed up fork rebound 1-2 clicks at 105 mm sag","result":"Smoother off-road","support":1}],"disagreements":[{"topic":"Bottom-end torque","sides":["Two tests found it short of low-end torque for off-road.","A 2022 test found a decent bottom with enough torque and a linear build."]}]},{"years":[2025,2026],"generation":"2025-2026 (2025 engine and frame, Showa suspension)","summary":"Only one first-impression test. The new engine puts more weight on low and midrange torque, which suits technical riding. The softer Showa suspension is plush in slow terrain but rides low and harsh on deceleration at speed.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"More low and midrange torque than the earlier high-revving engine; easier in technical terrain.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"neutral","statement":"Plush in slow terrain but low and harsh on deceleration at speed.","years":[2025,2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Fork low on deceleration at speed","fix":"A few clicks more compression and one click faster rebound","result":"Rode higher in the stroke and more balanced","support":1}],"disagreements":[]}],"Kawasaki|KX450":[{"years":[2019,2020,2021,2022,2023],"generation":"2019-2023 (2019-generation engine and frame, Showa coil fork)","summary":"Testers rate this KX450 chassis among the most stable and forgiving of the aluminium-frame 450s, and it lays into ruts easily, though it can feel long with a vague front. The engine is smooth and usable rather than the strongest, with a touchy hit right off idle. The Showa fork is too soft and divey, the rear brake is grabby, and soft threads and a crack-prone muffler tab are recurring niggles. Stiffer fork springs or a revalve, ECU mapping, a slip-on with the stock header and the KX250's smaller rear rotor were the usual fixes.","points":[{"aspect":"power_delivery","verdict":"neutral","statement":"Smooth and very usable rather than the strongest; lacks the mid pull of its main rivals in deep dirt and measures down on power from mid rpm up.","years":[2019,2020,2021,2022,2023],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Showa fork is too soft: it dives, pitches and bottoms on hills and big jumps, and adding compression only makes it harsh.","years":[2019,2020,2021,2022,2023],"support":3,"strength":"strong consensus"},{"aspect":"stability","verdict":"strength","statement":"Very stable and compliant; frame absorption is among the best in its class and makes setup less critical.","years":[2019,2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"turning","verdict":"strength","statement":"Lays into ruts easily with good rear bite and is easy into and through corners.","years":[2019,2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"turning","verdict":"weakness","statement":"Can feel long and lazy with a vague front mid-corner and once in a rut.","years":[2019,2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"engine_low","verdict":"weakness","statement":"Touchy right off idle (0-10% throttle), which can upset it mid-corner.","years":[2019,2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"brakes","verdict":"weakness","statement":"250 mm rear rotor is touchy and locks early.","years":[2019,2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"reliability","verdict":"weakness","statement":"Soft threads strip (seat nuts, airbox bolt in the subframe).","years":[2019,2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"suspension_rear","verdict":"weakness","statement":"Shock wallows and is soft on slap-downs and G-outs, squatting on exits for heavier riders; the stock link is harsh early and soft deep in the stroke.","years":[2019,2020,2021,2022,2023],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"strength","statement":"2021 clutch slips less with wider engagement and more traction.","years":[2021,2022,2023],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Muffler mounting tab on the subframe cracks, especially with solid-mounted aftermarket exhausts.","years":[2019,2020,2021,2022,2023],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"weakness","statement":"Fork guards and number plates crack and the lower chain roller wears fast.","years":[2019,2020,2021,2022,2023],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Skinny clutch and brake levers cause blisters and the clutch feels on/off.","years":[2019,2020,2021,2022,2023],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Soft, divey fork","fix":"One step stiffer fork springs (about 5.1 N/mm)","result":"Better balance and decel-bump comfort, less oversteer","support":2},{"problem":"Soft fork and shock","fix":"Revalve (owners say it is valved soft rather than undersprung); one owner raised fork oil volume","result":"Hold-up on deceleration and bump absorption without harshness","support":2},{"problem":"Shock soft on slap-downs","fix":"More shock high-speed compression (up to about two turns in)","result":"Less wallow","support":1},{"problem":"Rear harsh early, soft deep","fix":"Aftermarket linkage, usually with a stiffer shock spring","result":"Plusher early, firmer deep, straighter in acceleration bumps and calmer under braking","support":2},{"problem":"Grabby rear brake","fix":"Fit the KX250's 240 mm rear disc and hanger","result":"Easier to modulate","support":2},{"problem":"Touchy low end, dip from mid to top","fix":"Custom ECU map or reflash; mellow coupler for slick tracks","result":"Smoother off idle, dip filled, steadier in corners; owners call a reflash the cheapest effective upgrade","support":2},{"problem":"Snappy, hard-to-control hit with an aftermarket system","fix":"Slip-on muffler with the stock longer header","result":"Smoother, more controllable power and better corner speed","support":2},{"problem":"Subframe tab cracking","fix":"Rubber-mount the muffler bracket with the stock grommet, or have the tab re-welded","result":"Saves the subframe","support":1}],"disagreements":[{"topic":"Black (mellow) coupler","sides":["One tester found it smoothed the low end with no loss of mid-top pull.","A magazine found it gives up 1-2 hp from 6,000 to 11,500 rpm and is too smooth in deep dirt."]}]},{"years":[2024,2025,2026],"generation":"2024-2026 (new engine top end, frame, Showa suspension and bar electronics)","summary":"Testers agree the stock 2024-on KX450 feels mild and lethargic, more like a big 250 or a 350, with a restrictive airbox (including a hidden rubber plug) and muffler. The new chassis turns in far more sharply but can oversteer and shake its head at speed until the forks are lowered and the wheelbase lengthened. The fork is soft and pitchy with too little initial support. The most common fixes are opening the airbox, an aftermarket ECU and exhaust, a 51-tooth rear sprocket and stiffer fork settings.","points":[{"aspect":"power_delivery","verdict":"weakness","statement":"Stock engine feels mild, lethargic and heavy in tight corners, soft off the bottom and short on punch for starts, hills and deep sand.","years":[2024,2025,2026],"support":6,"strength":"strong consensus"},{"aspect":"engine_mid","verdict":"strength","statement":"Smooth and linear with good mid-to-top pull once revving; best ridden like a big 250.","years":[2024,2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"turning","verdict":"strength","statement":"Much sharper turn-in than before, with front-wheel traction while staying stable.","years":[2024,2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Fork is soft and pitchy with too little initial support, so it rides in the midstroke, dives under braking, bottoms and feels harsh on deceleration; the shock overpowers it.","years":[2024,2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"mapping","verdict":"weakness","statement":"Phone-app tuning offers few parameters and small gains, and a custom map saved to the second slot is detuned by the ECU.","years":[2024,2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"engine_low","verdict":"weakness","statement":"Intake and exhaust are restrictive: a hidden rubber plug blocks part of the airbox and the stock muffler is choked.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"stability","verdict":"weakness","statement":"Can oversteer and shake its head at speed, and feels top-heavy in flat turns.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"gearing","verdict":"weakness","statement":"Second gear is long and third feels far away.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"weakness","statement":"Vibration through the bars at low rpm and the pegs at high rpm.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"weight_feel","verdict":"weakness","statement":"Measured about 5 lb heavier than the 2023.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"suspension_rear","verdict":"neutral","statement":"Shock is plush, possibly soft for pros, though another tester found it firm in the midstroke and needing more hold-up.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"neutral","statement":"Traction control helps on hard-pack under loose dirt and on uphills but does little on a smooth, dry day.","years":[2024,2025,2026],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Some bikes leak oil from the right side-case gasket under the cylinder.","years":[2024,2025],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Stock air filter can be mis-installed and collapse inward, risking dirt ingestion.","years":[2024],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"neutral","statement":"A few owners reported very-low-hour engine failures or worn clutch plates around 20 hours; others report no problems.","years":[2024,2025,2026],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"weakness","statement":"Header nuts are nearly inaccessible.","years":[2024,2025,2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Lethargic power","fix":"Aftermarket ECU with tuner mapping, usually with an exhaust and opened airbox","result":"Much stronger off the bottom and third gear usable in corners; one dyno showed almost 4 hp more, and riders felt about 6-7 hp","support":3},{"problem":"Choked intake","fix":"Remove the hidden airbox rubber plug and drill or open the side cover/airbox","result":"Better throttle response and bottom-end pull","support":3},{"problem":"Choked muffler, heavy low end","fix":"Aftermarket slip-on or full exhaust","result":"More response and midrange; one dyno test showed about 3 hp more at 7,500 rpm","support":2},{"problem":"Weak third-gear pickup","fix":"51-tooth rear sprocket","result":"Third more usable in corners","support":2},{"problem":"Oversteer and head shake at speed","fix":"Lower the forks to flush, add a chain link and run the wheel back, add fork compression","result":"More stability at speed","support":4},{"problem":"Soft, bottoming fork","fix":"Stiffer fork springs (one or both legs) or about 10 cc more oil per leg, plus more compression","result":"Better hold-up and bottoming resistance","support":2},{"problem":"Fork and shock lack hold-up","fix":"Shop revalve","result":"More braking-bump support with the same ground-following feel; better shock control on acceleration and landings","support":1},{"problem":"Wants more low torque","fix":"Kawasaki's optional app maps","result":"More low torque feel and second-third roll-on, longer third","support":1},{"problem":"Vibration","fix":"Aftermarket engine mounts and head stays","result":"Less vibration","support":1}],"disagreements":[{"topic":"Top-end strength","sides":["Several tests found good mid-to-top pull.","One magazine found it broad and easy but lacking top end and torque."]},{"topic":"High-speed stability","sides":["2024 tests reported oversteer and head shake at speed.","2026 shootouts called the chassis stable, even best in class, though setup-sensitive."]},{"topic":"Front brake","sides":["One magazine rated the front brake excellent.","A 2026 shootout found it weaker than the class."]},{"topic":"51-tooth rear sprocket","sides":["Magazine testers call it one of the best single changes.","One tester found 13/51 hurt second-gear pull and went back to stock."]},{"topic":"Exhaust and low end","sides":["One magazine's slip-on test showed no meaningful low-end gain.","Other testers felt more low-end pull from slip-ons and full systems."]},{"topic":"Lowering link","sides":["One tester liked a lowering link on the earlier KX450.","On 2024-2025 bikes a tuner advised keeping the stock link because a lowering link softens shock feel; forum riders had no consensus."]}]}],"Kawasaki|KX450X":[{"years":[2021,2022,2023],"generation":"2021-2023 (off-road version of the 2019-generation KX450)","summary":"Testers found the KX450X's softer off-road suspension too soft at speed and on big hits, and stiffened fork compression as a first step. The front can feel vague on lean, the rear brake fades in heat on tight trails and the kickstand gets in the way.","points":[{"aspect":"suspension_front","verdict":"weakness","statement":"Stock suspension is too soft at speed: the fork blows through on bigger hits and rides low, and the shock lacks hold-up.","years":[2021,2022,2023],"support":3,"strength":"strong consensus"},{"aspect":"turning","verdict":"weakness","statement":"Front feels vague on lean and can wash suddenly or push on corner entry; some head shake at speed.","years":[2021,2022,2023],"support":1,"strength":"single source"},{"aspect":"brakes","verdict":"weakness","statement":"Rear brake fades in heat on tight trails.","years":[2021,2022,2023],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Kickstand hits when leaning and stock levers are skinny.","years":[2021,2022,2023],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Fork too soft","fix":"Stiffer fork compression and higher oil level, or an off-road revalve","result":"Firmer end of stroke and better hold-up","support":3},{"problem":"Vague front","fix":"Aftermarket 22 mm offset clamps","result":"More front traction, slightly more feedback on fast square edges","support":1},{"problem":"Rear could drive better through square edges","fix":"Aftermarket linkage at 102 mm sag","result":"More traction","support":1},{"problem":"Rear brake fade","fix":"Larger-volume rear brake piston","result":"Holds more fluid and sheds heat","support":1}],"disagreements":[]},{"years":[2024,2025,2026],"generation":"2024-2026 (off-road version of the 2024 KX450)","summary":"Little tester data. In a cross-country comparison the KX450X felt stiffer with more hold-up than its rival: good on fast courses, harder work in tight rocks and roots. One test noted it ran hot on tight technical trails.","points":[{"aspect":"suspension_front","verdict":"neutral","statement":"Stiffer with more hold-up than its main rival; good on fast courses but harder work in tight rocks and roots.","years":[2024,2025,2026],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Ran hot on tight technical trails.","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Stability on fast cross-country courses","fix":"Rear wheel back about 12 mm with extra chain links, 51-tooth sprocket, forks 2 mm up","result":"Calmer at speed","support":1},{"problem":"Fork soft at higher speeds","fix":"A few clicks more fork compression","result":"Better support at speed","support":1}],"disagreements":[]}],"Honda|CRF450R":[{"years":[2020],"generation":"2020 (last year of the 2017-generation frame and twin-muffler engine)","summary":"A powerful, light-turning 450 with a well-liked rider triangle, but testers agree the stiff chassis is harsh on bumps and nervous at speed on fast, rough tracks, and it was called the hardest bike in one shootout to set up. The clutch is the clear weak point: it heats up, slips and has a narrow engagement. The fork dives under hard braking and is soft on big hits, and the bike is heavy for its class with twin mufflers. Clutch packs, lower chassis bolt torques, calmer ECU maps or exhausts and lower fork height were the usual fixes.","points":[{"aspect":"stability","verdict":"weakness","statement":"Stiff chassis is harsh on bumps and twitchy or unpredictable at speed on fast, rough tracks, and can feel different day to day; it is happiest on tight, turny tracks.","years":[2020],"support":3,"strength":"strong consensus"},{"aspect":"clutch","verdict":"weakness","statement":"Clutch is the weak point: it heats up and slips or drags within a moto, the pull is heavy and engagement is narrow and on/off.","years":[2020],"support":3,"strength":"strong consensus"},{"aspect":"turning","verdict":"strength","statement":"Turns well and feels light; the 2020 battery moved lower and makes tip-in easier.","years":[2020],"support":2,"strength":"consensus"},{"aspect":"engine","verdict":"strength","statement":"Very strong engine: the most powerful 450 of 2020 on one magazine dyno, with 2020 mapping smoother off the bottom and pulling longer through mid and top than 2019.","years":[2020],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Fork dives under hard braking at race pace and is too soft on big hits and landings; one magazine also found it harsh on small braking bumps and could not fix that with the clickers.","years":[2020],"support":2,"strength":"consensus"},{"aspect":"maintenance","verdict":"weakness","statement":"Keep water away from the handlebar map and kill switches when washing; water there can stop the bike starting.","years":[2020],"support":2,"strength":"consensus"},{"aspect":"ergonomics","verdict":"strength","statement":"Rider triangle is widely liked.","years":[2020],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"weakness","statement":"Even the 2020 stock maps deliver too much for anything but loamy dirt, which upsets the stiff chassis.","years":[2020],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"neutral","statement":"Most magazine testers stayed on the standard map; the aggressive map felt crisper but measured about 1 hp less everywhere.","years":[2020],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"weakness","statement":"Shock is comfortable but runs out of support at the end of the stroke on G-outs.","years":[2020],"support":1,"strength":"single source"},{"aspect":"weight","verdict":"weakness","statement":"Heavy for the class (about 15 lb over the lightest 450 without fuel); the twin mufflers add weight and replacement cost.","years":[2020],"support":1,"strength":"single source"},{"aspect":"sound","verdict":"weakness","statement":"Measured over the 115 dB two-metre-max limit used by pro racing, though it passed the 94 dB amateur test.","years":[2020],"support":1,"strength":"single source"},{"aspect":"known issue","verdict":"weakness","statement":"Boils coolant quickly in hard use.","years":[2020],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"strength","statement":"One owner reported about 140 trouble-free hours with oil and filter changed every 6 hours.","years":[2020],"support":1,"strength":"single source"},{"aspect":"other","verdict":"neutral","statement":"Traction control helped most testers once the track got slick in the afternoon.","years":[2020],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"neutral","statement":"Stock 13/49 is in the ballpark; some testers preferred a taller 13/48.","years":[2020],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Clutch slips, heats up or engages on/off","fix":"Remove the judder spring and add a full-size friction plate, or fit an aftermarket clutch pack (Hinson or Rekluse); a longer clutch arm or different clutch cam widens engagement","result":"Wider engagement, less slip and longer clutch life; a longer arm roughly halved lever effort","support":3},{"problem":"Harsh chassis on square edges","fix":"Lower swingarm-pivot and engine-hanger bolt torque and seat the engine up and back in the frame before torquing","result":"Softer square-edge feel, more rear traction, less vibration and easier initial lean","support":1},{"problem":"Delivery and engine braking upset the chassis","fix":"Aftermarket ECU with linear maps, or an aftermarket muffler with a smoother low end","result":"Less engine braking and pitching; calmer chassis","support":1},{"problem":"Fork dives and is soft on big hits","fix":"Stiffer fork compression and slower rebound (pros went much stiffer), stiffer springs or a revalve for a lasting fix; shock high-speed compression a quarter turn in at about 105-107 mm sag","result":"Calmer front under braking and better G-out support","support":2},{"problem":"Nervous at speed","fix":"Lower the forks in the clamps (flush to about 2 mm)","result":"Calmer on fast tracks at some cost to turn-in","support":2},{"problem":"Boiling over","fix":"Higher-pressure radiator cap and check the fins for roost damage","result":"Holds coolant in hard use","support":1}],"disagreements":[]},{"years":[2021,2022,2023,2024],"generation":"2021-2024 (all-new 2021 frame and single exhaust; 2023 engine and frame refinements)","summary":"Testers consistently praise this CRF450R's turn-in and cornering but call the chassis harsh and tiring on dry, choppy tracks, nervous at speed and unusually sensitive to small setup changes. Early 2021 bikes ran rich and popped until Honda's free dealer reflash, and a 2021 drive-chain recall covered some early bikes; from 2023 the engine became more linear and torque-led. Stock suspension was the top complaint (soft in 2021, harsh or stagey from 2022), so the most common fixes were stiffer springs, a revalve or aftermarket linkage, longer-offset clamps, lower fork height and lower chassis bolt torques. A higher-pressure radiator cap is a standard recommendation.","points":[{"aspect":"turning","verdict":"strength","statement":"Sharp, precise turn-in and excellent in tight corners, on or off the throttle.","years":[2021,2022,2023,2024],"support":5,"strength":"strong consensus"},{"aspect":"stability","verdict":"weakness","statement":"Harsh and tiring on dry, choppy tracks, rigid on hard landings, loose at the rear on exits and prone to wander or head shake at speed; happiest on smooth tracks.","years":[2021,2022,2023,2024],"support":5,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"2021 suspension is soft and unbalanced for fast or 170 lb-plus riders: the fork pitches and bottoms and the rear blows through its stroke in ruts on the stock 54 N/mm spring.","years":[2021],"support":5,"strength":"strong consensus"},{"aspect":"power_delivery","verdict":"strength","statement":"From 2023 the engine is more linear and torque-led: precise throttle control at low rpm, stronger low-mid and a less frantic top, controllable by throttle rather than clutch.","years":[2023,2024],"support":4,"strength":"strong consensus"},{"aspect":"balance","verdict":"weakness","statement":"Very sensitive to setup: a few mm of sag or 1 mm of fork height is felt, fore/aft balance is hard to find, and a setting does not carry well from track to track.","years":[2021,2022,2023,2024],"support":4,"strength":"strong consensus"},{"aspect":"known issue","verdict":"weakness","statement":"Early 2021 bikes ran rich and dirty at low rpm and popped or flamed out in some maps; Honda issued a free dealer ECU reflash (also for the RX and Works Edition) and the corrected map became standard for 2022.","years":[2021],"support":3,"strength":"strong consensus"},{"aspect":"clutch","verdict":"strength","statement":"Hydraulic clutch has a light pull, engages in the same place every time and does not fade.","years":[2021,2022,2023,2024],"support":3,"strength":"strong consensus"},{"aspect":"known issue","verdict":"weakness","statement":"Recall (April 2021): the drive chain can break on about 536 early red 2021 CRF450Rs (a specific VIN range); free dealer repair.","years":[2021],"support":2,"strength":"consensus"},{"aspect":"power_delivery","verdict":"neutral","statement":"2021-2022 engine is strong and quick-revving with a big top end, but the bottom is ordinary before a steep surge around 7,000 rpm; with the occasional low-rpm hiccup it is easy to stall and demanding even for good riders.","years":[2021,2022],"support":2,"strength":"consensus"},{"aspect":"engine_top","verdict":"neutral","statement":"The 2023 retune traded some peak power for torque: it led its class on peak torque on one dyno but sat mid-pack on peak horsepower and fell behind the 2022 above about 8,300 rpm.","years":[2023,2024],"support":2,"strength":"consensus"},{"aspect":"mapping","verdict":"neutral","statement":"2022 mapping is cleaner and makes all three maps usable, though some lean popping on deceleration remained into 2023.","years":[2022,2023],"support":2,"strength":"consensus"},{"aspect":"mapping","verdict":"neutral","statement":"Standard map (map 1) is the usual choice; the aggressive map is sharper off the bottom but makes less peak power and can ping on hot days.","years":[2023,2024],"support":2,"strength":"consensus"},{"aspect":"electronics","verdict":"neutral","statement":"Traction control helps on hard-pack and loose-over-hard dirt but makes the bike feel choked in sand or very loose soil.","years":[2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"turning","verdict":"weakness","statement":"At the stock 22 mm offset the front can knife into hooked ruts and oversteer in long rutted corners.","years":[2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"stability","verdict":"strength","statement":"The 2023 frame changes and steel head stays made the rear calmer and more compliant in corners.","years":[2023,2024],"support":2,"strength":"consensus"},{"aspect":"suspension_rear","verdict":"weakness","statement":"From 2022 the fork is harsh in the mid or late stroke and the shock is stagey: it wallows in small bumps yet is harsh accelerating out of corners on baked, square-edged tracks.","years":[2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"clutch","verdict":"weakness","statement":"Hydraulic clutch engagement is narrow and on/off, and the clutch is not bulletproof under hard racing.","years":[2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"brakes","verdict":"strength","statement":"Front brake rated among the best on a Japanese bike.","years":[2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"vibration","verdict":"weakness","statement":"More engine vibration through the pegs and bars than rivals, at low rpm and as a high-rpm buzz with the stock muffler.","years":[2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"handling","verdict":"weakness","statement":"Rear can sit high entering corners off the throttle; curing that with less sag or a stiffer fork makes the chassis edgier.","years":[2021,2022],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"strength","statement":"Slim bike with a rider triangle that suits most body sizes; the shift lever is short.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"weight","verdict":"strength","statement":"Weighed about 233 lb without fuel in 2021 and 2023, the lightest Japanese 450 in that test.","years":[2021,2023],"support":1,"strength":"single source"},{"aspect":"known issue","verdict":"weakness","statement":"Radiators boil over quickly in hard use on the stock 1.1 cap.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"known issue","verdict":"weakness","statement":"A 14-tooth countershaft sprocket can damage the clutch slave cylinder on 2021 bikes.","years":[2021],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"weakness","statement":"Upside-down air filter gets dirty quickly and is awkward to service; seat foam breaks down quickly; exhaust flange studs can back out of the head.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"durability","verdict":"weakness","statement":"2022 muffler dents easily from leg pressure; 2023 got a heat-treated muffler body.","years":[2022],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"neutral","statement":"Many testers go one tooth larger on the rear (13/50) so third gear pulls sooner in turns.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Rich, dirty low end and popping (2021)","fix":"Honda dealer ECU reflash; use map 1 or 3 until then; an independent reflash also cleaned it up","result":"Cleaner low-rpm running; the fix became the 2022 standard map","support":3},{"problem":"Engine braking and on/off feel upset the chassis","fix":"Aftermarket ECU or a reflash of the stock ECU's maps 2 and 3","result":"Less engine braking, cleaner low-rpm cornering, more rear bite; third gear lugs on stock gearing","support":2},{"problem":"Touchy low end, decel harshness","fix":"Aftermarket exhaust (slip-on or full system)","result":"Smoother low-rpm roll-on, less engine braking and vibration, more mid; one full system with an ECU flash measured about 4.7% more peak power","support":3},{"problem":"Nervous at speed, knifing in ruts","fix":"Longer-offset clamps (23.5-24 mm), often with a revalve","result":"More stability and rut tracking, less vibration and harshness, turning kept","support":2},{"problem":"Head shake","fix":"Lower the forks from the stock 5 mm to about 2.5 mm or flush","result":"Calmer at speed without losing turn-in","support":2},{"problem":"Harsh on square edges","fix":"Lower chassis bolt torques slightly (axle, pivot, hangers, clamp pinch bolts) with thread locker","result":"More compliance and traction; Honda responds to this more than other bikes","support":1},{"problem":"Stock suspension soft for heavier or faster riders","fix":"One spring rate stiffer at each end (fork about 5.1 N/mm, shock 56 N/mm; 58 N/mm over about 200 lb)","result":"Bike rides higher and settles; more traction and track toughness, less oversteer","support":4},{"problem":"Harsh or unbalanced suspension","fix":"Revalve fork and shock","result":"More consistently plush fork and less loose feel at speed; owners name it the top improvement","support":2},{"problem":"Shock harsh accelerating out of corners","fix":"Aftermarket linkage with a flatter early and steeper late rate, plus a lighter spring and matched valving","result":"Corner-exit harshness roughly halved, better tracking, flatter on braking bumps","support":3},{"problem":"Narrow hydraulic clutch engagement","fix":"Fit a 2023 Kawasaki KX master cylinder and flip the stock line","result":"More progressive engagement","support":1},{"problem":"Engine vibration","fix":"Engine tilt procedure when torquing mounts, plus an aftermarket muffler or longer-offset clamps","result":"Reduced vibration","support":1},{"problem":"Boiling over","fix":"1.8 high-pressure radiator cap","result":"Holds coolant in hard use","support":1},{"problem":"Aggressive map pings","fix":"Use the standard map, or mix race fuel with pump fuel","result":"No detonation","support":1}],"disagreements":[{"topic":"2021-2022 power character","sides":["One tester found it smoother and longer-pulling than 2020 and easy to roll on.","Other tests found an ordinary bottom, a low-rpm stumble and a steep surge around 7,000 rpm that was hard to manage."]},{"topic":"Why the chassis feels harsh","sides":["Testers blamed an overly rigid aluminium frame.","Honda later said the old frame was among the softest and that flex caused the harshness; one tester also found the 2021 frame softer and straighter-tracking than 2020."]},{"topic":"Front brake","sides":["Testers rated it among the best brakes in the class.","Another had it overheat within a few laps in a 2021 shootout."]},{"topic":"Race sag","sides":["Owners found 110 mm too low and harsh and went back to Honda's 105 mm.","One magazine advised 100 or 108 mm and avoiding 105 mm; another found most testers liked more than 105 mm."]}]},{"years":[2025,2026],"generation":"2025-2026 (stiffer frame with about 70% new parts, new linkage and suspension)","summary":"Most testers say the 2025 frame transformed the CRF450R: more planted and stable at speed, less vibration, more neutral in corners and much less setup-sensitive, while keeping its sharp turn-in. The engine has the strongest low-to-mid pull of its class and is very usable, but tapers on top and measures a few hp behind the leaders. The plusher suspension suits 160-175 lb novice to intermediate riders; fast and heavier riders find it too soft and add compression, adjust fork height or fit stiffer springs. A minority still report harshness on hard, edgy tracks or pitching, and the 2025-2026 bikes are covered by an April 2026 handlebar-clamp recall.","points":[{"aspect":"engine_low","verdict":"strength","statement":"Very linear and usable with the strongest low-to-mid pull in its class and a crisp throttle connection; it can pull third gear in corners.","years":[2025,2026],"support":7,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"strength","statement":"Coil fork is much plusher with no harsh spot; setup is spot-on for a 160-175 lb intermediate or vet rider.","years":[2025,2026],"support":6,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Too soft for fast intermediates, pros and heavier riders: the fork dives under hard braking and can bottom on big jumps, and the softer 52 N/mm shock spring suits lighter riders.","years":[2025,2026],"support":6,"strength":"strong consensus"},{"aspect":"stability","verdict":"strength","statement":"Much better high-speed stability with less vibration and harsh slap-down; more neutral and less front-heavy in corners.","years":[2025,2026],"support":5,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Tapers off on top; peak power measures a few hp behind the class leaders, though it rides better than its dyno number.","years":[2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"turning","verdict":"strength","statement":"Accurate turn-in, the easiest bike to turn in ruts and strong on inside lines; it favours tight tracks over fast sweepers.","years":[2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"balance","verdict":"strength","statement":"Well balanced out of the crate and far less setup-sensitive than the 2021-2024 bike; no need for constant fork-height changes between tracks.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"handling","verdict":"weakness","statement":"Can feel busy and pitch between acceleration and braking, partly because the suspension is soft.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"stability","verdict":"weakness","statement":"Some riders still find it harsh over square edges and unsettled on fast hard-pack, with a kicking feel through the rear.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"ergonomics","verdict":"strength","statement":"Rider triangle rated best in class.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"ergonomics","verdict":"weakness","statement":"Shift lever is short and hard to get a boot under.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"ergonomics","verdict":"weakness","statement":"Cockpit details draw complaints: narrow stock bar, thin seat foam or slippery seat cover, and large, hard grips.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"known issue","verdict":"weakness","statement":"Recall (April 2026): the handlebar clamp can let the bar rotate unexpectedly on about 12,600 US 2025-2026 CRF250R/RX/Works Edition and CRF450R/RX/Works Edition bikes; stop riding until a dealer inspects and replaces the clamp free (check the VIN on Honda's recall lookup).","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"engine_low","verdict":"neutral","statement":"The low-end torque is so strong it can be hard to control on some tracks; shift early because it signs off past its peak.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"weight_feel","verdict":"strength","statement":"Feels the lightest of its class on the track despite a wet weight in the high 240s.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"weakness","statement":"Hydraulic clutch has a narrow, on/off engagement that contributes to occasional stalling.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"brakes","verdict":"weakness","statement":"Brakes are not up to the European bikes' standard.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"electronics","verdict":"weakness","statement":"Three settings each for map, launch and traction control with flash codes and no phone app confuse riders.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"known issue","verdict":"weakness","statement":"Radiator boils over in hard use on the stock 1.1 cap.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"durability","verdict":"weakness","statement":"Muffler dents easily from boots.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"air_filter","verdict":"weakness","statement":"The new triangular air filter is small.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"neutral","statement":"Stock 13/49 is close; some testers prefer 13/50.","years":[2025,2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Fork soft on big jumps and under braking","fix":"Add 2-3 clicks of fork compression, adjust fork height (most went to flush-2.5 mm) and add about half a turn of shock high-speed compression","result":"Better balance and hold-up on big jumps","support":5},{"problem":"Too soft for heavier riders","fix":"Stiffer springs: about 5.1 N/mm fork and 54 N/mm shock over about 190 lb; stiffer shock spring over about 220 lb","result":"More support, less pitching and better chassis feel","support":5},{"problem":"Fast and pro riders want more support","fix":"Send fork and shock out for firmer valving","result":"Firmer setting suited to pace; owners report most harshness gone when combined with clamps","support":3},{"problem":"Harsh and unstable on fast hard-pack","fix":"Aftermarket 23.5 mm offset clamps","result":"More flex, calmer chassis and better edge comfort; flat-corner exits less planted until the forks were raised","support":2},{"problem":"Harsh chassis feel","fix":"Lower axle, clamp-pinch, pivot and shock-bolt torques slightly with thread locker","result":"More compliance for one tester; owners report only partial improvement","support":2},{"problem":"Boiling over","fix":"1.8 high-pressure radiator cap in place of the stock 1.1","result":"Stopped boil-over","support":1}],"disagreements":[{"topic":"High-speed chassis calm","sides":["Most tests call the 2025-on chassis stable and largely bug-free.","One tester still found it harsh and unstable on fast hard-pack, some owners report a kicking rear on edgy tracks, and one 2026 shootout found it slightly front-heavy in rough high-speed sections."]},{"topic":"Pitching","sides":["One magazine found the stiffer rising-rate linkage makes it less pitchy.","Other testers found it busy and pitchy between acceleration and braking."]},{"topic":"Front-end weight","sides":["One shootout called it well balanced since the 2025 frame stiffening.","Another found it slightly front-heavy in rough high-speed sections."]},{"topic":"Airbox backfire screen","sides":["One magazine found removing the backfire screen made almost no difference.","A tester found a replacement cage added low-rpm response and freer revving, about a slip-on's worth."]},{"topic":"Fork height for bottoming resistance","sides":["Most testers slid the forks toward flush-2.5 mm and added compression.","One test instead raised the tubes in the clamps to help bottoming resistance."]}]},{"years":[2027],"generation":"2027 (all-new engine, frame and suspension)","summary":"Early tests only. Testers say the new engine keeps the low end but now revs, with more mid and top, less vibration and taller gearing, and the slipper-style clutch eases corner entry. The chassis is calmer and more composed in rough sections than the 2025-2026, curing much of its pitching, though turn-in takes a little more effort and it can still hunt for lines in the rough. Stock suspension is plush and well controlled. Electronics and cockpit details draw minor complaints.","points":[{"aspect":"engine","verdict":"strength","statement":"Smoother and more linear with less vibration; keeps the strong low end but now revs with much more mid and top and no surge, and taller gearing means fewer shifts.","years":[2027],"support":2,"strength":"consensus"},{"aspect":"stability","verdict":"strength","statement":"Calmer and more composed in whoops and rough ground; the front holds up better from acceleration to braking, curing the 2025-2026 pitching, and it is far more stable on smooth tracks.","years":[2027],"support":2,"strength":"consensus"},{"aspect":"clutch","verdict":"strength","statement":"New slipper-style clutch cuts compression braking and makes corner entry easier.","years":[2027],"support":1,"strength":"single source"},{"aspect":"handling","verdict":"weakness","statement":"In rough sections it can still hunt for lines.","years":[2027],"support":1,"strength":"single source"},{"aspect":"turning","verdict":"neutral","statement":"Turn-in takes more effort than the 2026, but it is more planted once in the corner.","years":[2027],"support":1,"strength":"single source"},{"aspect":"suspension","verdict":"strength","statement":"Plush and well controlled with less mid-stroke harshness.","years":[2027],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"neutral","statement":"Standard map works best in deep dirt; the smooth map is too soft there.","years":[2027],"support":1,"strength":"single source"},{"aspect":"electronics","verdict":"weakness","statement":"Changing maps means holding the button for several seconds at idle; it cannot be done on the fly.","years":[2027],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Stock grips are harsh and bulky and the seat cover is slippery under acceleration.","years":[2027],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Bike not level for a heavier rider","fix":"Slide the forks down 2.5 mm and soften shock high-speed compression a quarter turn","result":"Bike sat level (200 lb tester)","support":1},{"problem":"Unsettled in rough sections","fix":"The usual Honda fix (softer rear, forks flush) was too much; going back to stock with the fork slightly stiffer and the shock slightly slower worked better","result":"Better balance in the rough","support":1}],"disagreements":[{"topic":"Aggressive map","sides":["One test found it adds over-rev with the same low end and is usable full time in good traction.","Another found it signs off earlier than standard."]}]}],"Honda|CRF450RWE":[{"years":[2021,2022,2023,2024],"generation":"2021-24 Works Edition (CRF450RWE)","summary":"The Works Edition's ported head, titanium full exhaust and own mapping smooth the standard bike's steep hit and add a few hp across the upper range, which testers say makes it faster and easier to ride. Its suspension uses the standard springs (and mostly the same valving) with low-friction coatings, so it rides lower and feels soft, especially at the rear. It shares the standard bike's nervous, setup-sensitive chassis, and 2021 bikes needed the same dealer ECU reflash. Stiffer rear springs, linkage and clamp changes were the common fixes.","points":[{"aspect":"engine","verdict":"strength","statement":"Porting, pipe and mapping smooth the standard bike's steep mid hit and tame the chassis; faster and easier to ride than the standard bike, quieter and cleaner-running.","years":[2021,2022,2023,2024],"support":3,"strength":"strong consensus"},{"aspect":"dyno","verdict":"strength","statement":"Measures more than the standard bike: about 2-2.5 hp more at peak on two magazine dynos, the most peak power of any 450 one magazine tested in 2021, and the strongest production 450 up to 7,500 rpm in 2024.","years":[2021,2022,2023,2024],"support":3,"strength":"strong consensus"},{"aspect":"known issue","verdict":"weakness","statement":"2021 Works Editions shared the standard bike's low-rpm mapping glitch and are covered by Honda's free dealer ECU reflash.","years":[2021],"support":3,"strength":"strong consensus"},{"aspect":"suspension","verdict":"weakness","statement":"Same springs and mostly the same valving as the standard bike, but the low-friction coatings let it sit deeper in the stroke; both ends feel soft, and the soft rear makes it busy into fast corners for riders over about 180 lb.","years":[2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"handling","verdict":"weakness","statement":"Very light-feeling and supercross-quick, but the front is sensitive and it can get nervous suddenly; setup has to be right.","years":[2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"suspension_rear","verdict":"weakness","statement":"Shock is harsh accelerating out of corners.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"neutral","statement":"The mild map only trims peak and over-rev rather than softening the bottom, because the bike is a bit sleepy down low; traction control tames it in soft soil.","years":[2022],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"strength","statement":"Comes with an aftermarket clutch basket and higher-volume clutch cover from the factory.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Fork-guard bolts pack with dirt and the guards cannot hold a holeshot device; grips are thick and the levers awkwardly shaped.","years":[2023],"support":1,"strength":"single source"},{"aspect":"known issue","verdict":"weakness","statement":"A 14-tooth countershaft sprocket can damage the clutch slave cylinder on 2021 bikes.","years":[2021],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Soft, low-riding rear","fix":"Stiffer shock spring (54 to 56 N/mm), or more rear preload; one spring rate up at each end for riders over about 180 lb","result":"Settled the bike and cured the sudden nervousness for several testers","support":2},{"problem":"Shock harsh accelerating out of corners","fix":"Aftermarket linkage (linear early, progressive late) with matched valving","result":"Harshness roughly halved","support":1},{"problem":"Engine braking and on/off feel","fix":"Aftermarket ECU","result":"Less engine braking; third gear lugs on stock gearing","support":1},{"problem":"Knifing in ruts and bar vibration","fix":"23.5 mm offset clamps","result":"Less vibration, oversteer and harshness","support":1},{"problem":"Low-rpm mapping glitch (2021)","fix":"Honda dealer ECU reflash","result":"Clean running","support":3}],"disagreements":[{"topic":"Preferred map after the 2021 reflash","sides":["One magazine's testers preferred the standard map.","Another magazine's testers mostly preferred map 2."]}]},{"years":[2025,2026],"generation":"2025-26 Works Edition (CRF450RWE)","summary":"Built on the 2025 chassis, the Works Edition's pipe, polished ports and own mapping make the power more linear with a gentler fall-off on top and clean, pop-free fueling, and it out-pulls the standard bike from about 4,200 rpm to the limiter on the dyno. Its coated fork moves more freely and can feel like more brake dive, while the 18 mm shaft shock is firmer under power than the standard bike. Testers added fork damping, and heavier riders went up a spring rate. It is part of the April 2026 handlebar-clamp recall.","points":[{"aspect":"engine","verdict":"strength","statement":"More linear power with a gentler fall-off on top than the standard bike, with clean fueling, no pops or hiccups and little stall risk; on the dyno it out-pulls the standard bike from about 4,200 rpm to the roughly 11,500 rpm limiter.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"suspension","verdict":"neutral","statement":"Coated fork moves quicker and feels softer mid-stroke than the standard bike, which can feel like more brake dive; the 18 mm shaft shock is firmer on the throttle than the standard bike's softer end stroke.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"known issue","verdict":"weakness","statement":"Recall (April 2026): the handlebar clamp can let the bar rotate unexpectedly on about 12,600 US 2025-2026 CRF250R/RX/Works Edition and CRF450R/RX/Works Edition bikes; stop riding until a dealer inspects and replaces the clamp free (check the VIN on Honda's recall lookup).","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"cost","verdict":"neutral","statement":"Costs about $2,900 more than the standard bike, roughly what the matching aftermarket exhaust, clutch parts and head porting would cost.","years":[2025],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Coated fork moves too freely, more brake dive","fix":"Add fork compression and rebound damping (about 8-10 out compression, 8-9 out rebound) with forks flush-2 mm","result":"Calmer front","support":2},{"problem":"Soft for heavier riders or soft east-coast soil","fix":"Heavier springs (5.1-5.2 N/mm fork, 54-56 N/mm shock) for riders over about 180-185 lb; on stock springs in soft soil run stiffer clickers","result":"Rides higher in soft dirt that sucks the bike down","support":1},{"problem":"Chassis harshness","fix":"Slightly lower chassis bolt torques (axle, clamp pinch bolts, swingarm pivot)","result":"More compliance","support":1}],"disagreements":[]}],"Honda|CRF250R":[{"years":[2020,2021],"generation":"2020-2021 (twin-muffler engine, 2020 frame and suspension update)","summary":"A high-revving 250 whose strength is top-end and over-rev; most US testers still found the bottom end soft and slow-revving out of corners despite Honda's 2020 low-end changes. The 2020 clutch update made the clutch a strong point and the Showa suspension was rated plush and easy to set up, though faster or heavier riders found the fork divey and the shock empty on G-outs. Testers reported a twitchy front or head shake in rough ground (one cause was a steering-head nut left loose from the factory) and an engine that runs hot and pushes coolant. Aftermarket full exhausts and a plug-in ECU were the usual low-end fixes.","points":[{"aspect":"engine_low","verdict":"weakness","statement":"Bottom end feels soft and slow-revving; power comes in late and the clutch is needed to wake it up out of corners, so it needs a gear lower and more shifting than rivals.","years":[2020,2021],"support":3,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"strength","statement":"Pulls hard at high rpm and over-revs further than most rival 250Fs; it rewards being kept on the boil.","years":[2020,2021],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"strength","statement":"Showa suspension is plush, comfortable on decel bumps and easy to set up for an average rider.","years":[2020,2021],"support":3,"strength":"strong consensus"},{"aspect":"stability","verdict":"weakness","statement":"Front can feel twitchy, knife into corners or shake at speed in rough ground, especially for lighter riders.","years":[2020,2021],"support":2,"strength":"consensus"},{"aspect":"clutch","verdict":"strength","statement":"The 2020 clutch update (stiffer springs, better fibres, more oil) stopped the slipping of earlier bikes and made the clutch a strong point.","years":[2020,2021],"support":2,"strength":"consensus"},{"aspect":"mapping","verdict":"weakness","statement":"The three stock maps feel too similar to one magazine; one tester chose the aggressive map for corner torque and the standard map for longer pull in second and third.","years":[2020,2021],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"For fast or 160-190 lb riders the fork dives under hard braking and the shock runs out of support at the end of the stroke on G-outs; over about 190 lb a spring rate up at each end is needed.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"known issue","verdict":"weakness","statement":"Steering-head bearing can come too loose from the factory, causing knifing in corners and slight head shake on deceleration.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"turning","verdict":"strength","statement":"Quick turning with no wag, rated its best trait by one magazine.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"known issue","verdict":"weakness","statement":"Runs hot when idling or in long high-rpm motos, sand or heat and can push coolant out of the overflow, despite the 2020 radiator change.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"strength","statement":"Second-to-third spacing improved for 2020 so third is usable.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"weight","verdict":"weakness","statement":"About 10 lb heavier than the lightest 250F; the twin mufflers add weight and replacement cost.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"weakness","statement":"Rear fender can break if used to lift the bike and engine-cover paint scratches on the first ride.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"brakes","verdict":"neutral","statement":"Front brake is powerful; the rear pedal sits low.","years":[2020],"support":1,"strength":"single source"},{"aspect":"starts","verdict":"strength","statement":"Launch control works well on tacky gates with the stronger 2020 bottom end; keep 1-2 cm of clutch freeplay for starts.","years":[2020],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"weakness","statement":"An aftermarket dual-pipe system's header springs broke twice in 22 hours; replace them every 8-10 hours.","years":[2020,2021],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Weak bottom end out of corners","fix":"Aftermarket full exhaust system (slip-ons or quiet inserts lose most of the benefit)","result":"Better bottom and low-mid pull and quicker second/third recovery, so a higher gear can be held; no top-end loss","support":1},{"problem":"Weak bottom end","fix":"Plug-in aftermarket ECU with tuned maps","result":"More low-end grunt and longer-pulling gears than any exhaust tested","support":1},{"problem":"Third gear hard to use","fix":"One tooth larger rear sprocket (13/49)","result":"Third gear usable in corners, at some cost to second","support":1},{"problem":"Fork dive and head shake","fix":"Stiffer fork compression and forks raised from 5 mm to about 3 mm in the clamps (back toward flush if it shakes); for oversteer lower the sag first, then drop the forks","result":"Calmer front on braking and corner entry","support":2},{"problem":"Shock empty on G-outs","fix":"High-speed compression about 1/8 turn in and sag around 100-103 mm; slower low-speed and rebound rather than more high-speed (which loads the front)","result":"Rear held up better; 105 mm sag added stability but slowed turning","support":2},{"problem":"Twitchy front, knifing","fix":"Snug the steering-head nut","result":"Front settled","support":1},{"problem":"Running hot","fix":"Check coolant often, do not idle in the pits; aftermarket water-pump cover and impeller","result":"Less heat stress","support":1},{"problem":"Clutch feel and life","fix":"Aftermarket clutch pack in the stock basket","result":"Better lever feel, longer life, less slip in soft dirt","support":1},{"problem":"Square-edge harshness","fix":"Stock engine-mount torques, swingarm pivot at 52 ft-lb","result":"More lean-angle compliance","support":1}],"disagreements":[{"topic":"Bottom-end strength","sides":["Most US tests found the low end soft and lethargic.","One Australian test of the 2020 found it pulled early with a strong midrange."]},{"topic":"Cornering feel","sides":["One magazine rated quick, wag-free turning its best trait.","One tester found the 2020 harder to hold leaned mid-corner than the 2019, though more stable."]}]},{"years":[2022,2023,2024],"generation":"2022-2024 (single exhaust, low-mid engine, CRF450R-style frame)","summary":"The 2022 redesign swapped the old top-end character for much stronger bottom and midrange pull and made the bike one of the lightest 250Fs, but the engine falls off early on top and trails the class on peak power. Most testers found the chassis rigid and touchy, with a twitchy front and head shake that needs setup work, though it corners very well. The stock Showa fork was widely called too stiff and harsh while the shock felt soft, and both ends react to single-click changes. Common fixes are fork oil and valving changes, slower shock low-speed and rebound, longer-offset clamps, a high-pressure radiator cap and a tooth more on the rear sprocket.","points":[{"aspect":"engine_low","verdict":"strength","statement":"Much stronger bottom-to-mid pull than the 2020-2021 bike; it exits corners with little clutch and lugs third gear more easily.","years":[2022,2023,2024],"support":5,"strength":"strong consensus"},{"aspect":"stability","verdict":"weakness","statement":"Frame feels rigid and touchy: twitchy front, mid-corner oversteer and head shake in rough ground, especially for lighter riders, with fore-aft balance hard to find.","years":[2022,2023,2024],"support":4,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Measured peak power sits at or near the bottom of the 250F class and below the 2020-2021 bike.","years":[2022,2023,2024],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Stock fork is firm and harsh, especially late in the stroke and for riders under about 170 lb, while the shock is softer, leaving the bike unbalanced; valving was unchanged for three years.","years":[2022,2023,2024],"support":3,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Power falls off after the midrange and lacks over-rev, so a lower gear is often needed in corners.","years":[2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"mapping","verdict":"neutral","statement":"Standard map (map 1) is the usual pick; map 3 adds snap down low but signs off sooner on top.","years":[2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"balance","verdict":"weakness","statement":"Very sensitive to single clicks, especially shock high-speed compression: stiffening it puts weight on the front and makes the fork harsher.","years":[2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"tires","verdict":"weakness","statement":"Stock 100/90-19 rear tire is too narrow for the engine's low-end and gives up grip at lean; the stock tires also wear quickly.","years":[2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"reliability","verdict":"strength","statement":"Build quality rated highly: the revised water pump stopped coolant loss and owners report valves staying in spec past 40 hard hours.","years":[2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"clutch","verdict":"strength","statement":"Nine-plate cable clutch holds up to abuse.","years":[2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"weight_feel","verdict":"strength","statement":"About 8-10 lb lighter than the 2021 after dropping the second muffler; one magazine measured it the lightest 250F of 2024.","years":[2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"gearing","verdict":"weakness","statement":"Third gear is short so riders often skip to fourth.","years":[2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"turning","verdict":"strength","statement":"Rated one of the best-cornering 250Fs and forgiving on the throttle while leaned over.","years":[2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"weakness","statement":"Owners still name the stock clutch (one at about 45 hours) and the stock chain as the first wear items.","years":[2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"known issue","verdict":"weakness","statement":"Stock 1.1 radiator cap lets it overheat when worked hard.","years":[2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"known issue","verdict":"weakness","statement":"Upside-down air filter gets dirty quickly in dust; check it often.","years":[2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"weakness","statement":"Seat foam breaks down in about 10-12 hours.","years":[2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"sound","verdict":"weakness","statement":"Stock muffler is loud and harsh.","years":[2022,2023,2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Harsh, stiff fork","fix":"Lower fork oil about 5 cc per leg, soften compression and quicken rebound; revalve for lighter riders","result":"Less harshness deep in the stroke and better balance with the shock","support":3},{"problem":"Soft shock, poor acceleration hold-up","fix":"Slower shock low-speed compression and rebound instead of more high-speed compression","result":"More hold-up and exit traction without loading the front","support":2},{"problem":"Twitchy front and head shake","fix":"Longer-offset clamps (23.5-24 mm vs stock 22 mm), correct springs, 105-108 mm sag and forks near flush; some added a steering damper; avoid raising the forks","result":"More stability on fast and rough tracks","support":2},{"problem":"Harsh rising-rate rear","fix":"Aftermarket linkage with a more linear rate","result":"Plush start to the stroke that ramps up later","support":1},{"problem":"Short third gear","fix":"13/51 gearing","result":"Third usable in corners","support":1},{"problem":"Lacks top end","fix":"Aftermarket full exhaust","result":"Kept the low end and added midrange, top and quicker recovery; second gear pulls longer","support":1},{"problem":"Overheats when worked hard","fix":"1.8 high-pressure radiator cap","result":"Holds coolant in hard use","support":1},{"problem":"Seat foam collapses","fix":"Firmer aftermarket foam","result":"Lasts longer","support":1},{"problem":"Clutch and chain wear","fix":"Aftermarket clutch pack; replace the stock chain early","result":"Longer life","support":1}],"disagreements":[{"topic":"Stock fork firmness","sides":["Most tests found the fork too stiff and harsh.","One 2022 shootout found it too soft with a light rear and added compression."]},{"topic":"Top-end character","sides":["Several tests found it falls off early with a short top end.","One 2022 shootout found it linear and over-revving well, and one long-term test said it still revs to about 14,000 rpm."]},{"topic":"Chassis feel","sides":["Several tests called the frame rigid, harsh and nervous.","One tester found it forgiving leaned over and less rigid than the CRF450R."]},{"topic":"Cooling","sides":["One tester found the 2022 pump and louvers cured coolant loss.","Another recommends a higher-pressure cap because it overheats when worked hard."]},{"topic":"Clutch durability","sides":["Testers say the nine-plate clutch survives abuse.","Owners name the stock clutch as the most common early wear item."]}]},{"years":[2025,2026],"generation":"2025-2026 (stiffer new frame, revised airbox, linkage and suspension)","summary":"Testers broadly agree the 2025 frame fixed much of the earlier nervousness: the bike is more planted, precise and stable with less pitching, corners excellently and still feels light. The engine is strong off the bottom but goes flat on top where the Austrian bikes and the Kawasaki pull, measuring roughly 3-4 hp down, so most riders prefer the aggressive map. Suspension is plusher than before but soft for riders over about 175 lb or fast riders, and the stock Pirelli tires (especially the 100/90 rear) are widely criticised. The 2025-2026 bikes are covered by an April 2026 handlebar-clamp recall.","points":[{"aspect":"engine_low","verdict":"strength","statement":"Strong off the bottom; easier to drive out of ruts and hold third gear than earlier bikes.","years":[2025,2026],"support":5,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Mid-to-top pull and over-rev trail the Austrian 250s and the KX250 and it goes flat where they come alive; peak power measures roughly 3-4 hp down and below the 2019-2021 bikes.","years":[2025,2026],"support":5,"strength":"strong consensus"},{"aspect":"stability","verdict":"strength","statement":"More planted and precise with less pitching and front wiggle on entry; needs less effort to hold a line in braking bumps.","years":[2025,2026],"support":5,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Both ends are soft for riders over about 175 lb, fast riders or very rough tracks; the shock squats under acceleration.","years":[2025,2026],"support":5,"strength":"strong consensus"},{"aspect":"mapping","verdict":"neutral","statement":"Aggressive map is the most common pick on the stock bike for its extra hit and pull.","years":[2025,2026],"support":4,"strength":"strong consensus"},{"aspect":"turning","verdict":"strength","statement":"Excellent cornering and front-end traction with very quick, light steering; arguably the best-handling 250 in its class and it fits a wide range of rider sizes.","years":[2025,2026],"support":4,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"strength","statement":"Fork is plusher over small bumps with a linear ramp; the shock stays planted under power and the setup is comfortable yet controlled.","years":[2025,2026],"support":4,"strength":"strong consensus"},{"aspect":"tires","verdict":"weakness","statement":"Stock Pirelli tires lose grip at lean, the 100/90-19 rear is too small and the front wears out fast; testers want a 110 rear.","years":[2025,2026],"support":4,"strength":"strong consensus"},{"aspect":"stability","verdict":"neutral","statement":"Can feel harsh in the forearms, busy under braking or twitchy in long choppy corners until fork height, clickers and clamp torque are adjusted.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"weight_feel","verdict":"strength","statement":"Feels very light and easy to scrub and whip.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"gearing","verdict":"weakness","statement":"First and second feel long and there is a big gap into a third gear that revs out quickly, forcing early shifts to fourth.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"known issue","verdict":"weakness","statement":"Recall (April 2026): the handlebar clamp can let the bar rotate unexpectedly on about 12,600 US 2025-2026 CRF250R/RX/Works Edition and CRF450R/RX/Works Edition bikes; stop riding until a dealer inspects and replaces the clamp free (check the VIN on Honda's recall lookup).","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"brakes","verdict":"strength","statement":"Revised front caliper gives a smoother, more linear feel.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"neutral","statement":"Wider midsection grips well but tall riders' legs can catch the shrouds in deep ruts.","years":[2025,2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Busy front, instability","fix":"Lower the forks from the stock height toward 2-3 mm or flush and run about 103-108 mm sag","result":"Better cornering and stability","support":2},{"problem":"Fork soft as the track roughens or on hard-pack","fix":"Add 2-4 clicks of fork compression (and a couple of clicks of rebound on hard-pack)","result":"Holds up better in braking bumps; cured instability on hard-pack","support":3},{"problem":"Too soft for heavier riders","fix":"Stiffer springs for riders over about 180 lb (no revalve needed per one test); fork revalve for heavier or fast intermediate riders","result":"Better hold-up","support":2},{"problem":"Shock squats on acceleration","fix":"Stiffer shock low-speed compression and slower rebound (avoid stiffening high-speed, which made the front harsh)","result":"More support and corner traction","support":2},{"problem":"Rear tire too narrow","fix":"110/80-19 rear on a 2.15 rim","result":"More rear grip","support":2},{"problem":"Forearm harshness","fix":"Lower triple-clamp pinch-bolt torque (check service manual minimums)","result":"Less harshness and better front tire feel","support":1},{"problem":"Lacks top end","fix":"Aftermarket full exhaust, run with the standard map","result":"Felt about 2 hp stronger with better bottom, mid and over-rev","support":1}],"disagreements":[{"topic":"Preferred map","sides":["Most testers prefer the aggressive map.","Another found the aggressive map tops out quickly and preferred standard."]},{"topic":"Top-end feel","sides":["Most testers say it lacks top-end punch.","One magazine's dyno runs looked better on top than expected, and a long-term tester said it did not feel slow on track."]},{"topic":"Bottom-end torque","sides":["Most say it is strong off the bottom.","An Australian test wanted more torque out of turns in deep mud, and a heavy long-term tester found it soft off the bottom."]},{"topic":"Opening the airbox","sides":["One magazine saw no dyno gain from removing the filter cover and backfire screen.","A long-term test bike felt sharper response after removing the screen and enlarging the airbox hole, done together with an ECU remap."]},{"topic":"Gear spacing","sides":["One magazine liked stock gearing and changed nothing.","Other tests found first and second long and a gap to third that revs out quickly."]}]}],"Honda|CRF250RWE":[{"years":[2025,2026],"generation":"2025-26 Works Edition (CRF250RWE)","summary":"The 250 Works Edition adds ported ports, a titanium exhaust, its own mapping, coated suspension with an 18 mm shock shaft, a hydraulic clutch and Dunlop tires to the 2025 chassis. Testers agree it keeps pulling on top where the standard bike goes flat, though it still trails the Austrian 250s off starts and up hills and gives up a little very low down. The coated suspension moves more freely early and holds up slightly better deep in the stroke. It is part of the April 2026 handlebar-clamp recall.","points":[{"aspect":"engine_top","verdict":"strength","statement":"Keeps power climbing where the standard 2025 CRF250R goes flat: snappier, quicker-revving and better over-rev; on the dyno it gains from about 5,400 rpm to the limiter.","years":[2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"suspension","verdict":"strength","statement":"Coated fork and 18 mm shaft shock move more freely early in the stroke and hold up a little better deep than the standard bike; one tester wanted it calmer at speed on the throttle.","years":[2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"engine","verdict":"weakness","statement":"Still slower than the Austrian 250s off starts and up hills, and gives up a little power around 3,900-5,100 rpm versus the standard bike.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"mapping","verdict":"neutral","statement":"Testers ran the aggressive map.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"clutch","verdict":"neutral","statement":"Hydraulic clutch (the standard bike has a cable) feels normal quickly, though cable fans may miss the engagement feel.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"tires","verdict":"strength","statement":"Its Dunlop tires and 110/90-19 rear suit western dirt much better than the standard bike's Pirellis.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"known issue","verdict":"weakness","statement":"Recall (April 2026): the handlebar clamp can let the bar rotate unexpectedly on about 12,600 US 2025-2026 CRF250R/RX/Works Edition and CRF450R/RX/Works Edition bikes; stop riding until a dealer inspects and replaces the clamp free (check the VIN on Honda's recall lookup).","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"known issue","verdict":"weakness","statement":"Stock 1.1 radiator cap was swapped immediately; seat foam is thin and the bars are crowded with the clutch master cylinder and switches.","years":[2025,2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Overheating risk","fix":"1.8 high-pressure radiator cap","result":"Holds coolant","support":1},{"problem":"Quick-moving suspension busy on throttle at speed","fix":"Fork compression 9 out, rebound 11 out at 4 mm height; shock low-speed 7 out, rebound 10 out at 105 mm sag (160-190 lb)","result":"Calmer at speed","support":1}],"disagreements":[]}],"Honda|CRF250RX":[{"years":[2020,2021],"generation":"2020-2021 (off-road version of the twin-muffler CRF250R)","summary":"Two full tests. Handling and turning are outstanding and the suspension is plush with little brake dive, but the engine is a revver with a weak bottom that can stall in tight going. The clutch faded in a muddy race, it boils over with heavy clutch use, and the twin mufflers lack spark arrestors. A spark-arrested aftermarket system added bottom end.","points":[{"aspect":"engine","verdict":"weakness","statement":"Still a top-end revver with weak bottom-end pull and some stalling in tight terrain; the mild map only tames the top.","years":[2020,2021],"support":2,"strength":"consensus"},{"aspect":"handling","verdict":"strength","statement":"Outstanding handling and turning; suspension is excellent, slightly softer than the motocross bike, sits tall with little brake dive.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"known issue","verdict":"weakness","statement":"Boils over with heavy clutch use on warm days.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"weakness","statement":"Clutch faded badly and wore quickly in a muddy cross-country race and needed adjuster turns to regain bite.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"exhaust","verdict":"weakness","statement":"Twin mufflers with no spark arrestors double the cost of making it trail-legal; no handguards stock.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"The 2.2-gallon tank feels top-heavy when full.","years":[2020,2021],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Weak bottom end, no spark arrestors","fix":"Aftermarket stainless full system with spark arrestors","result":"Added bottom end","support":1},{"problem":"Boiling over","fix":"Aftermarket water-pump impeller and waterless coolant","result":"Stopped boil-overs","support":1}],"disagreements":[]},{"years":[2022,2023,2024],"generation":"2022-2024 (off-road version of the 2022 CRF250R)","summary":"Off-road testers like the RX engine: it pulls low, hits hard in the midrange and lets riders stay in a higher gear on tight trails, with the aggressive map the favourite. Its softer springs and valving are plush, more user-friendly than the stiff motocross bike and good in rocks, but too soft for grand-prix pace without extra compression. Testers also mention a firm clutch pull, a wide tank and a wish for a sixth gear.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Broad engine that pulls from low rpm, hits hard in the midrange and tolerates being a gear high while still revving.","years":[2022,2023,2024],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"strength","statement":"Softer springs and valving are plush on track and trail, excellent in rocks and more user-friendly than the noticeably stiff motocross bike.","years":[2022,2023,2024],"support":3,"strength":"strong consensus"},{"aspect":"suspension_rear","verdict":"weakness","statement":"Too soft for grand-prix speed: the fork wants a few clicks more compression and the shock is soft relative to the fork.","years":[2022,2023,2024],"support":3,"strength":"strong consensus"},{"aspect":"mapping","verdict":"neutral","statement":"Riders preferred the aggressive map, especially for uphills and motocross.","years":[2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"weight","verdict":"strength","statement":"The 2022 RX weighed about 7 lb less than the 2021 on the same scale.","years":[2022],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"weakness","statement":"Clutch pull feels firm.","years":[2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Oversized fuel tank is noticeable when putting a leg out.","years":[2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"weakness","statement":"Five-speed gearbox shared with the motocross bike; off-road testers want a sixth gear.","years":[2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"known issue","verdict":"weakness","statement":"Stock 1.1 radiator cap lets it overheat when worked hard; the upside-down air filter clogs quickly in dust.","years":[2022,2023,2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Fork dives on big hits at speed","fix":"Stiffen fork compression 1-2 clicks (or more) so it rides higher","result":"Holds up better without losing much plushness","support":3},{"problem":"Harsh in tight rocks","fix":"Soften compression 2-3 clicks at both ends","result":"Smoother in slow technical terrain","support":1},{"problem":"Unstable at speed","fix":"Add sag (107-108 mm) and lower the forks 1-3 mm in the clamps","result":"More stability without giving up much cornering","support":1}],"disagreements":[]},{"years":[2025,2026],"generation":"2025-2026 (2025 frame, airbox and suspension update)","summary":"Off-road testers rate the 2025 RX's engine the best-mannered of the cross-country 250Fs: torque-rich below 7,000 rpm with no stalling, though a few hp shy at peak. The 2025 frame and one-piece pull rod make it more comfortable and predictable than the 2022-2024, and a mostly stock bike survived a 24-hour race. The suspension suits a moderate-pace rider of about 170 lb, with the fork feeling softer than the shock. Complaints are the wide tank, the five-speed gearbox, the stock front tire and a cable clutch that fades when abused. It is part of the April 2026 handlebar-clamp recall.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Best off-road delivery of the cross-country 250Fs: strong below 7,000 rpm with no tendency to stall or cough, and the off-road map softens the transition into the main power; the top end signs off earlier and peak is about 3-4 hp shy of the fastest 250s.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"neutral","statement":"Fork feels softer than the shock on big hits now that the shock holds up better.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"gearing","verdict":"weakness","statement":"Five-speed gearbox works on trails but testers miss a taller sixth gear for fire roads.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"known issue","verdict":"weakness","statement":"Recall (April 2026): the handlebar clamp can let the bar rotate unexpectedly on about 12,600 US 2025-2026 CRF250R/RX/Works Edition and CRF450R/RX/Works Edition bikes; stop riding until a dealer inspects and replaces the clamp free (check the VIN on Honda's recall lookup).","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"chassis","verdict":"strength","statement":"The 2025 frame and one-piece pull rod add comfort and predictability over the rigid 2022-2024 chassis, with less rider fatigue.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"suspension","verdict":"neutral","statement":"Setup suits a rider of about 170 lb at moderate trail pace; too soft for motocross or desert speed and too stiff for light riders in tight trails.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"durability","verdict":"strength","statement":"A mostly stock 2025 RX ran a full 24-hour race with only tip-over damage and a bent shifter.","years":[2025],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"The 2.1-gallon tank is wide and carries fuel high, so handling changes noticeably from full to empty.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"tires","verdict":"weakness","statement":"Stock front tire gives poor grip.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"weakness","statement":"Cable clutch has an easy pull but fades if abused.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Arm fatigue on long rides, blamed on the aluminium chassis.","years":[2025,2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Fork low under big hits","fix":"Two clicks more fork compression and 104-105 mm sag, or springs matched to rider weight","result":"Fork held higher in the stroke while staying plush; better front-rear balance","support":2},{"problem":"Arm fatigue","fix":"Lower triple-clamp pinch-bolt torque and soften fork and shock high-speed compression","result":"Less harshness through the bars","support":1},{"problem":"Poor front grip","fix":"Swap the stock front for a better intermediate tire","result":"More front traction","support":2}],"disagreements":[{"topic":"Fork compression direction","sides":["One tester stiffened fork compression to hold it up.","Another softened high-speed compression over several rides for comfort."]},{"topic":"Chassis comfort","sides":["One test found the 2025 frame cut fatigue versus the old bike.","A long-term tester still had arm fatigue and blamed the aluminium chassis."]},{"topic":"Hydraulic clutch conversion","sides":["One test says converting needs machine work with no bolt-on kit.","Another says it can be done with OEM parts from the 250 Works Edition."]}]}],"Honda|CRF450RX":[{"years":[2020],"generation":"2020 (off-road version of the 2017-generation CRF450R)","summary":"Only one full test plus a dyno run on the same engine. Its huge, throbbing low end is great for grand-prix and desert racing but hard to manage in tight, rocky trails, with a constant stall risk, and the stock radiator cap lets it steam in clutch-heavy riding. Suspension is a little softer than the motocross bike yet resists bottoming well. The wide tank, tall first gear and lack of handguards are the other complaints.","points":[{"aspect":"power_delivery","verdict":"neutral","statement":"Huge, throbbing power that gets more frantic up top: great in grand-prix and desert racing but hard to control in tight, rocky trails, with a constant stall risk; the mild map and traction control do not smooth the low end.","years":[2020],"support":1,"strength":"single source"},{"aspect":"dyno","verdict":"strength","statement":"Made the most power of the 450 off-road bikes on one magazine dyno (measured on the identical 2019 engine).","years":[2020],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"strength","statement":"A little softer than the motocross bike, well suited to grand-prix racing; stays up in the stroke and takes a big hit to bottom.","years":[2020],"support":1,"strength":"single source"},{"aspect":"known issue","verdict":"weakness","statement":"Starts steaming within minutes of first-gear or clutch-heavy riding on the stock 1.1 radiator cap.","years":[2020],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"The 2.25-gallon tank is wide and cumbersome on technical rides, first gear is tall for trails and no handguards are fitted.","years":[2020],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Head shake in desert racing","fix":"Fit a steering stabilizer","result":"Recommended for desert speed","support":1}],"disagreements":[]},{"years":[2021,2022,2023,2024],"generation":"2021-2024 (off-road version of the 2021 CRF450R)","summary":"Testers call the RX a very tractable, torque-led engine that is strong but can be tiring in tight trails; the 2023 update moved the hit lower and made it more gradual. It turns quickly and precisely, and its softer suspension is supple in whoops and rocks but too soft for big jumps and fast or heavy riders. Complaints include the wide, top-heavy tank, traction control that can bog on loose hills, and a chassis some found stiff or prone to moving around at speed. Early 2021 bikes needed Honda's free mapping reflash.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Very tractable, torque-led engine that feels slightly detuned versus the motocross bike; strong, but can be tiring or too much in tight technical trails.","years":[2021,2022,2023,2024],"support":4,"strength":"strong consensus"},{"aspect":"ergonomics","verdict":"weakness","statement":"The 2.1-gallon tank is wide and top-heavy, making the bike feel bulkier and less nimble and getting in the way when putting a leg out.","years":[2021,2022,2023,2024],"support":3,"strength":"strong consensus"},{"aspect":"known issue","verdict":"weakness","statement":"Early 2021 RXs share the CRF450R's mid-throttle hiccup and popping; Honda's free dealer ECU reflash fixes it.","years":[2021],"support":2,"strength":"consensus"},{"aspect":"power_delivery","verdict":"weakness","statement":"The 2021-2022 engine had a hard rush between about 7,500 and 8,500 rpm that felt light-switch-like.","years":[2021,2022],"support":2,"strength":"consensus"},{"aspect":"power_delivery","verdict":"strength","statement":"From 2023 the hit moved to the bottom and ramps up more gradually, making it much easier to ride and all three maps useful, at the cost of some peak power.","years":[2023,2024],"support":2,"strength":"consensus"},{"aspect":"turning","verdict":"strength","statement":"Turns quickly and precisely, stable in sand berms; rut cornering is its most consistent trait.","years":[2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"strength","statement":"Softer valving with the same springs as the R gives a supple, forgiving initial stroke that is great in whoops and rocky trails.","years":[2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"suspension","verdict":"weakness","statement":"Too soft for heavier or faster riders and overwhelmed by big jumps and speed on a motocross track.","years":[2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"chassis","verdict":"weakness","statement":"Chassis can feel stiff, and the frame can bind and unload, moving the bike side to side at speed.","years":[2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Fork has a harsh top-out feel.","years":[2024],"support":1,"strength":"single source"},{"aspect":"stability","verdict":"strength","statement":"Feels less rigid and more planted than the CRF450R.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"strength","statement":"Hydraulic clutch has one of the lightest pulls in the class and never fades.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"weakness","statement":"Hydraulic clutch pull is firm and engagement too on/off.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"electronics","verdict":"weakness","statement":"Traction control helps on flat, dry, rocky ground but is inconsistent and can make the bike go flat on loose or sandy hills; map button flash order is confusing and launch control is useless for dead-engine starts.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"strength","statement":"Reliability proved solid over a long test with a good clutch and brakes.","years":[2022],"support":1,"strength":"single source"},{"aspect":"known issue","verdict":"weakness","statement":"Stalls and overheats when ridden slowly in tight trails.","years":[2022],"support":1,"strength":"single source"},{"aspect":"weight","verdict":"strength","statement":"Only about 5 lb heavier than the R despite the kickstand and handguards; the handguards and sealed chain are good quality.","years":[2021],"support":1,"strength":"single source"},{"aspect":"service","verdict":"neutral","statement":"Airbox vent can take in water at crossings; tape it over first.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"tires","verdict":"weakness","statement":"Stock rear tire spins in sand.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Unstable at speed","fix":"Add sag (about 107-108 mm) and lower the forks in the clamps or run them flush; 23.5 mm offset clamps","result":"More stability without giving up much cornering","support":2},{"problem":"Too soft for fast riders or jumps","fix":"Stiffer grand-prix valving, or the motocross bike's stiffer rear spring","result":"Holds up at race pace","support":2},{"problem":"Front heavy in tight trails","fix":"Raise the forks up to 5 mm in the clamps","result":"Quicker steering in tight going","support":1},{"problem":"Stiff-feeling chassis","fix":"Aftermarket engine hangers","result":"More comfort and traction","support":1},{"problem":"Rear spins in sand","fix":"Sand-specific rear tire","result":"Better drive in sand","support":1},{"problem":"Drag on deceleration","fix":"Swap the O-ring chain for a standard motocross chain","result":"Less drag, freer deceleration","support":1}],"disagreements":[{"topic":"Clutch feel","sides":["One magazine found the hydraulic clutch among the lightest in the class and fade-free.","Another tester found the pull firm and the engagement on/off."]},{"topic":"Chassis at speed","sides":["One tester found it less rigid and more planted than the R.","Others found it stiff or prone to side-to-side movement at speed."]}]},{"years":[2025,2026],"generation":"2025-2026 (2025 frame and airbox update)","summary":"Little tester data. The stiffer 2025 frame makes it very planted and secure at speed while still steering quickly, and testers no longer needed to drop the forks. Opinions split on the engine: one test found the new airbox softened the hit and cut stalling, another said it still hits like a motocross bike at trials-type speeds. Suspension is only a little softer than the R and soft for big jumps. It is part of the April 2026 handlebar-clamp recall.","points":[{"aspect":"handling","verdict":"strength","statement":"Stiffer frame makes it very planted and secure at speed despite light, quick steering; the forks no longer need dropping in the clamps.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"suspension","verdict":"neutral","statement":"Only a little softer than the R; it settles into the stroke and soaks up chatter but is soft for big motocross jumps.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"known issue","verdict":"weakness","statement":"Recall (April 2026): the handlebar clamp can let the bar rotate unexpectedly on about 12,600 US 2025-2026 CRF250R/RX/Works Edition and CRF450R/RX/Works Edition bikes; stop riding until a dealer inspects and replaces the clamp free (check the VIN on Honda's recall lookup).","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"power_delivery","verdict":"strength","statement":"Torque-first delivery with a softer hit, cleaner fueling and fewer low-rpm stalls than before.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"power_delivery","verdict":"weakness","statement":"Even in the softest map it has a motocross-style hit; at very low speed first gear hits too hard and second wants to stall, demanding lots of clutch.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"neutral","statement":"Smooth map with the strongest traction setting makes it feel like a 350, good for tight single-track; standard or aggressive suit loam and sand.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"weakness","statement":"Five-speed gearbox; off-road testers want a sixth gear.","years":[2025,2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Unstable at speed","fix":"Add sag (107-108 mm) and lower the forks in the clamps","result":"More stability without giving up much cornering","support":1}],"disagreements":[{"topic":"Low-speed engine manners","sides":["One test found the 2025 airbox softened the hit and reduced stalling.","Another found it still hits hard and wants to stall at trials-type speeds even in the softest map."]}]}],"Honda|CRF150R":[{"years":[2020,2021,2022,2023,2024,2025,2026],"generation":"2020-2026 (carbureted four-stroke, platform largely unchanged since 2007)","summary":"Little tester data. The carbureted 150 revs quickly but has little low-end torque, stalls easily and trails European 85cc two-strokes on power-to-weight; the kick-start is hard for some kids. Stock suspension is harsh at slow speeds and needs springs and valving for heavier riders. A tuner's jetting only raises the pilot jet.","points":[{"aspect":"engine","verdict":"weakness","statement":"Light flywheel lets it rev quickly, but it has little low-end torque, slows fast off the throttle, stalls easily and trails European 85cc two-strokes on power-to-weight.","years":[2020,2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"ergonomics","verdict":"weakness","statement":"Kick-starting is hard for some kids.","years":[2024],"support":1,"strength":"single source"},{"aspect":"suspension","verdict":"weakness","statement":"Stock valving is harsh at slow speed and on trails; heavier riders need stiffer springs and a revalve.","years":[2020,2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"service","verdict":"neutral","statement":"Engine and transmission oil are drained separately (every 10-15 hours); stale pump gas left in the carburettor is a common cause of starting problems.","years":[2020,2021,2022,2023,2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Jetting baseline","fix":"Keep stock main (138), needle (clip 3) and leak jet; raise the pilot from 38 to 45 (premium pump gas, 0-1,500 ft)","result":"Tuner baseline jetting","support":1},{"problem":"Stalls, little low end","fix":"Flywheel weight, auto-clutch or jetting changes","result":"Fewer stalls","support":1},{"problem":"Hard starting after storage","fix":"Drain the carburettor and fuel before storage","result":"Avoids stale-fuel starting problems","support":1}],"disagreements":[]}],"KTM|450 SX-F":[{"years":[2020,2021,2022],"generation":"2019-2022 generation (AER/XACT air fork)","summary":"Testers describe a smooth, linear 450 that builds power progressively and is easy to ride, though next to the Japanese 450s it can feel short on snap off the bottom. Handling is rated accurate and stable, but the stock air fork and rigid clamps draw complaints about harshness, while tuners also find the stock air setting too soft for fast riders. The 2021 fork update made the frame feel less rigid and the 2021 maps became easier to tell apart. Most fixes are about adding low-end response (exhaust flange, ECU, race fuel) and taking harshness out of the front end.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Engine builds power smoothly and linearly from low to high rpm, which makes it easy and tiring-free to ride.","years":[2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"engine_low","verdict":"weakness","statement":"Low-end hit is mild; next to Japanese 450s it can feel sleepy and testers wanted more response and snap off corners.","years":[2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"mapping","verdict":"neutral","statement":"For 2021 the two maps became easier to tell apart, with the aggressive map adding mid and top power rather than sharper throttle response.","years":[2021,2022],"support":2,"strength":"consensus"},{"aspect":"chassis","verdict":"neutral","statement":"Frame is on the stiff side, which faster riders like more than vets; the 2021 fork update made the chassis feel less rigid.","years":[2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Stock air fork and rigid stock clamps feel harsh, especially mid-stroke on braking bumps, and pass vibration to the hands.","years":[2020,2021],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"neutral","statement":"Stock and recommended air settings are too soft for fast riders on rough tracks; tuners run more air or revalve.","years":[2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"weakness","statement":"Neutral is hard to find when stopped; easiest method is selecting it as revs drop with the clutch in.","years":[2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"stability","verdict":"strength","statement":"Accurate and stable, needing little steering input; rated the best all-round handler of its years.","years":[2020,2021,2022],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"Air pressure climbs on hot days (about 10 psi from morning to race time), so the fork must be checked and bled every moto.","years":[2021],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"weakness","statement":"Rear sits low under acceleration and feels harsh off corners; stock shock fades when hot late in long motos.","years":[2021],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"neutral","statement":"Hardware needs regular checks: rear sprocket bolts, spokes by the rim lock, head-stay and engine-mount bolts, shift lever and linkage nut.","years":[2020,2021,2022],"support":1,"strength":"single source"},{"aspect":"other","verdict":"weakness","statement":"Runs hot in hot conditions.","years":[2021],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Engine smooth but lacks low-end snap","fix":"Aftermarket exhaust flange (no remap)","result":"Better mid-to-exit response and third-gear lugging","support":1},{"problem":"Wants more pull and over-rev","fix":"Aftermarket ECU with tuner maps","result":"Stronger corner exits and could hold third longer","support":1},{"problem":"Low-end response on pump fuel","fix":"Oxygenated race fuel on the stock map","result":"More low-end pull and response within a few laps","support":1},{"problem":"Harsh front end and vibration","fix":"Split triple clamps with more flex","result":"More comfort and front contact while staying precise in ruts","support":1},{"problem":"Rear harsh under squat on square edges","fix":"Floating axle blocks with a different axle","result":"More compliance and traction; allowed stiffer low-speed compression","support":1},{"problem":"Rear sits low and harsh on corner exits","fix":"Shock shaft 1 mm longer and a slightly longer pull rod","result":"Rear stayed higher, sag could return to 103-105 mm and the bike balanced","support":1},{"problem":"Setup too soft for fast riders","fix":"Stiffer mid-valve and low-speed stack, shock bladder, progressive linkage","result":"More control and hold-up at some cost to initial plushness","support":1},{"problem":"Slightly short on high-rpm breathing","fix":"Vented airbox cover","result":"About 1 hp more near peak on the dyno; use the solid cover in mud or dust","support":1}],"disagreements":[{"topic":"Stock fork character","sides":["Feels harsh in mid-stroke and over braking bumps","Stock and recommended settings are too soft for fast riders"]}]},{"years":[2023,2024,2025,2026],"generation":"2023+ generation (new engine and frame; flexier frame from 2025)","summary":"Testers agree the current 450 SX-F engine is one of the strongest in the class yet broad and easy to use, with power building steadily from low rpm to a strong mid and top. The 2023-2024 chassis was widely criticised as stiff and harsh until well broken in, and the 2025 frame, linkage and mount changes are credited with making it more compliant and stable. The stock air fork gets mixed reviews: comfortable to some, harsh on small braking bumps or limiting at a high level to others, and the shock can go deep and bottom hard. Owners and tuners lean toward coil conversions, aftermarket linkages, softer engine mounts and clamps, and careful chain slack and pivot torque.","points":[{"aspect":"chassis","verdict":"weakness","statement":"The 2023-2024 frame feels stiff and harsh, deflects over braking bumps and needs roughly 8-10 hours to settle; it also feels heavier at the front.","years":[2023,2024],"support":4,"strength":"strong consensus"},{"aspect":"power_delivery","verdict":"strength","statement":"Broad, linear power that is very strong from the middle to the top but still easy to manage in tight turns or a high gear.","years":[2023,2024,2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"strength","statement":"Measures among the most powerful stock 450s on the dyno.","years":[2023,2024,2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"stability","verdict":"strength","statement":"From 2025 the chassis is more compliant in rough ground while staying stable and accurate, with no head shake and good rear traction.","years":[2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"engine_low","verdict":"weakness","statement":"Off-idle and low-end feel is criticised: one tester found the early stock map jerky at low rpm with a hit that upset the bike in ruts, another found less low-end intensity than the Japanese 450s.","years":[2023,2024],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"weakness","statement":"Strong engine braking and noticeable high-rpm vibration through stiff bars.","years":[2024,2025],"support":2,"strength":"consensus"},{"aspect":"mapping","verdict":"neutral","statement":"Quickshifter helps on long starts but feels quirky at half throttle and on jump faces, so some riders leave it off.","years":[2023,2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Air fork is harsh on small braking bumps and its pressure drifts, hurting consistency; a harsh spot in mid-stroke is a common complaint.","years":[2023,2024,2025],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"neutral","statement":"Once broken in, testers run more fork air than the stock setting (around 10.8-10.9 bar) because the stock setting feels too soft.","years":[2023,2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"suspension_rear","verdict":"weakness","statement":"Shock can go too deep in its stroke and bottom hard at the end, and may kick sideways on big hits.","years":[2023,2024],"support":2,"strength":"consensus"},{"aspect":"ergonomics","verdict":"weakness","statement":"Cockpit feels cramped and the seat tall for short riders; shock clickers sit hidden behind the side panel.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"maintenance","verdict":"neutral","statement":"Chain slack should be kept around 68-70 mm; tighter chains eat the swingarm buffer pad and load the suspension.","years":[2023,2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"engine_top","verdict":"neutral","statement":"Aftermarket full exhaust systems add mid-to-top pull but soften or slightly reduce the low-end hit.","years":[2023],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"strength","statement":"Places in the top three of 450 shootouts.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"mapping","verdict":"neutral","statement":"Traction control is mainly useful on hard, slick or wet tracks and adds little in loam.","years":[2023,2024,2025,2026],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"strength","statement":"2025 linkage and frame give more rear feedback, compliance and traction.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"brakes","verdict":"strength","statement":"Brakes are powerful.","years":[2025],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"neutral","statement":"Spokes near the rear rim lock loosen often; check before every ride.","years":[2023,2024,2025,2026],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Linkage needle bearings can walk out and bind; 2023 start/stop switch could let water short the ECU; rear brake pedal tip bends easily (strengthened for 2025).","years":[2023,2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Air fork harsh and inconsistent","fix":"Coil cartridge conversion (for example a valved WP 6500 kit) or lighter spring plus air with reduced damping","result":"More comfort, lean traction and consistency; valved coil kits named as the biggest single fix","support":3},{"problem":"AER soft once broken in but harsh with more air","fix":"Raise fork oil level and lower air pressure","result":"Hold-up without the harshness of simply adding air","support":1},{"problem":"Rear goes deep and kicks on big bumps","fix":"Aftermarket linkage (softer initial, more progression, rear about 5 mm higher)","result":"Calmer rear with better traction","support":2},{"problem":"Rigid 2023-2024 chassis","fix":"Medium-flex engine mounts, 23.5 mm offset split clamps, flexier bar, swingarm pivot at 95 Nm","result":"Less slap-down harshness and vibration, better lean grip and less deflection","support":1},{"problem":"Stock map jerky off idle / wants more pull","fix":"Aftermarket ECU or reprogrammed ECU with per-gear mapping","result":"Smoother low end, stronger mid-top and less engine braking","support":2},{"problem":"Linkage feels dead","fix":"Replace needle bearings with caged KTM bearing 58033097000","result":"Linkage moves freely again","support":1}],"disagreements":[{"topic":"Which map testers prefer","sides":["Aggressive map 2 (2023-2024 race tests, one 2024 dyno tester)","Mellow map 1 (2025-2026 race tests, one 2023 launch test)"]},{"topic":"Stock air fork on the 2026 bike","sides":["Comfortable, resists bottoming and is balanced","Holds the bike back at the top level"]}]}],"Husqvarna|FC 450":[{"years":[2020,2021,2022],"generation":"2019-2022 generation; lowered chassis from 2021","summary":"Testers describe the FC 450 as smooth and soft off the bottom, building predictably and deceptively fast, with a restrictive intake that makes it more lethargic than the KTM. The 2021 lowered chassis turns very well and is rated a top handler, but one tester found it unbalanced and harsh on chop, and the stock shock spring soft for heavier riders. The stock air fork drew repeated complaints about harshness and inconsistency, with sticker settings too soft. Cheap intake mods, linkage changes and brake-pedal spring fixes are common.","points":[{"aspect":"power_delivery","verdict":"neutral","statement":"Soft off the bottom, then builds predictably and linearly with no surges; deceptively fast, but less exciting than the KTM 450.","years":[2020,2021,2022],"support":4,"strength":"strong consensus"},{"aspect":"turning","verdict":"strength","statement":"The 2021-2022 lowered chassis corners very well and feels smaller; rated better turning than the KTM 450.","years":[2021,2022],"support":2,"strength":"consensus"},{"aspect":"mapping","verdict":"strength","statement":"The 2020 ECU cured the rich-low, lean-top feel of the 2019; the 2020 Rockstar Edition ECU adds low-rpm response and cuts engine braking.","years":[2020],"support":1,"strength":"single source"},{"aspect":"balance","verdict":"weakness","statement":"The lowered 2021 chassis can feel unbalanced with the rear lower than the front, harsh on chop, and the frame can touch rut walls.","years":[2021],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"Stock air fork harsh and inconsistent through a moto; sticker settings too soft for a 190 lb rider.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"weakness","statement":"Shock spring too soft for heavier riders: squats mid-corner and blows through in whoops.","years":[2021,2022],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"weakness","statement":"Stock rear rigid on acceleration chop and kicks on decel bumps.","years":[2020],"support":1,"strength":"single source"},{"aspect":"stability","verdict":"neutral","statement":"22 mm offset clamps were the best all-round choice; 20 mm turns in easier but hunts on throttle; 24 mm is most stable but lazy.","years":[2020],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Rear brake pedal return spring breaks every 4-5 hours, stock bar mounts bend, and throttle cables wear by about 20 hours.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"2022 composite subframes cracked at the lower right bolt hole and the fuel quick-release O-ring can tear.","years":[2022],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Wants more low-end snap","fix":"Screenless two-stroke filter cage or cutting out the backfire screen; exhaust flange","result":"More low-end response for little money","support":2},{"problem":"Lowered 2021 chassis unbalanced","fix":"Aftermarket linkage (different pull rod and knuckle)","result":"Rear raised and the bike balanced","support":1},{"problem":"Stock rear harsh on chop","fix":"Aftermarket linkage with 48 N/mm spring, 103 mm sag","result":"Rode higher with more traction and control on braking bumps","support":1},{"problem":"Air fork inconsistent","fix":"Hybrid coil/air fork conversion or revalve","result":"Spring-fork small-bump comfort with air-fork bottoming resistance","support":1},{"problem":"Rear brake spring breaks","fix":"Honda CRF450R rubber-covered spring or aftermarket return spring kit","result":"Spring no longer breaks","support":1},{"problem":"Chassis stiff when leaning on the throttle","fix":"Remove one upper engine-mount bolt, torque others to 30 Nm; pivot at 95 Nm","result":"More flex; can be too flexy in deep tilled dirt","support":1},{"problem":"Shock kicks on decel","fix":"High-speed compression in 1/4 turn and sag kept near 95-105 mm","result":"Calmer rear without hurting the fork","support":1}],"disagreements":[]},{"years":[2023,2024,2025],"generation":"2023+ generation (lowered version of the KTM platform; no 2026 US model)","summary":"The current FC 450 shares the KTM engine but its closed-off airbox gives a smoother, softer low end; testers still rate it the strongest or among the strongest 450s and very manageable. Its lower chassis earns praise for cornering, stability and fitting shorter riders. The weak spot testers keep finding is the rear: it rides low and deep, can bottom on big hits and the stock spring feels soft for heavier or faster riders. The air fork works but divides riders and needs setup knowledge.","points":[{"aspect":"turning","verdict":"strength","statement":"Low ride height helps it carve flat turns and ruts with excellent traction while staying stable and accurate.","years":[2025],"support":3,"strength":"strong consensus"},{"aspect":"suspension_rear","verdict":"weakness","statement":"Rear rides low and deep: it squats mid-corner, can feel harsh and bottoms on landings or big hits, and the stock spring is soft for heavier or fast riders.","years":[2023,2024,2025],"support":3,"strength":"strong consensus"},{"aspect":"power_delivery","verdict":"strength","statement":"Among the most powerful 450s yet broad and manageable even for less skilled riders.","years":[2025],"support":2,"strength":"consensus"},{"aspect":"engine_low","verdict":"neutral","statement":"Closed-off airbox makes it smoother and mellower low-to-mid than the KTM, which feels brisker.","years":[2023,2024,2025],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"neutral","statement":"Air fork works but is setup-sensitive and divides riders.","years":[2025],"support":2,"strength":"consensus"},{"aspect":"ergonomics","verdict":"strength","statement":"About an inch lower than the KTM; suits short riders without bothering tall ones.","years":[2023,2024,2025],"support":1,"strength":"single source"},{"aspect":"chassis","verdict":"strength","statement":"The 2025 frame no longer needs a long break-in and feels plusher.","years":[2025],"support":1,"strength":"single source"},{"aspect":"brakes","verdict":"strength","statement":"Powerful one-finger front brake with wide modulation.","years":[2025],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"neutral","statement":"Needs about 70 mm chain slack; spokes near the rim lock loosen; shroud blocks the shock clickers.","years":[2025],"support":1,"strength":"single source"},{"aspect":"engine_top","verdict":"neutral","statement":"Special-edition titanium slip-on gave no peak power gain over the standard bike on one dyno.","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Rear rides deep and bottoms","fix":"Stiffer shock spring (48 N/mm over about 190 lb), or slide forks out in the clamps and reduce sag","result":"Rear sits higher and stops blowing through; clickers alone were only a stopgap","support":2},{"problem":"Shock bottoms at end of stroke","fix":"About five more clicks of low-speed compression","result":"Helped control bottoming","support":1},{"problem":"Slow throttle response from closed airbox","fix":"Vented airbox cover","result":"Sharper response","support":1},{"problem":"Shock clickers hard to reach","fix":"Cut an access hole in the shroud","result":"Clickers reachable without removing plastics","support":1}],"disagreements":[{"topic":"Rear suspension quality","sides":["Rear is excellent / chassis plusher","Rear rides low, harsh and bottoms on big hits"]}]},{"years":[2027],"generation":"2027 model (first ride only)","summary":"Only one early first ride exists. Testers found it smooth on the first part of the throttle and then strong, physically demanding, and less settled on rough ground unless ridden fast and committed.","points":[{"aspect":"power_delivery","verdict":"neutral","statement":"Smooth on the first part of the throttle, then builds strongly; the most physically demanding bike in the range.","years":[2027],"support":1,"strength":"single source"},{"aspect":"stability","verdict":"weakness","statement":"Less settled on rough ground unless ridden at a fast, committed pace.","years":[2027],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]}],"GasGas|MC 450F":[{"years":[2021,2022,2023],"generation":"2021-2023 (KTM 2019-2022 platform)","summary":"The first GasGas MC 450F is a KTM 450 SX-F engine and frame with cheaper parts and restrictions: a nearly sealed airbox cover, a header with no resonance chamber, muffler restrictors and no map switch. Testers consistently find it weaker and less racy off the bottom than the KTM, though it builds well through the middle and its peak power is competitive. Forged clamps and softer valving make it comfortable but vaguer to steer and too soft for fast riders.","points":[{"aspect":"engine_low","verdict":"weakness","statement":"Weaker and less racy off the bottom than the KTM because of the sealed airbox, plain header and muffler restrictors.","years":[2021,2022,2023],"support":3,"strength":"strong consensus"},{"aspect":"engine_mid","verdict":"strength","statement":"Builds strongly through the middle; peak power is close to the KTM and competitive with rival 450s.","years":[2022],"support":2,"strength":"consensus"},{"aspect":"mapping","verdict":"weakness","statement":"No handlebar map switch: it runs the mellow map only until an accessory switch is fitted.","years":[2021,2022],"support":2,"strength":"consensus"},{"aspect":"turning","verdict":"weakness","statement":"Forged clamps flex more than billet ones: comfortable in rough ground but vague at turn-in, with tip-in oversteer then mid-corner push.","years":[2021,2022],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"neutral","statement":"Softer valving than the KTM: too soft for fast riders and felt poor for the first few hours.","years":[2021,2022],"support":2,"strength":"consensus"},{"aspect":"reliability","verdict":"weakness","statement":"Rim-lock spokes loosen quickly; about half the test bikes had one loose.","years":[2022],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Weak bottom-to-mid response","fix":"Cut the winglet off the airbox cover or fit a KTM vented cover","result":"Better breathing and bottom-to-mid pull","support":1},{"problem":"Front pushes / vague turn-in","fix":"Clamp pinch bolts 20 Nm top, 15 Nm bottom, or billet clamps","result":"Sharper steering","support":1},{"problem":"Only one map","fix":"Plug in the KTM map switch (about $180)","result":"Access to map 2, traction and launch control","support":1}],"disagreements":[{"topic":"2022 brake supplier","sides":["Race test says the GasGas shares the KTM's Brembo brakes","Later recall notices cover Braktec front calipers on 2022 GasGas MCs"]}]},{"years":[2024,2025,2026],"generation":"2024+ (KTM 2023+ platform)","summary":"On the current KTM platform the MC 450F is the mellow, budget sibling: testers find it fun and easy, but its closed airbox, restricted exhaust and single stock map blunt response and top-end pull, and it measures a bit below the KTM on the dyno. Softer valving and forged clamps make it compliant, so testers run more fork air than on the KTM. Opinions split on its Braktec brakes and on whether the fork is comfortable or harsh.","points":[{"aspect":"power_delivery","verdict":"weakness","statement":"Closed airbox, restricted muffler and the single stock map blunt response and top-end pull; it measures slightly below the KTM on the same dyno.","years":[2024,2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"neutral","statement":"Valving is softer than the KTM's, so testers add fork air (around 10.6-10.9 bar).","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"power_delivery","verdict":"strength","statement":"Mellow and fun with usable power everywhere; testers often ride it harder than the stronger KTM.","years":[2024,2025],"support":1,"strength":"single source"},{"aspect":"turning","verdict":"strength","statement":"2024 chassis changes direction and cuts under ruts easily.","years":[2024],"support":1,"strength":"single source"},{"aspect":"tires","verdict":"weakness","statement":"Stock Maxxis tires lack side-knob grip.","years":[2024],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"strength","statement":"Torque values printed on key bolts, few bolt lengths and one Torx size for bodywork.","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Dull response and single map","fix":"Drill or replace the airbox cover and fit the accessory map switch","result":"Sharper response and access to the aggressive map","support":1}],"disagreements":[{"topic":"Braktec brakes","sides":["Strong with no fade even for a brake dragger","Less power and feel than Brembo"]},{"topic":"Stock air fork","sides":["Softer and compliant","Needs constant adjusting and harsh on small and big hits"]},{"topic":"Chassis feel from forged clamps","sides":["Slightly more compliant than the KTM","Cast clamp and bars pass excess feedback"]}]}],"KTM|350 SX-F":[{"years":[2020,2021,2022],"generation":"2019-2022 generation","summary":"Testers describe the previous-generation 350 SX-F as an engine that picks up quickly, pulls steadily and must be revved further than riders expect, yet can also be short-shifted like a 450. The 2021 aggressive map added midrange but felt less crisp than the 450's. In deep sand the stock air-fork setup rides deep and pitches, so testers and owners add compression and fine-tune air and sag. Small annoyances include a long-throw throttle cam, hard-to-find neutral and electrical niggles on 2022 bikes.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Flexible engine: it rewards revving well past where you would normally shift but also tolerates short-shifting like a 450.","years":[2020,2021],"support":2,"strength":"consensus"},{"aspect":"mapping","verdict":"neutral","statement":"On the 2021 bike map 1 is broad and easy with plenty of over-rev; map 2 pulls harder low and in the middle but goes flat sooner on top.","years":[2021],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"In deep sand or whooped, cupped tracks the stock setup rides deep and pitches, so riders add compression and adjust air and sag.","years":[2021,2022],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"weakness","statement":"Neutral is hard to find when stopped.","years":[2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"weakness","statement":"Stock throttle cam has a very long throw; testers fit the quick-turn cam supplied with the bike.","years":[2020,2021,2022],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"2022 bikes: starter wire pulling out of its junction box, FI light falling out, preload ring chipping, bar mounts twisting and rear brake springs breaking.","years":[2022],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"neutral","statement":"Some owners hear a loud top-end rattle for a few seconds after a cold start or hot restart, usually blamed on the hydraulic cam-chain tensioner.","years":[2020],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Rides deep and pitches in sand and whoops","fix":"Stiffer compression and more fork air; 103-110 mm sag in deep sand","result":"Better hold-up and less air-fork harshness in soft terrain","support":2},{"problem":"Long-throw throttle","fix":"Fit the supplied quick-turn throttle cam","result":"Quicker throttle and less arm pump","support":1},{"problem":"G-outs on the shock","fix":"High-speed compression in 1/4 turn","result":"Fewer G-out bottoming hits","support":1}],"disagreements":[]},{"years":[2023,2024,2025,2026],"generation":"2023+ generation","summary":"Testers agree the current 350 SX-F picks up quickly, pulls harder through the middle than the old bike and makes its best power at the top, so it wants to be revved out. They describe it as pulling like a 450 out of corners while revving like a 250, less tiring than a 450 but weaker on long starts. The 2023-2024 chassis is stiff and harsh until broken in, the shock lacks end-stroke support for fast riders, and the 2025 frame is more comfortable. Common changes are the aggressive map, an extra rear sprocket tooth, an aftermarket ECU or remap, a linkage, and chain slack near 70 mm.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Picks up quickly off the bottom, pulls harder through the middle than the 2019-2022 engine and is strongest at the top, so it should be revved to the limiter.","years":[2023,2024,2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"power_delivery","verdict":"neutral","statement":"Pulls like a 450 out of corners and revs like a 250, but has less low-end grunt than a 450 and cannot pull tall gears the same way.","years":[2023,2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"weight_feel","verdict":"strength","statement":"Feels lighter and less tiring than a 450 even though claimed weights are almost the same, mainly due to softer delivery and less rotating mass.","years":[2024,2025],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"weakness","statement":"Starts are weaker than a 450 on long start straights.","years":[2023,2024],"support":2,"strength":"consensus"},{"aspect":"engine_top","verdict":"neutral","statement":"Peak power is a few hp short of most 450s and arrives well over 11,000 rpm, roughly 1,400-2,400 rpm higher than a 450.","years":[2025],"support":2,"strength":"consensus"},{"aspect":"mapping","verdict":"neutral","statement":"Most testers race the aggressive map 2 for a snappier, more 450-like feel; the standard map suits novices, vets and slick hard pack.","years":[2023,2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"chassis","verdict":"weakness","statement":"The 2023-2024 frame is stiffer and heavier, feels harsh until about 10 hours of break-in, but is stable under braking.","years":[2023,2024],"support":2,"strength":"consensus"},{"aspect":"suspension_rear","verdict":"weakness","statement":"Fast riders find the shock lacks end-stroke support and bottoms harshly.","years":[2023,2024],"support":2,"strength":"consensus"},{"aspect":"gearing","verdict":"neutral","statement":"Many testers add a rear sprocket tooth (some two) for more low-to-mid thrust or to use third in corners.","years":[2023,2024],"support":2,"strength":"consensus"},{"aspect":"maintenance","verdict":"neutral","statement":"Needs about 68-70 mm of chain slack; too little chews the swingarm buffer and loads the suspension.","years":[2023,2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"mapping","verdict":"weakness","statement":"Quickshifter can feel boggy at half throttle or on jump faces, so testers often turn it off.","years":[2023,2024],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"neutral","statement":"Traction control watches for runaway rpm, so it helps only in mud, rain or rock-hard slick dirt.","years":[2023,2024,2025,2026],"support":1,"strength":"single source"},{"aspect":"chassis","verdict":"strength","statement":"The 2025 frame is more comfortable and compliant than 2024 with the same geometry.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Swingarm pivot nut can back out from vibration; check it or use thread locker.","years":[2023,2024],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"neutral","statement":"Spokes near the rear rim lock loosen; small plastic radiator cap can loosen or be hard to open (threaded cap from 2026); neutral hard to find on the line.","years":[2023,2024,2025],"support":1,"strength":"single source"},{"aspect":"power_delivery","verdict":"weakness","statement":"Many owners report decel popping and some report low-rpm stalling in slow sections.","years":[2023,2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Wants more low-end snap and clean decel","fix":"Aftermarket ECU mapped for the exhaust and fuel, or a stock-ECU remap where available","result":"Crisper response, stronger mid and over-rev, less popping and engine braking","support":2},{"problem":"Shock bottoms at end of stroke","fix":"Aftermarket linkage, stiffer bumpers or more low-speed compression","result":"Better end-stroke support","support":2},{"problem":"Rear unsettled over acceleration bumps","fix":"Swingarm pivot bolt at 95 Nm (thread-locked)","result":"Rear settles and tracks straighter","support":1},{"problem":"Nervous at speed / vague in ruts","fix":"23.5 mm offset clamps","result":"Calmer straight-line and better front feel in ruts","support":1},{"problem":"Wants more mid pull","fix":"Full titanium exhaust","result":"More mid-rpm response and pull with stock-like over-rev, about 2 lb lighter","support":1},{"problem":"Low-to-mid throttle response","fix":"Vented airbox cover","result":"Better low-to-mid response","support":1},{"problem":"Decel popping","fix":"Raise TPS voltage slightly, check header seals, or remap","result":"Reported to reduce popping (no confirmed root cause)","support":1}],"disagreements":[{"topic":"What the aggressive map 2 does","sides":["Snappier off the bottom","Smoother off the bottom with less engine braking","Peaks later rather than harder"]},{"topic":"Aftermarket ECU vs stock-ECU remap","sides":["Aftermarket ECU worth it for extra maps and response","A cheap remap of the stock ECU gets most of the benefit"]}]}],"Husqvarna|FC 350":[{"years":[2020,2021,2022],"generation":"2019-2022 generation; lowered chassis from 2021","summary":"Testers describe the previous FC 350 as smooth, linear and sneaky fast with a big over-rev, broad and easy to modulate rather than torquey. The stock air fork needed attention: one tester found it soft and divey on decel, another short on initial comfort, and pressure had to be checked every ride. The lowered 2021-2022 chassis was rated a top handler. Intake screen removal, fork air changes and a stiffer shock spring for heavier riders are typical changes.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Smooth, linear and broad off the bottom with a big over-rev; easy to modulate and faster than it feels.","years":[2020,2022],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Stock air fork needs attention: soft and divey on decel for one tester, short on initial comfort for another, with pressure checks needed every ride.","years":[2020],"support":2,"strength":"consensus"},{"aspect":"engine_top","verdict":"neutral","statement":"Nearly matches a 450's top speed on the flat but loses out uphill; recovers better than a 450 when in the wrong gear.","years":[2020],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"weakness","statement":"Noticeable engine braking in second gear, much less in third.","years":[2020],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"weakness","statement":"Shock empties at the end of the stroke on G-outs and jump faces.","years":[2020],"support":1,"strength":"single source"},{"aspect":"turning","verdict":"strength","statement":"The lowered 2021-2022 chassis was rated best-handling, with a low centre of gravity and easy ground reach.","years":[2021,2022],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"2022 composite subframe cracked at the lower right bolt hole.","years":[2022],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Stock seat cover too grippy and bar low when standing.","years":[2020],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Fork soft and divey on decel","fix":"Add air (about 10.8 bar)","result":"More hold-up and comfort","support":1},{"problem":"Air fork lacks comfort and consistency","fix":"Coil conversion using KYB internals in the WP tubes","result":"More comfort, better front contact and bottoming control","support":1},{"problem":"Shock empties on G-outs","fix":"High-speed compression in 1/8-1/4 turn","result":"Balanced the bike","support":1},{"problem":"Restrictive intake","fix":"Cut out the backfire screen or fit a two-stroke filter cage","result":"Runs more like the KTM","support":1},{"problem":"Shock spring soft for a 190 lb rider","fix":"Go up to 45 N/mm (or 48)","result":"Suggested by owners; no tested outcome reported","support":1}],"disagreements":[{"topic":"Magura clutch feel versus the KTM's Brembo","sides":["Magura is smoother","Magura is more on/off"]}]},{"years":[2023,2024,2025],"generation":"2023+ generation (lowered KTM platform; no 2026 US model)","summary":"The current FC 350 shares the KTM engine and frame but sits lower, and testers rate it best of the three brands for handling, comfort and reaching the ground. Its closed airbox mutes low-end response compared with the KTM. The 2023 frame felt stiff and harsh until broken in, and on hard pack testers mostly reduced compression damping. Tuners note its valving differs from the KTM, so KTM settings do not carry over.","points":[{"aspect":"turning","verdict":"strength","statement":"Lower chassis gives the best handling and comfort of the three brands and makes it easy to touch the ground.","years":[2024],"support":1,"strength":"single source"},{"aspect":"engine_low","verdict":"weakness","statement":"Muted low-end response compared with the barkier KTM.","years":[2024],"support":1,"strength":"single source"},{"aspect":"chassis","verdict":"weakness","statement":"2023 frame is stiff and feels harsh until broken in; testers soften the fork to compensate.","years":[2023],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"neutral","statement":"On hard pack most testers reduced compression at both ends and tuned with clickers rather than air.","years":[2023],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"weakness","statement":"Testers often turn the quickshifter off.","years":[2023],"support":1,"strength":"single source"},{"aspect":"power_delivery","verdict":"weakness","statement":"One owner reported rich blubbering at quarter throttle and repeated stalling in a harescramble.","years":[2023],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Hydraulic clutch intermittently loses pressure","fix":"Check crankcase breather hose routing (often pinched after linkage service)","result":"Clutch works normally again","support":1}],"disagreements":[{"topic":"What the aggressive map does","sides":["Peaks later rather than harder","Snappier off the bottom"]}]}],"GasGas|MC 350F":[{"years":[2021,2022,2023],"generation":"2021-2023 (KTM 2019-2022 platform)","summary":"Few tester findings exist for the first-generation MC 350F. Testers found it lively low with a long rev, smoother off the bottom than the KTM 350 but harder than the Husqvarna, and lighter than both on the 2023 scale. It ran only the mellow map without an accessory switch.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Lively low and revs long; smoother off the bottom than the KTM 350 but harder-hitting than the FC 350.","years":[2023],"support":1,"strength":"single source"},{"aspect":"weight_feel","verdict":"strength","statement":"On the old platform it weighed about 5-6 lb less than the KTM or Husqvarna 350.","years":[2023],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"weakness","statement":"Only the mellow map without an accessory switch; no quickshift, traction or launch control.","years":[2023],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"neutral","statement":"Testers turned shock high-speed compression in a quarter turn to reduce G-out bottoming and ran more rebound than recommended.","years":[2023],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]},{"years":[2024,2025,2026],"generation":"2024+ (KTM 2023+ platform)","summary":"The current MC 350F shares the KTM engine, frame and wheels but uses forged clamps, softer damping, taller bars and Braktec brakes, and ships with only the mellow map. Testers find its low-end response muted by intake and exhaust restrictions, and its softer suspension suits hard pack and slower riders. Brake opinions split: some find the Braktec units strong, others say they lack modulation.","points":[{"aspect":"suspension_front","verdict":"neutral","statement":"Softer valving than the KTM; it works on hard pack and for slower riders.","years":[2024,2025],"support":2,"strength":"consensus"},{"aspect":"engine_low","verdict":"weakness","statement":"Intake and exhaust restrictions (no resonance chamber, muffler restrictor, small airbox vent) mute low-end response compared with the KTM.","years":[2024,2025],"support":1,"strength":"single source"},{"aspect":"power_delivery","verdict":"neutral","statement":"Second gear is punchy but it revs out and cannot pull third or fourth like a 450.","years":[2024],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"neutral","statement":"On slick hard pack one tester preferred the mellow map; the aggressive map had more punch low but less mid torque.","years":[2024],"support":1,"strength":"single source"},{"aspect":"turning","verdict":"strength","statement":"2024 chassis changes direction and cuts under ruts easily.","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Single mellow map","fix":"Accessory map switch (about $170-180)","result":"Unlocks the aggressive map, traction control, launch control and quickshifter","support":1},{"problem":"Abrupt second gear","fix":"One tooth smaller rear sprocket (51)","result":"Less abrupt second gear","support":1},{"problem":"Muted throttle response","fix":"Drill or replace the airbox cover; slip-on or KTM stock pipe","result":"Sharper response; peak power reportedly unaffected","support":1}],"disagreements":[{"topic":"Braktec brakes","sides":["Strong, no fade, as good as Brembo","Less modulation than Brembo"]}]}],"KTM|250 SX-F":[{"years":[2020,2021,2022],"generation":"2016-2022 engine (78 x 52.3 mm), 2019-2022 chassis","summary":"Testers describe the previous 250 SX-F as soft below about 6,000 rpm and then pulling harder and harder to a very high peak with long over-rev, rewarding riders who keep it revving. Stock gearing feels tall, so testers commonly go to a 13-tooth countershaft or add rear teeth. The air fork needs several hours to break in. Hardware such as the counterbalancer needle bearing and various bolts needed watching.","points":[{"aspect":"power_delivery","verdict":"neutral","statement":"Soft below about 6,000 rpm, then pulls harder to a peak near 13,400-13,900 rpm with long over-rev; it rewards aggressive riders and punishes lazy shifting.","years":[2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"gearing","verdict":"weakness","statement":"Stock 14/51 gearing feels tall and sluggish out of tight turns, especially for slower or heavier riders.","years":[2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"neutral","statement":"Air fork needs about 5-6 engine hours to break in; extra air helped hold-up on decel.","years":[2020,2021,2022],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Counterbalancer needle bearing could walk out (changed to a bushing for 2022); sprocket, head-stay and subframe bolts and the linkage nut could loosen.","years":[2020,2021,2022],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Sluggish out of tight turns","fix":"13-tooth countershaft or 14/52-14/53","result":"Better corner-exit surge and more use of third","support":2},{"problem":"Dip at 8,500-11,000 rpm","fix":"Vented airbox cover","result":"Filled the dip with almost no change at peak","support":1},{"problem":"Rear squats under throttle","fix":"Stiffer low-speed compression; 1/4 turn more high-speed if still soft at end of stroke","result":"Less squat and better end-stroke control","support":1}],"disagreements":[]},{"years":[2023,2024,2025,2026],"generation":"2023+ generation (81 x 48.5 mm engine, new frame)","summary":"Testers consistently describe the current 250 SX-F engine as quiet and very linear: less exciting off the bottom than a Yamaha or Honda, but with a strong midrange and a top end that keeps pulling after rivals sign off, giving the widest usable power window in the class. It wins or places second in most 250 shootouts. The air fork and the new frame feel stiff until broken in, and the fork's pressure drift means checks before every ride. Testers race the aggressive map with traction control off, fit the vented airbox cover and keep chain slack near 65-70 mm.","points":[{"aspect":"engine_top","verdict":"strength","statement":"Quiet, very linear engine with a strong midrange that does its best work above about 11,000 rpm and keeps pulling after rivals sign off, giving the widest usable power window in the class.","years":[2023,2024,2025,2026],"support":4,"strength":"strong consensus"},{"aspect":"engine_low","verdict":"weakness","statement":"Bottom end feels less exciting than a Yamaha or Honda; it needs revs and a big throttle opening to show its speed, so it feels slower than the dyno says.","years":[2023,2024,2025],"support":3,"strength":"strong consensus"},{"aspect":"other","verdict":"strength","statement":"Wins or places second in 250 four-stroke shootouts.","years":[2023,2024,2025],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Air fork pressure rises in the sun and while riding, so it must be set cold and bled before each ride; drift hurts consistency.","years":[2023,2024,2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"weight_feel","verdict":"neutral","statement":"About 6 lb heavier than the 2022 bike on the scale.","years":[2023],"support":2,"strength":"consensus"},{"aspect":"mapping","verdict":"neutral","statement":"Most testers race the aggressive map; the mellow map suits very light riders, novices or slick tracks.","years":[2023,2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"chassis","verdict":"weakness","statement":"Fork and frame feel stiff and harsh when new; testers allow about 6-10 hours of break-in before judging.","years":[2023,2024],"support":2,"strength":"consensus"},{"aspect":"suspension_rear","verdict":"neutral","statement":"The stock 42 N/mm shock spring suits riders up to about 175-180 lb; heavier riders go to 45 N/mm.","years":[2023,2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"mapping","verdict":"weakness","statement":"On 2023-2024 bikes traction control cut power by roughly a quarter and made the engine run rough, so testers leave it off; the 2025 update made it usable on wet or very hard tracks.","years":[2023,2024,2025],"support":1,"strength":"single source"},{"aspect":"stability","verdict":"strength","statement":"Frame squats less under power, pitches less under braking and is very stable; the 2025 frame reduced harshness in acceleration chop.","years":[2023,2024,2025],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"weakness","statement":"2023 shock is not firm enough at the very end of its stroke; more low-speed compression controls it.","years":[2023],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Linkage needle bearings can walk out and bind; spokes by the rear rim lock loosen during break-in; plastic radiator cap is hard to remove and has leaked.","years":[2023,2024,2025],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"neutral","statement":"Chain should run 65-70 mm slack at the buffer pad, which looks loose; tighter chains wear the buffer quickly.","years":[2023,2024,2025],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"neutral","statement":"A few owners report 2023 bikes turning hard to start cold, blamed on a stuck ring or tightening valves; a leak-down test is advised.","years":[2023],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Throttle response","fix":"Vented airbox cover","result":"Sharper response; on the older engine it filled a midrange dip","support":1},{"problem":"Rider will not rev the engine","fix":"One more tooth on the rear sprocket","result":"More low-rpm pull","support":1},{"problem":"Air fork harsh and inconsistent","fix":"Coil cartridge conversion","result":"Better hand comfort and ground-following with no pressure checks","support":2},{"problem":"Rear feels dead","fix":"Caged linkage bearing 58033097000","result":"Linkage moves freely","support":1},{"problem":"Chain buffer wears fast","fix":"Run 65-70 mm slack; aftermarket buffer pad","result":"Buffer lasts; 2025 raised the pad from the factory","support":1}],"disagreements":[{"topic":"2023 engine low end versus 2022","sides":["Slightly less snappy off the bottom","Noticeably punchier off the bottom","Character largely unchanged"]},{"topic":"2025 shootout ranking","sides":["First in class","Second behind the YZ250F"]}]}],"Husqvarna|FC 250":[{"years":[2020,2021,2022],"generation":"2016-2022 engine, 2019-2022 chassis; lowered from 2021","summary":"Testers describe the previous FC 250 as smooth and linear, mellow at the bottom and very fast when revved, and less snappy than the KTM because of its more restrictive airbox. Its stock gearing feels tall, the 2020 suspension settings came out too soft for most riders, and a light rider found the fork harsh on small chatter. A recurring list of KTM-family maintenance items applies, and the rear brake pedal spring breaks often.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Smooth and linear off the bottom, building to a big over-rev; easier and less snappy than the KTM and can be ridden a gear high.","years":[2020,2021,2022],"support":3,"strength":"strong consensus"},{"aspect":"engine_low","verdict":"weakness","statement":"Restrictive airbox makes it smoother and less aggressive than the KTM, even in the aggressive map.","years":[2021,2022],"support":2,"strength":"consensus"},{"aspect":"gearing","verdict":"weakness","statement":"Stock 14/51 feels sluggish; at least one more rear tooth or a 13-tooth countershaft is needed.","years":[2022],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"neutral","statement":"2020 settings came out too soft for most buyers; one light rider found the 2021 fork harsh on low-speed chatter.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Rear brake pedal spring breaks every 4-5 hours; throttle cables wear around 20 hours; spokes, engine-hanger and pivot bolts back out.","years":[2022],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Header sticks out and burns pants; stock bar low for a 6 ft rider.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"other","verdict":"neutral","statement":"Recommended over a 450 for most vets and weekend riders, even older ones.","years":[2020],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Wants more low-mid response","fix":"Screenless two-stroke filter cage, cutting the backfire screen, or drilling the vented cover","result":"Cheapest gain; runs more like the KTM","support":3},{"problem":"Low-speed chatter harsh for a light rider","fix":"Drop fork air to about 10.2 bar","result":"Fixed without bottoming","support":1},{"problem":"Fork soft and divey on decel","fix":"Add air (about 10.7 bar)","result":"More hold-up and comfort","support":1},{"problem":"Rear brake spring breaks","fix":"Honda CRF450R spring or aftermarket return spring","result":"Spring stops breaking","support":1},{"problem":"Fixed left axle block stiffens rear on throttle","fix":"Floating axle blocks","result":"More rear compliance","support":1}],"disagreements":[{"topic":"FC 250 power versus the identical KTM","sides":["Regularly out-dynos the KTM","Matches the KTM and falls behind above about 12,700 rpm"]},{"topic":"Magura clutch feel versus the KTM's Brembo","sides":["Magura is smoother","Magura is more on/off"]}]},{"years":[2023,2024,2025],"generation":"2023+ generation (lowered KTM platform; no 2026 model)","summary":"The current FC 250 uses the KTM engine, and on the dyno it matches the KTM, but its tightly closed airbox makes it softer and smoother off the bottom on the track; once on the pipe it pulls hard and wants to be revved. It sits about an inch lower, turns tighter and suits shorter, lighter and novice-to-vet riders, and testers set it up a bit stiffer than the KTM. The 2025 frame is calmer in acceleration chop and breaks in sooner. Shootout results range from second to fifth.","points":[{"aspect":"engine_low","verdict":"neutral","statement":"Same engine as the KTM, but the closed airbox makes it softer and smoother off the bottom; it pulls hard from the middle and wants high revs.","years":[2023,2024,2025],"support":3,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"neutral","statement":"Dyno numbers are essentially the same as the KTM's.","years":[2024,2025],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"neutral","statement":"Testers set it up stiffer than the KTM: one found the stock valving too soft for serious racing, another runs firmer settings because it sits lower.","years":[2023,2024,2025],"support":2,"strength":"consensus"},{"aspect":"turning","verdict":"strength","statement":"Sits about an inch lower and turns tighter; suits shorter, lighter and novice-to-vet riders.","years":[2023,2024],"support":1,"strength":"single source"},{"aspect":"stability","verdict":"strength","statement":"The 2025 frame is calmer, more comfortable leaned over and less jarring on acceleration bumps, and settles sooner in break-in.","years":[2025],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"neutral","statement":"Initial harshness when new, typical of the Austrian bikes, settled after a few days.","years":[2024,2025],"support":1,"strength":"single source"},{"aspect":"other","verdict":"strength","statement":"Quickshifter works well and the Brembo clutch is very durable.","years":[2024,2025],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"weakness","statement":"On 2023-2024 bikes traction control cut power heavily and was nearly unusable.","years":[2023,2024],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Linkage needle bearings can walk out and make the rear feel dead.","years":[2023],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Restricted airbox softens response","fix":"Perforated alternative airbox panel or vented cover","result":"Sharper throttle response","support":2},{"problem":"Default connectivity-unit setting felt jerky with too much engine braking","fix":"Engine braking 1/5, aggressive output, response 4/5","result":"Freer engine and calmer chassis","support":1},{"problem":"Wants more front-end steering and grip","fix":"Open shock high-speed compression to 1.75 turns out","result":"More front bite in corners","support":1},{"problem":"Shock speeds up at end of stroke","fix":"More low-speed compression","result":"Controlled end-stroke drop","support":1}],"disagreements":[{"topic":"Shootout placing","sides":["Second in class three years running","Fifth, marked down for its lowered chassis and price"]},{"topic":"Which map to race","sides":["Aggressive map 2 preferred","Map 1 on track, map 2 with traction control for rocky single track"]}]},{"years":[2027],"generation":"2027 model (first ride only)","summary":"Only one early first ride exists. Testers called it the easiest bike in the range, with good low-end torque, smooth non-aggressive power and soft suspension that stays calm at slower speeds.","points":[{"aspect":"engine_low","verdict":"strength","statement":"Good low-end torque; pulls out of corners even a gear too high with smooth, non-aggressive power.","years":[2027],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"neutral","statement":"Soft suspension stays calm over bumps at slower speeds.","years":[2027],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]}],"GasGas|MC 250F":[{"years":[2021,2022,2023],"generation":"2021-2023 (KTM 2016-2022 engine and chassis)","summary":"The first MC 250F is the KTM 250 SX-F with a near-sealed airbox, plain header, muffler restrictors, forged clamps, softer valving and no map switch. Testers found a soft low end with a clear dip before strong mid-to-top pull, and stock gearing that feels tall. In 2023, still on the old platform, it was the lightest bike in its class.","points":[{"aspect":"engine_low","verdict":"weakness","statement":"Soft low-rpm response with a clear dip from about 3,500 to 6,000 rpm, then strong from the middle to the top.","years":[2022,2023],"support":2,"strength":"consensus"},{"aspect":"gearing","verdict":"weakness","statement":"Stock 14/51 feels sluggish out of corners.","years":[2022],"support":1,"strength":"single source"},{"aspect":"weight_feel","verdict":"strength","statement":"On the old platform in 2023 it was the lightest 250F in its class.","years":[2023],"support":1,"strength":"single source"},{"aspect":"balance","verdict":"weakness","statement":"Felt pitchy with weight transfer until setup changes; some testers liked up to 108 mm sag.","years":[2022],"support":1,"strength":"single source"},{"aspect":"turning","verdict":"weakness","statement":"Forged clamps flex more than billet clamps, giving vague turn-in.","years":[2021,2022],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"weakness","statement":"No map switch: map 1 only until an accessory switch is fitted.","years":[2021,2022],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Weak bottom-to-mid","fix":"Cut the airbox winglet or fit a KTM vented cover","result":"Better breathing and response","support":1},{"problem":"Sluggish corner exits","fix":"13-tooth countershaft (13/50) or 14/52","result":"Better corner-exit surge","support":1}],"disagreements":[]},{"years":[2024,2025,2026],"generation":"2024+ (KTM 2023+ platform)","summary":"On the current KTM platform the MC 250F measures essentially the same as the KTM on the dyno, but its closed airbox, muffler restrictor and single stock map dull throttle response on the track; testers disagree on whether that makes it fun or held back. Softer valving makes it comfortable for vets and novices on soft tracks but short on hold-up for fast riders on jumpy tracks. Braktec brakes and clutch are rated below the Brembo parts, and it finishes mid-pack in shootouts.","points":[{"aspect":"engine_top","verdict":"neutral","statement":"Dyno numbers are close to the KTM and Husqvarna (within about 1-2 hp), and in some tests slightly ahead.","years":[2024,2025],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"neutral","statement":"Softer valving than the KTM: comfortable with easy traction on soft or rough tracks for vets and novices, but less hold-up for fast riders on jumpy tracks.","years":[2024,2025],"support":3,"strength":"strong consensus"},{"aspect":"brakes","verdict":"weakness","statement":"Braktec brakes stop well but with less precise modulation than Brembo; front brake subject to recall.","years":[2024,2025],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"neutral","statement":"Finishes mid-pack in shootouts, behind the KTM and Husqvarna.","years":[2024,2025],"support":2,"strength":"consensus"},{"aspect":"engine_low","verdict":"weakness","statement":"Closed airbox, muffler restrictor and single stock map dull throttle response on the track more than the dyno shows.","years":[2024,2025],"support":1,"strength":"single source"},{"aspect":"engine_low","verdict":"strength","statement":"2024 engine has better bottom torque than the previous one and revs a long way.","years":[2024],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"neutral","statement":"Air fork is sensitive: a 5 psi change is clearly felt.","years":[2024],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"strength","statement":"2025 frame cut-outs make it more comfortable in acceleration chop.","years":[2025],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"weakness","statement":"Braktec clutch feel changes when fanned or held at high rpm, causing a surge.","years":[2025],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Right radiator wing blocks the fork compression clickers; bars are 12 mm taller than the KTM's.","years":[2025],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"One-piece airbox side panel fits loosely and can be knocked off by a boot.","years":[2024],"support":1,"strength":"single source"},{"aspect":"tires","verdict":"weakness","statement":"Stock Maxxis tires lack side-knob grip.","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Restricted intake, exhaust and single map","fix":"Accessory map switch, drilled or swapped airbox cover, unrestricted muffler","result":"Brings it close to KTM feel (no dyno before/after published)","support":1},{"problem":"Chassis feel","fix":"Run 65-70 mm chain slack at the buffer pad","result":"Chassis works best at that slack","support":1}],"disagreements":[{"topic":"Engine character in stock form","sides":["Held back by intake and exhaust restrictions","Most fun of the three Austrian engines"]},{"topic":"Braktec brakes","sides":["Strong with no fade","Less precise modulation than Brembo"]}]}],"KTM|125 SX":[{"years":[2020,2021,2022],"generation":"carbureted (to 2022)","summary":"The carbureted 125 SX won one magazine's 125 shootouts in 2021 and 2022, ahead of its Husqvarna and GasGas siblings and the YZ125. Little else is reported beyond the usual KTM-family checks and owner jetting reports that lean toward the lean side.","points":[{"aspect":"other","verdict":"strength","statement":"Won 125 two-stroke shootouts in 2021 and 2022, ahead of the Husqvarna, GasGas and YZ125.","years":[2021,2022],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"neutral","statement":"Spokes by the rim lock loosen during break-in and the rear brake pedal spring can fall off or break.","years":[2020,2021,2022],"support":1,"strength":"single source"},{"aspect":"engine_top","verdict":"neutral","statement":"Owners report some jetting combinations running lean and hot; use owner settings only as a direction.","years":[2022],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Aftermarket linkage fitted","fix":"Drop fork air 0.2-0.5 bar to rebalance","result":"Keeps front and rear in balance","support":1},{"problem":"Throttle response","fix":"Vented airbox cover or drilled cover, then re-check jetting","result":"More bottom-end power and response","support":1}],"disagreements":[]},{"years":[2023,2024,2025,2026],"generation":"TBI fuel-injected (2023+)","summary":"Testers find the TBI 125 SX a little slower off the crack than the carbureted bike but easier to keep on the pipe, with smoother delivery that helps traction and suits novices more than top racers; the old carb bike keeps pulling higher on top. One magazine had repeated detonation on pump fuel, worse with an aftermarket pipe, and found the green map bogged randomly, while another tester saw no detonation. The ECU was locked at launch.","points":[{"aspect":"power_delivery","verdict":"neutral","statement":"Slightly slower off the crack than the carb 125 but rolls into the power more easily and stays on the pipe with less effort; tapers on top where the carb bike keeps climbing.","years":[2023,2024],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Detonated repeatedly on pump fuel in testing, worse with an aftermarket pipe; the 2024 model got no mapping fix.","years":[2023,2024],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"weakness","statement":"The richer green map bogged at random on test bikes, so testers used the white map.","years":[2023,2024],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"neutral","statement":"Stock ECU was locked at launch with no aftermarket ECU available.","years":[2023],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"neutral","statement":"2024 valving changes could not be felt on track; the suspension gets plusher after break-in.","years":[2024],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"neutral","statement":"A dealer reported 2025 bikes that would not start or fouled plugs; cycling the fuel pump, waiting for the light to go out and fresh correctly mixed fuel fixed them.","years":[2025],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Wants more low-mid","fix":"Aftermarket pipe (one brand gave more low-mid and less clutch use; another the snappiest bottom and longest over-rev)","result":"Closer to 150 feel","support":1},{"problem":"Detonation with a pipe","fix":"Remap needed with an aftermarket pipe","result":"Testers say a pipe alone made detonation worse","support":1}],"disagreements":[{"topic":"Detonation on the TBI 125","sides":["Repeated detonation on pump fuel, worse with a pipe","No detonation seen with aftermarket pipes"]}]}],"KTM|150 SX":[{"years":[2020,2021,2022],"generation":"carbureted (to 2022)","summary":"The carbureted 150 SX makes about 3 hp more than the 125 but hits hard in the middle and signs off quickly, so testers find the 125 smoother. Holding a gear too long unsettles the chassis. Findings come from one magazine.","points":[{"aspect":"power_delivery","verdict":"neutral","statement":"About 3 hp more than the 125, but hits hard in the midrange and signs off fast; the 125 feels smoother.","years":[2021,2022],"support":1,"strength":"single source"},{"aspect":"stability","verdict":"weakness","statement":"Holding a gear too long shifts weight forward and unsettles the chassis.","years":[2021],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"neutral","statement":"Fast riders preferred 14/49 over stock 13/48; tight tracks or less skilled riders 14/50.","years":[2021,2022],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Narrow midrange","fix":"Stamped aftermarket pipe","result":"About 2 hp more at peak, smoother mid so third is usable, quicker rev","support":1}],"disagreements":[]},{"years":[2025],"generation":"TBI fuel-injected","summary":"One reviewer found the stock TBI 150 SX dull at the bottom, strongest in the midrange and fading on top, so riders short-shifted; an aftermarket pipe and silencer fixed most of that. A dealer also reported no-start and plug-fouling cases on 2025 bikes.","points":[{"aspect":"power_delivery","verdict":"weakness","statement":"Stock engine is dull at the bottom, strongest in the midrange and fades on top, so riders short-shift.","years":[2025],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"neutral","statement":"Some 2025 bikes would not start or fouled plugs until the fuel pump was cycled and fresh, correctly mixed fuel used.","years":[2025],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Dull bottom and early fade","fix":"Aftermarket pipe and silencer","result":"Better bottom response, slightly more mid and a much longer over-rev","support":1}],"disagreements":[]}],"Husqvarna|TC 125":[{"years":[2020,2021,2022],"generation":"carbureted (to 2022)","summary":"In one magazine's 125 shootouts the carbureted TC 125 handled best of the group, but its composite airbox muted throttle response enough to cost pro testers lap time. Stock shock settings were close, and the fork is sensitive to height in the clamps.","points":[{"aspect":"turning","verdict":"strength","statement":"Handled best in the 125 shootout.","years":[2021],"support":1,"strength":"single source"},{"aspect":"engine_low","verdict":"weakness","statement":"Composite airbox mutes throttle response; pro testers were up to 2 seconds a lap slower than on the KTM.","years":[2021,2022],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"neutral","statement":"Fork is sensitive to clamp height; stock shock settings were close after setting sag.","years":[2020,2022],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]},{"years":[2023,2024,2025,2026],"generation":"TBI fuel-injected (2023+)","summary":"The TBI TC 125 sits lower than the KTM with softer fork action. Like the KTM it detonated on pump fuel in testing, worse with a pipe, and its green map bogged; the ECU was locked at launch.","points":[{"aspect":"suspension_front","verdict":"neutral","statement":"Forks 10 mm shorter and changed linkage lower the seat, with softer fork action than the KTM.","years":[2023,2024],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Detonation on pump fuel, made worse by an aftermarket pipe even on race fuel.","years":[2023,2024],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"weakness","statement":"Green map bogged at random; ECU locked at launch.","years":[2023],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Detonation with a pipe","fix":"Remap the ECU","result":"Needed before a pipe can be run safely","support":1}],"disagreements":[]}],"Husqvarna|TC 150":[{"years":[2025],"generation":"TBI fuel-injected","summary":"Only dyno and technical reporting exist. The bigger bore gives about 3 hp more than a 125 on the same dyno, and the lowered chassis and closed-off subframe follow the Husqvarna pattern.","points":[{"aspect":"engine_top","verdict":"neutral","statement":"Made about 3 hp and 1 lb-ft more than a 125 SX on the same dyno.","years":[2025],"support":1,"strength":"single source"},{"aspect":"engine_low","verdict":"neutral","statement":"Rear of the subframe is closed off, cutting airflow to the engine compared with the KTM.","years":[2025],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]}],"GasGas|MC 125":[{"years":[2021,2022,2023],"generation":"carbureted (to 2023)","summary":"The carbureted MC 125 uses the KTM engine with a closed airbox, forged clamps and softer suspension. Testers found a strong midrange and good top-end pull blunted at the first crack of throttle by the airbox, plusher suspension aimed at novices and vets, and clamps that flex enough to affect steering. In 2023 it out-revved the new TBI KTM and Husqvarna on top.","points":[{"aspect":"suspension_front","verdict":"neutral","statement":"Same WP hardware as the KTM with softer valving, plusher and aimed at novice and vet riders.","years":[2021,2022],"support":2,"strength":"consensus"},{"aspect":"suspension_rear","verdict":"weakness","statement":"A 200 lb rider would need a stiffer shock spring.","years":[2021],"support":1,"strength":"single source"},{"aspect":"engine_low","verdict":"weakness","statement":"Closed airbox cover blunts initial throttle response.","years":[2023],"support":1,"strength":"single source"},{"aspect":"engine_top","verdict":"strength","statement":"Strong midrange and good top-end pull; in 2023 it kept climbing on top where the TBI siblings tapered.","years":[2023],"support":1,"strength":"single source"},{"aspect":"turning","verdict":"weakness","statement":"Forged clamps flex more than billet ones, causing oversteer on entry and understeer on exit.","years":[2021],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"neutral","statement":"One 160 lb owner found the manual's lower air pressure felt great after higher pressure felt soft at speed and pogo-like slow.","years":[2022],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Blunted initial response","fix":"Vented aftermarket cover or drilled stock cover","result":"Sharper first crack of throttle","support":1}],"disagreements":[]},{"years":[2024,2025,2026],"generation":"TBI fuel-injected (2024+)","summary":"Testers found the TBI MC 125 smoother and more predictable than the carbureted bike, with power shifted toward the midrange and fewer peaks and dips after a missed shift.","points":[{"aspect":"power_delivery","verdict":"neutral","statement":"Power shifted toward the midrange; more predictable and four-stroke-like with fewer peaks and dips after a missed shift.","years":[2024],"support":2,"strength":"consensus"}],"common_fixes":[],"disagreements":[]}],"KTM|250 SX":[{"years":[2020,2021,2022],"generation":"carbureted (2019-2022)","summary":"Testers found the carbureted 250 SX strongest from bottom to mid with an aggressive hit, then little top end, and less explosive than the 2017-2018 bike mainly because of airbox restriction. It out-pulled the YZ250 low and in the middle on the dyno. Stock fork settings felt stiff, and some owners still prefer it to the heavier TBI model.","points":[{"aspect":"power_delivery","verdict":"neutral","statement":"Strongest bottom to mid with an aggressive hit, then little top end; it out-pulls the YZ250 to about 8,800 rpm and then falls off.","years":[2020,2022],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"Stock fork felt stiff and harsh until broken in; testers lowered air and opened compression significantly.","years":[2020,2021,2022],"support":1,"strength":"single source"},{"aspect":"other","verdict":"neutral","statement":"Owners say the TBI 250 that replaced it makes less power and weighs more.","years":[2022],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"neutral","statement":"Shock preload ring wears quickly; there is no oil sight glass so oil is checked at a weep bolt.","years":[2020,2022],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Airbox restricts power","fix":"Optional vented airbox cover or drilled cover, then re-jet","result":"More bottom-end power and response","support":1},{"problem":"Hit too abrupt","fix":"One tooth smaller rear sprocket","result":"Calmer bottom and spread gears","support":1}],"disagreements":[]},{"years":[2023,2024,2025,2026],"generation":"TBI fuel-injected (2023+)","summary":"Testers agree the TBI 250 SX's stock mapping is conservative: a luggable, almost four-stroke-like bottom end, then a flat top that runs into an abrupt limiter. Remaps and aftermarket pipes are the standard fix and add mid-to-top pull. Stock suspension is balanced on hard tracks but soft for heavier or faster riders. A few owners reported brief cut-outs on 2023 bikes.","points":[{"aspect":"engine_top","verdict":"weakness","statement":"Stock mapping is conservative: luggable bottom end but flat on top and quick to reach the rev limiter.","years":[2023,2024,2025],"support":2,"strength":"consensus"},{"aspect":"power_delivery","verdict":"neutral","statement":"Revs through the gears quicker than the 300.","years":[2024],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"neutral","statement":"The white map opens the power valve only about 80% and mutes power; the green map opens it fully.","years":[2024],"support":1,"strength":"single source"},{"aspect":"engine_top","verdict":"weakness","statement":"Rev limiter is abrupt, mostly when revving with the clutch in or in the air.","years":[2023,2024],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"neutral","statement":"Stock suspension is balanced on hard West Coast tracks but soft for heavier or faster riders and for deep loam or sand.","years":[2023,2024],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"neutral","statement":"A few 2023 owners reported brief cut-outs under load or in the air; dealers could not reproduce them.","years":[2023],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Flat top end and limiter hits","fix":"Remap of the stock ECU","result":"Keeps the luggable bottom while adding mid-to-top pull and fewer limiter hits","support":2},{"problem":"Rich low-rpm feel and flat top","fix":"Aftermarket pipe and silencer","result":"Cleaner low end, more second-gear pull and much stronger top end","support":1}],"disagreements":[]}],"KTM|300 SX":[{"years":[2023,2024,2025,2026],"generation":"TBI fuel-injected (2023+)","summary":"Testers like the TBI 300 SX's strong, luggable low-to-mid torque, which lets riders hold second or third with fewer shifts, but the stock mapping has a short over-rev and runs flat on top. The white map is mellower with a longer pull, the green map hits harder. Stock suspension is soft for riders over about 185 lb, though one east-coast tester found it firm. Aftermarket pipes are the most-tested fix and add measurable power; a remap adds over-rev.","points":[{"aspect":"engine_mid","verdict":"strength","statement":"Strong, luggable low-to-mid torque lets riders hold second or third with fewer shifts.","years":[2023,2024,2025],"support":2,"strength":"consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Stock delivery has a short midrange ramp and short over-rev, so it needs quick shifts or runs flat at high rpm.","years":[2023,2024],"support":2,"strength":"consensus"},{"aspect":"mapping","verdict":"neutral","statement":"White map is mellower with a longer pull; green map hits harder and needs more clutch work.","years":[2023,2025],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Stock suspension gets soft for riders over about 185 lb.","years":[2023,2024],"support":2,"strength":"consensus"},{"aspect":"reliability","verdict":"neutral","statement":"Owners report water in the throttle-position-sensor connector causing fouled plugs and cut-outs, and re-teach the electronic power valve periodically.","years":[2023,2024,2025],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Short over-rev, flat top","fix":"Aftermarket pipe and silencer","result":"Measured about 3 hp more on one dyno; more mid, snap and over-rev, third usable in corners","support":3},{"problem":"Flat top, limiter hits","fix":"ECU remap","result":"More traditional hit, more over-rev and better third-gear exits","support":1},{"problem":"Weak third-gear roll-on in loose dirt","fix":"One more rear tooth (13/50)","result":"Better third-gear pull","support":1},{"problem":"Detonation","fix":"One step hotter spark plug","result":"Used by one tester to cure detonation","support":1}],"disagreements":[{"topic":"Stock suspension firmness","sides":["Soft over about 185 lb","Firm; changes made it smoother and plusher"]}]}],"Husqvarna|TC 250":[{"years":[2020,2021,2022],"generation":"carbureted (2019-2022)","summary":"Findings come from one magazine. The carbureted TC 250 breathes through a composite airbox that gives softer throttle response than the KTM, its power is concentrated bottom to mid so it needs more shifting, and it sits about an inch lower with softer valving. Stock suspension settings felt stiff to vet testers.","points":[{"aspect":"engine_low","verdict":"weakness","statement":"Composite subframe and airbox breathe less than the KTM's, softening throttle response.","years":[2020,2021,2022],"support":1,"strength":"single source"},{"aspect":"power_delivery","verdict":"neutral","statement":"Power is concentrated bottom to mid and needs more shifting than a YZ250.","years":[2021],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"Stock settings felt stiff; vet testers lowered air and opened compression.","years":[2020],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"weakness","statement":"Handlebar map switch is hidden under the throttle cables and hard to read.","years":[2021],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Soft throttle snap","fix":"Vent the airbox cover (large holes away from the filter), re-check jetting","result":"More throttle snap; fast testers liked it, slow ones did not","support":1}],"disagreements":[]},{"years":[2023,2024,2025,2026],"generation":"TBI fuel-injected (2023+)","summary":"The TBI TC 250 sits about an inch lower than the KTM with a closed airbox that dulls the first crack of throttle and softer valving aimed at novices and vets; faster riders wanted more support. An aftermarket pipe filled a dip in its curve. One owner traced a mid-ride cut-out to a failed fuel pump.","points":[{"aspect":"engine_low","verdict":"weakness","statement":"Closed airbox slightly dulls the first crack of throttle.","years":[2023],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"neutral","statement":"Softer valving with less hold-up than the KTM 300 SX: better traction and fit for shorter riders, less support for fast riders.","years":[2023,2025],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"neutral","statement":"One owner's bike lost power and died about 15 minutes into rides; the fuel pump was faulty.","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Dip in the curve at 7,600-8,000 rpm","fix":"Aftermarket pipe and silencer","result":"About 1 hp more at peak and the dip removed","support":1},{"problem":"Not enough support for intermediate/pro","fix":"Forks flush, high-speed compression 1 turn out","result":"More hold-up","support":1}],"disagreements":[]}],"Husqvarna|TC 300":[{"years":[2025,2026],"generation":"TBI fuel-injected","summary":"Only owner reports exist: smooth, linear and luggable, smoother than a YZ250, but some feel it runs out of steam early in stock form and recommend a remap.","points":[{"aspect":"power_delivery","verdict":"neutral","statement":"Smooth, linear and luggable; some owners feel it runs out of steam early stock.","years":[2025],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Runs out of steam early","fix":"ECU remap, often with a 49-tooth sprocket","result":"More over-rev","support":1}],"disagreements":[]}],"GasGas|MC 250":[{"years":[2021,2022,2023],"generation":"carbureted (to 2023)","summary":"Findings come from one magazine. The carbureted MC 250 hits hard from the bottom and pulls hard into the middle but signs off early, so it needs short-shifting; taller gearing calms it. Suspension is softer and suited to novices and vets, and the forged clamps flex.","points":[{"aspect":"power_delivery","verdict":"neutral","statement":"Hits hard from the bottom and pulls harder into the middle than a YZ250 but signs off early, so it needs short-shifting.","years":[2022,2023],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"neutral","statement":"Softer settings suit novice and vet riders; fast or heavy riders go stiffer or to a 45 N/mm spring.","years":[2022,2023],"support":1,"strength":"single source"},{"aspect":"turning","verdict":"weakness","statement":"Forged clamps flex more than billet ones.","years":[2021,2022,2023],"support":1,"strength":"single source"},{"aspect":"weight_feel","verdict":"strength","statement":"In 2023 it was about 7 lb lighter and $600 cheaper than the TBI KTM.","years":[2023],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Abrupt bottom end","fix":"One tooth taller gearing (14/48)","result":"Calmer bottom and better gear spacing","support":1}],"disagreements":[]},{"years":[2024,2025,2026],"generation":"TBI fuel-injected (2024+)","summary":"Testers found the TBI MC 250 crisp and clean with very strong low-end torque that pulls third in slow sections. One launch tester found the anti-squat rear odd at first but good for driving out of corners, and the air fork harsh on small high-speed bumps. The map switch was an option on the tested bike and was the first suggested upgrade.","points":[{"aspect":"engine_low","verdict":"strength","statement":"Crisp, clean delivery with very strong low-end torque that pulls third gear in slow sections.","years":[2024],"support":2,"strength":"consensus"},{"aspect":"suspension_rear","verdict":"neutral","statement":"Anti-squat rear feels odd at first on corner exits but lets the rider get on the throttle harder; shock is forgiving.","years":[2024],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"Air fork handles big landings but feels harsh on small high-speed bumps.","years":[2024],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"neutral","statement":"Map switch was optional on the test bike; standard map for hard pack, green map for sand.","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Fork too stiff for a 74 kg rider","fix":"140-145 psi; sag raised to about 103 mm","result":"Sharper steering, at some cost to downhill stability","support":1}],"disagreements":[]}],"KTM|85 SX":[{"years":[2020,2021,2022,2023,2024],"generation":"2018-2024 generation","summary":"Testers describe the 2018-2024 85 SX as having little bottom end before exploding into its midrange. Small complaints include a soft plastic shock preload ring, a power-valve adjuster that needs a square-drive wrench and a hard-to-remove airbox cover. Parents report the air fork can feel harsh on landings for very light riders.","points":[{"aspect":"power_delivery","verdict":"neutral","statement":"Little bottom end, then explodes into the midrange; later testers called it lazy off the bottom.","years":[2020,2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"weakness","statement":"Soft plastic shock preload ring, square-drive power-valve adjuster, Torx fork bleed screw and a hard-to-remove airbox cover.","years":[2020,2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"Parents report the air fork can feel harsh on landings for light riders; one never got it right until a coil conversion.","years":[2020,2021,2022,2023,2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Harsh fork for a light rider","fix":"Open compression rather than dropping air; coil conversion as last resort","result":"Owner-reported improvements","support":1}],"disagreements":[]},{"years":[2025,2026],"generation":"2025+ update","summary":"Testers found the 2025 KTM-group 85 stronger off the bottom than the 2024 bike, smooth into the midrange and still snappy on top, and most testers picked it as the best 85. Complaints: rich stock jetting, brittle plastics, hidden shock clickers, weaker Formula brakes and low bars.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Pulls harder off the bottom than the 2024 bike, transitions smoothly into the midrange and keeps its top-end snap; picked as best 85 by most testers.","years":[2025],"support":1,"strength":"single source"},{"aspect":"engine_low","verdict":"weakness","statement":"Stock jetting runs rich, leaving oil residue and a slight midrange flat spot.","years":[2025],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Rigid plastic fenders snap in small crashes.","years":[2025],"support":1,"strength":"single source"},{"aspect":"brakes","verdict":"weakness","statement":"Formula brakes are weaker than the Brembos on the big bikes.","years":[2025],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Testers wanted taller bars; side panels hide the shock clickers; steering lock is tight.","years":[2025],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Rich stock jetting","fix":"Lean the pilot (42-52) and adjust main/needle as advised","result":"Cleaned up the rich midrange","support":1},{"problem":"Shock clickers hidden","fix":"Drill an access hole in the side panel","result":"Clickers reachable without removing plastics","support":1}],"disagreements":[]}],"GasGas|MC 85":[{"years":[2025],"generation":"2025+ (same bike as KTM 85 SX)","summary":"Tested as the same bike as the 2025 KTM 85 SX: stronger and smoother off the bottom than the 2024 version, with rich stock jetting and brittle plastics.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Pulls harder off the bottom than the 2024 bike and transitions smoothly into the midrange while keeping its top-end snap.","years":[2025],"support":1,"strength":"single source"},{"aspect":"engine_low","verdict":"weakness","statement":"Stock jetting runs rich with a slight midrange flat spot.","years":[2025],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Rigid plastic fenders snap in crashes; air fork needs a pressure check before every ride.","years":[2025],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Rich stock jetting","fix":"Pilot dropped to 42 with an NRJC needle in the third clip (advised by factory R&D)","result":"Cleaned up the midrange","support":1}],"disagreements":[]}],"Husqvarna|TC 85":[{"years":[2025],"generation":"2025+","summary":"In one 85 comparison the Husqvarna version, with its closed airbox, pulled shorter and ran richer than the KTM and GasGas versions.","points":[{"aspect":"engine_top","verdict":"weakness","statement":"Closed airbox makes it pull less far on top and run richer than the KTM and GasGas versions.","years":[2025],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]}],"KTM|450 XC-F":[{"years":[2020,2021,2022],"generation":"2019-2022 generation (air fork, 5-speed)","summary":"Testers describe the previous 450 XC-F as an SX-F engine with mellower cross-country mapping: soft off the bottom, smooth and strong once going, and it hooks up well. Its five-speed gearbox is the main complaint, with first too tall for tight trails and too few gears for fast desert, so a sixth gear is a popular swap. Suspension is plush on trail chatter but lacks the SX-F's hold-up on jumps, and it shipped without a skid plate or spark arrester.","points":[{"aspect":"gearing","verdict":"weakness","statement":"Five-speed gearbox: first is too tall for tight trails and it runs out of gear in fast desert.","years":[2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"power_delivery","verdict":"strength","statement":"Mellow off the bottom, smooth and surge-free through the middle and strong once going; hooks up with less wheelspin and feels slower than it is.","years":[2021],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"neutral","statement":"Softer cross-country valving is plush on trail chatter but lacks the SX-F's hold-up on jumps.","years":[2021],"support":1,"strength":"single source"},{"aspect":"other","verdict":"weakness","statement":"Shipped without a skid plate, engine protection or a USFS spark arrester despite costing more than the SX-F.","years":[2021],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Runs out of gear in the desert","fix":"Add the OEM sixth-gear pair and shift drum (about $300, cases split), often with 14/48 sprockets","result":"Usable top gear for fast terrain","support":1},{"problem":"Not enough hold-up for GP racing","fix":"Fork air raised 0.5 bar and shock high-speed compression in 1/4 turn","result":"Stronger hold-up (0.5 bar is a big change)","support":1}],"disagreements":[]},{"years":[2023,2024,2025,2026],"generation":"2023+ generation (coil fork from 2024)","summary":"Testers find the current 450 XC-F as powerful as any production 450 yet manageable and linear, but more prone than a 350 or XC-W to stalling and flame-outs in slow technical terrain. The 2023-2024 frame felt too rigid and the 2025 frame is more compliant. Its soft cross-country suspension suits WORCS and hare scrambles, while the 2026 coil fork rides low and bottoms on fast ground. Desert racers add a sixth gear to the five-speed.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"As much peak power as any production 450, yet linear and manageable, pulling cleanly from off idle and revving far.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"engine_low","verdict":"weakness","statement":"Stalls and flames out more easily than a 350 or XC-W in tight, slow terrain; the spinning mass makes low-speed work harder.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"gearing","verdict":"weakness","statement":"The five-speed runs out of gear on fast desert; many racers add a sixth gear.","years":[2023,2024,2025],"support":2,"strength":"consensus"},{"aspect":"chassis","verdict":"weakness","statement":"The 2023-2024 frame felt too rigid; the 2025 frame is more compliant almost everywhere.","years":[2023,2024,2025],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"neutral","statement":"Shock is valved like a soft motocross setting: good for WORCS-style racing but too stiff in desert rock fields; fork slightly stiff picking through boulders.","years":[2025],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"The 2026 coil fork rides low and softer than the rear, giving a nose-down feel and bottoming in fast terrain; suits hare scrambles and some prefer the old air fork.","years":[2026],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"weakness","statement":"Clutch-heavy riders can overheat the clutch in tight single track.","years":[2025],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Runs out of gear in the desert","fix":"Fit a sixth gear","result":"Top gear for fast terrain","support":2},{"problem":"Too stiff in desert rocks","fix":"Firmer settings for speed or revalve for rocks","result":"Desert racers need different settings from WORCS racers","support":1}],"disagreements":[]}],"KTM|350 XC-F":[{"years":[2023,2024,2025,2026],"generation":"2023+ generation (coil fork from 2024)","summary":"Testers like the current 350 XC-F's strong bottom-end pull, good midrange and extra pull on top, rideable like a 450 but rewarding revs. Its weak spots are jerky low-speed throttle response and stalling in tight rocky terrain, a coil fork that is softer than the shock and pitches or blows through, and a clutch that overheats or fades under heavy slipping. Testers try shorter gearing with mixed results.","points":[{"aspect":"engine_low","verdict":"weakness","statement":"Low-speed throttle response is jerky in slow rocky sections and it can cough and stall in tight single track.","years":[2024,2025],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Coil fork is softer than the shock: it pitches under hard braking and blows through on big hits, and is soft for aggressive motocross.","years":[2024,2025],"support":2,"strength":"consensus"},{"aspect":"clutch","verdict":"weakness","statement":"Heavy clutch use in tight single track overheats or fades the clutch; one tester boiled coolant twice.","years":[2024,2025],"support":2,"strength":"consensus"},{"aspect":"gearing","verdict":"neutral","statement":"Testers try shorter gearing to use third in corners; results are mixed (one went back to stock because second became too short).","years":[2024,2025],"support":2,"strength":"consensus"},{"aspect":"power_delivery","verdict":"strength","statement":"Strong bottom-end pull, good midrange and more pull on top; can be ridden like a 450 but rewards revving.","years":[2025],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"neutral","statement":"The 2023 air fork worked at stock settings for desert and motocross after break-in but was harsh before 6-8 hours.","years":[2023],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Stalling and coughing in tight terrain","fix":"Turn traction control off on the soft map; shorter header, aftermarket silencer and custom map","result":"Cleaner running and less stalling","support":2},{"problem":"Clutch fade or overheating","fix":"Auto-clutch, lower gearing, smoother map, or the 450 SX-F clutch master cylinder","result":"Less fade and heat","support":2},{"problem":"Soft fork pitches and blows through","fix":"Revalve and springs for rider weight, about 105 mm sag with forks flush","result":"Controlled slow-speed bump absorption with only occasional controlled bottoming","support":1}],"disagreements":[]},{"years":[2020,2021,2022],"generation":"2019-2022 generation","summary":"Only a dyno test exists for this generation; it measured about the same peak as one rival 450.","points":[{"aspect":"engine_top","verdict":"neutral","statement":"On one dyno the 2022 model matched a rival 450's peak power.","years":[2022],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]}],"KTM|250 XC-F":[{"years":[2020,2021,2022],"generation":"2019-2022 generation","summary":"One first-impression test found the 250 XC-F air fork harsh on square edges and sharp chop at standard pressure, and the six-speed's big jump to sixth hard to engage.","points":[{"aspect":"suspension_front","verdict":"weakness","statement":"At standard pressure the air fork felt harsh on square edges and sharp chop and could not be softened without losing bottoming resistance.","years":[2020],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"weakness","statement":"Semi-close six-speed has a big jump to sixth that is hard to engage.","years":[2020],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Stability","fix":"107 mm sag instead of 105","result":"More stable with a lower rear on corner entry, slightly slower steering","support":1}],"disagreements":[]},{"years":[2023,2024,2025,2026],"generation":"2023+ generation","summary":"Little tester commentary exists beyond a dyno test. A few owners reported fuel pump failures, sometimes after long idling with little fuel.","points":[{"aspect":"reliability","verdict":"neutral","statement":"A few owners report the fuel pump fuse blowing or the pump dying; others had no issues.","years":[2023],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Fuel pump failure","fix":"Replace pump and filter; keep enough fuel to cover the pump","result":"Running again","support":1}],"disagreements":[]}],"KTM|450 XCF-W":[{"years":[2023,2024,2025,2026],"generation":"older-frame woods model with PDS rear","summary":"Testers call the 450 XCF-W the smoothest KTM four-stroke: it lugs to very low rpm and finds traction where a motocross bike spins, at the cost of peak power from its quiet exhaust. The linkless PDS shock is valued for ground clearance and not snagging logs. The 2023 coil fork was too soft and pitchy at speed, and the 2024 closed-cartridge fork was a big improvement.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Smoothest KTM four-stroke: lugs to very low rpm without bogging, builds steadily and finds traction where motocross bikes spin.","years":[2023,2024],"support":3,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Quiet exhaust and tame tune cost peak power compared with the XC-F; an aftermarket exhaust recovers about half of what racers want.","years":[2023],"support":2,"strength":"consensus"},{"aspect":"suspension_rear","verdict":"strength","statement":"Linkless PDS shock gives more ground clearance and nothing to snag on logs and rocks.","years":[2023,2025],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"strength","statement":"The 2024 closed-cartridge fork was a major improvement over the 2023 fork.","years":[2024],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"2023 fork was softer than a motocross setup, pitchy and divey at high speed; happiest under 30-40 mph.","years":[2023],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"weakness","statement":"Map switch, traction control and quickshifter are optional; the map light is hard to see in sun and buttons sit close together.","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Wants more power for racing","fix":"Aftermarket exhaust, then remap and cams","result":"Exhaust recovers about half; mapping and cams the rest","support":1}],"disagreements":[]}],"Husqvarna|FX 450":[{"years":[2020,2021,2022],"generation":"2019-2022 generation","summary":"Testers found the FX 450 smooth off the bottom and strong through the middle with no surges, so it feels slower than it is. Its five-speed's tall first gear is the main complaint for trail riding, and the suspension needed more hold-up, especially in front, everywhere except slow rocky terrain.","points":[{"aspect":"gearing","verdict":"weakness","statement":"Five-speed with a tall first gear for tight trails, and it runs out of gear on fast desert.","years":[2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"power_delivery","verdict":"strength","statement":"Smooth off the bottom, strong through the middle and still pulling at the limiter, with no surges; feels slower than it is.","years":[2020],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"Needed more hold-up, especially at the front, everywhere except very slow rocky terrain.","years":[2020],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"neutral","statement":"Spoke nipples and rear sprocket bolts need frequent checks and the airbox-cover hook can snap when refitted.","years":[2020],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Tall first gear","fix":"Gear down for trails, up for motocross","result":"Better match to terrain","support":1},{"problem":"Runs out of gear","fix":"Fit a sixth gear (cases accept it)","result":"Usable top gear","support":1}],"disagreements":[]},{"years":[2023,2024,2025,2026],"generation":"2023+ generation","summary":"Little tester commentary exists: one dyno tester described linear, controllable delivery, and the five-speed's limits for fast desert still apply.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Linear, controllable delivery.","years":[2023],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"weakness","statement":"Five-speed runs out of gear on fast desert; a sixth gear is the usual fix.","years":[2023,2024,2025,2026],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]}],"Husqvarna|FX 350":[{"years":[2023,2024,2025],"generation":"2023+ generation","summary":"Testers describe the FX 350 as closer to a mellow 450 than a 250F: only a few hp short of a 450, pulling a long way and easy to short-shift when tired, and it stalls less than a 450. Stock settings suit most vet tracks, and the 2025 frame needs no break-in.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Feels like a mellow 450: only a few hp short, pulls a long way and can be short-shifted when tired.","years":[2025],"support":2,"strength":"consensus"},{"aspect":"engine_low","verdict":"strength","statement":"Stalls less than a 450 when ridden low in the rpm off-road.","years":[2025],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"neutral","statement":"Stock settings suit most vet tracks; faster tracks need a few more clicks of fork compression.","years":[2025],"support":1,"strength":"single source"},{"aspect":"chassis","verdict":"strength","statement":"2025 frame needs no break-in.","years":[2025],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]}],"Husqvarna|FE 450":[{"years":[2020],"generation":"2020 enduro (non-US market)","summary":"One Australian test found the 2020 FE 450's stiffer frame more stable at speed and less harsh, while its spring fork was plush in the woods but too soft on a motocross track.","points":[{"aspect":"stability","verdict":"strength","statement":"Stiffer 2020 frame is more stable at speed and less harsh.","years":[2020],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"neutral","statement":"Spring fork is plush in the woods but too soft on a motocross track; the shock handles big hits better than the fork.","years":[2020],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]},{"years":[2024],"generation":"2024 enduro","summary":"Testers found the 2024 FE 450 smooth and easy with strong low-end grunt and good climbing, but heavier and more work in tight sections than the smaller FEs. The switch to a closed-cartridge fork made it firmer and less prone to bottoming.","points":[{"aspect":"weight_feel","verdict":"weakness","statement":"Feels heavier and needs more effort in tight sections than the FE 250/350; sometimes pushes the front.","years":[2024],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"neutral","statement":"New closed-cartridge fork is firmer and bottoms less than the previous open-cartridge fork.","years":[2024],"support":2,"strength":"consensus"},{"aspect":"power_delivery","verdict":"strength","statement":"Smooth and easy with strong low-end grunt and good climbing, pulling from corners in second to fourth.","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]}],"GasGas|EX 350F":[{"years":[2021,2022,2023],"generation":"first generation (KTM XC-F based, air fork)","summary":"The first EX 350F uses the KTM XC-F engine and chassis with a restrictive airbox, a plain header and no map switch, and testers found it weaker than the KTM out of tight uphill turns. The air fork was plush and most testers stayed near stock. Forged clamps caused front push until torqued higher.","points":[{"aspect":"engine_low","verdict":"weakness","statement":"Weaker than the KTM out of tight turns; testers traced it to the airbox and plain header rather than the engine.","years":[2021],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"strength","statement":"Stock fork plush; most testers stayed close to stock clickers.","years":[2021],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"neutral","statement":"Six-speed has a much lower first and taller third to fifth than the motocross box; sixth is unusable on a track.","years":[2021],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Rim-lock spoke loosens quickly, plastic preload ring gets chewed, fuel cap clogs with dirt.","years":[2021],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Weak pull out of tight uphill turns","fix":"KTM vented airbox cover (winglet removed)","result":"Noticeably better pull; with no cover it pulled third cleanly","support":1},{"problem":"Front-end push","fix":"Top clamp bolts 20 Nm, bottom 15 Nm","result":"Push cured","support":1},{"problem":"Third gear not usable on MX","fix":"14/52 or 13/50","result":"Third usable","support":1}],"disagreements":[]},{"years":[2024,2025,2026],"generation":"2024+ (new frame, coil fork)","summary":"Testers find the EX 350F keeps a free-revving motocross character with less bottom-end tractability than the enduro EC, and its closed-cartridge fork handles big hits and ruts but is harsher on roots and loose rock.","points":[{"aspect":"suspension_front","verdict":"neutral","statement":"Closed-cartridge fork handles big hits, braking bumps and ruts well but is harsher on roots and loose rock than the enduro fork.","years":[2024],"support":2,"strength":"consensus"},{"aspect":"power_delivery","verdict":"neutral","statement":"Free-revving with strong mid-to-top pull, but less bottom tractability and a less smooth throttle off idle than the EC models.","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]}],"GasGas|EX 250F":[{"years":[2021,2022,2023],"generation":"first generation (KTM XC-F based, air fork)","summary":"Testers measured a clear low-rpm dip and less power than the KTM, blamed on the closed airbox, missing map 2 and plain header. The suspension was firm early but short on progression, bottoming on big hits and blowing through at pro pace, with a soft, wallowy shock.","points":[{"aspect":"engine_low","verdict":"weakness","statement":"Clear dip around 4,300-4,700 rpm and less power than the KTM 250 SX-F, blamed on the closed airbox, single map and plain header.","years":[2021],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"Fork is firm early but short on progression and bottoms on big fast hits; shock soft with some wallow; both ends blow through at pro pace.","years":[2022],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Blows through at speed","fix":"Higher fork air and 105-108 mm sag","result":"Better hold-up and bottoming resistance, though valving stays soft","support":1}],"disagreements":[]},{"years":[2024,2025,2026],"generation":"2024+ (new frame, coil fork)","summary":"One dyno tester described the 2024 EX 250F's power as long and linear with no hard hit, still revving out and suiting the wide-ratio six-speed.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Long, linear power with no hard hit that still revs out; wide-ratio six-speed hides the gaps.","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]}],"GasGas|EX 450F":[{"years":[2021,2022,2023],"generation":"first generation (KTM XC-F based, air fork)","summary":"Only a shootout note exists: added fork air helped, but both ends still lacked bottoming resistance compared with rivals.","points":[{"aspect":"suspension_front","verdict":"weakness","statement":"Both ends lacked bottoming resistance compared with rival off-road 450s, even with added fork air.","years":[2023],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]},{"years":[2024,2025,2026],"generation":"2024+ (new frame, coil fork)","summary":"Testers found the 2024 EX 450F very stable at speed with playful, soft off-road suspension and a coil fork that stays more planted than the air fork as tracks get rough. Complaints centre on a Braktec clutch that drags unless fully pulled, poor cold starting in gear, missing protection and a rear tire short on side grip.","points":[{"aspect":"suspension_front","verdict":"strength","statement":"Closed-cartridge coil fork stays more planted than the air fork as the track gets choppy; racier than the enduro fork on big hits and ruts.","years":[2024],"support":2,"strength":"consensus"},{"aspect":"stability","verdict":"strength","statement":"Very stable in fifth gear on chop, with playful, soft off-road suspension.","years":[2024],"support":1,"strength":"single source"},{"aspect":"power_delivery","verdict":"neutral","statement":"Keeps motocross character: free-revving with strong mid-to-top but less bottom-end tractability than the EC enduro.","years":[2024],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"weakness","statement":"Braktec hydraulic clutch drags unless pulled fully in; the tester stalled four times.","years":[2024],"support":1,"strength":"single source"},{"aspect":"other","verdict":"weakness","statement":"Will not start in gear when cold, weak start button, no handguards or skid plate; 18-inch rear tire lacks side bite.","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Clutch drags","fix":"Set the lever fully out","result":"Less drag","support":1}],"disagreements":[]}],"GasGas|EC 450F":[{"years":[2024,2025],"generation":"enduro (open-cartridge fork)","summary":"Testers find the EC 450F smooth, mellow and less tiring than the cross-country EX, with better bottom-end tractability. Its open-cartridge fork is plush with low stiction on trails but soft at speed over big hits, and adding hold-up without harshness took a revalve.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Smooth, mellow and less tiring, with better bottom-end tractability and a smoother throttle off idle than the EX.","years":[2024,2025],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"neutral","statement":"Open-cartridge fork is plush with low stiction on trails but soft over big hits at speed; hard to add hold-up without harshness.","years":[2024,2025],"support":2,"strength":"consensus"}],"common_fixes":[{"problem":"Soft fork and shock at race pace","fix":"Aftermarket revalve of fork and shock","result":"Surprisingly good","support":1},{"problem":"Wants more pull","fix":"KTM XC-F silencer (fully open muffler caused low-rpm flame-outs)","result":"Pulled harder","support":1},{"problem":"Balance","fix":"Fork tubes flush in clamps; lower footpegs, taller seat, steering damper","result":"Better balance and more open cockpit","support":1}],"disagreements":[]}],"KTM|300 XC-W":[{"years":[2020,2021,2022,2023],"generation":"TPI fuel injection","summary":"Testers find the TPI 300 XC-W smooth, mellow and easy to ride with excellent fuel economy, but lacking the bottom-end grunt and midrange pull of the old carbureted 300s, with a lean-feeling tune and light detonation on trailing throttle. The open-cartridge fork and progressive PDS shock are plush at low speed but dive, wallow and bottom, and suit riders up to about 170-180 lb. ECU replacements or reflashes and higher-compression heads are the most common engine fixes.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Smooth, long and friendly powerband that is easy to ride at low speed.","years":[2020,2023],"support":2,"strength":"consensus"},{"aspect":"engine_low","verdict":"weakness","statement":"Lacks the bottom-end grunt and midrange pull of earlier carbureted 300s; the stock map feels lean, with a weak spot in the midrange.","years":[2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"reliability","verdict":"weakness","statement":"Light detonation can be heard at low rpm and on trailing throttle, worse on 87-octane fuel.","years":[2020,2021],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"strength","statement":"Good fuel range: about 33-40 mpg, roughly 50 miles racing or 60-65 miles trail riding per tank.","years":[2020],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"Open-cartridge fork and progressive PDS shock are plush at low speed but dive under braking, wallow and bottom, and are sprung for about 170-180 lb riders.","years":[2020,2023],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"neutral","statement":"PDS is cushy in tight rocks, roots and logs but gets bouncy at speed compared with the linkage XC.","years":[2022],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"weakness","statement":"On 2020 bikes long climbs or descents without stopping made it run lean or rich until restarted; a software update fixed it.","years":[2020],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"neutral","statement":"Never premix an oil-injected TPI, prime the oil line after throttle-body work, and warm the engine before riding hard to avoid seizures.","years":[2020,2021,2022,2023],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Lean, flat stock fueling and detonation","fix":"Replacement ECU or stock-ECU reflash","result":"Runs better throughout, detonation removed, big gain in power and torque","support":3},{"problem":"Weak low end, especially at altitude","fix":"High-compression head (with mountain insert) plus remap","result":"More low-end grunt and midrange pull","support":2},{"problem":"Dives and bottoms","fix":"Rework suspension and run about 108-115 mm sag; 1/4 turn more high-speed compression","result":"Better cornering and no blow-through on logs","support":1},{"problem":"Stalls on hard-enduro climbs","fix":"Heavier flywheel, high-compression head and reflash","result":"Smoother part throttle and fewer stalls","support":1},{"problem":"Bike delivered with power-valve adjuster screwed all the way in","fix":"Back the adjuster out","result":"Harder hit while keeping bottom-end chug","support":1}],"disagreements":[]},{"years":[2024,2025,2026],"generation":"TBI fuel injection, new frame, closed-cartridge coil fork","summary":"Testers agree the TBI 300 XC-W lugs at very low rpm without stalling and delivers smooth, tractor-like low-to-mid torque, with a stronger midrange and longer rev than the TPI bike. The map switch was optional and testers say to buy it, though they disagree on how different the maps feel. The stiffer frame is planted at speed but deflects at low speed in rocks, the shorter coil fork makes the front sit low, and long-term testing found overheating, worse fuel range and fuel pickup problems.","points":[{"aspect":"engine_low","verdict":"strength","statement":"Lugs at very low rpm without bogging or stalling, with smooth, tractor-like low-to-mid torque.","years":[2024],"support":3,"strength":"strong consensus"},{"aspect":"mapping","verdict":"neutral","statement":"Map switch was an optional extra; testers recommend buying it.","years":[2024],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Closed-cartridge coil fork is plush to mid-stroke and stable under braking but about 10 mm shorter, so the front sits low.","years":[2024],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"weakness","statement":"Fuel range is worse than the TPI bike (about 22-32 mpg), and the high fuel pickup can starve the engine with fuel still in the tank.","years":[2024],"support":2,"strength":"consensus"},{"aspect":"engine_mid","verdict":"strength","statement":"Compared with the TPI bike it is mellow down low but far stronger in the midrange and revs much further.","years":[2024],"support":1,"strength":"single source"},{"aspect":"engine_low","verdict":"weakness","statement":"Could not reliably pull third up steep, sandy climbs at altitude that the TPI bike handled.","years":[2024],"support":1,"strength":"single source"},{"aspect":"chassis","verdict":"neutral","statement":"Stiffer frame is more planted and stable at speed but feels unsettled and deflects more over rocks at low speed.","years":[2024],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"neutral","statement":"Riders under about 170 lb need few changes; riders over 200 lb find the shock too soft.","years":[2024],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Runs hot and overheated within minutes of slow technical riding on a long-term bike.","years":[2024],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"On one test bike the oil-level light worked only intermittently and the bike ran out of oil, needing a new piston and rings.","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Front sits low","fix":"Run about 110 mm sag rather than moving the fork","result":"Front lifted","support":1},{"problem":"Rear stiff","fix":"Lower swingarm pivot torque by 5-10%","result":"Less rear stiffness","support":1},{"problem":"Wants more snap","fix":"Aftermarket ECU opening the power valve slightly more","result":"Woke the bike up","support":1},{"problem":"Big ratio gaps","fix":"48-tooth rear sprocket","result":"Tighter gaps but first and second very low","support":1}],"disagreements":[{"topic":"How different the two maps feel","sides":["Difference mostly on top and hard to notice","Map 2 is a big step more aggressive and a handful in tight changes of direction"]}]}],"KTM|250 XC-W":[{"years":[2024,2025,2026],"generation":"TBI fuel injection","summary":"One test found the TBI 250 XC-W has usable power across the range matched to its six-speed, with the damped clutch helping traction; map 2 is a big step more aggressive and can spin the rear unexpectedly.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Usable power across the range, matched to the six-speed; damped clutch softens delivery for traction.","years":[2024],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"neutral","statement":"Map 2 is a big step more aggressive and can spin the rear tire unexpectedly.","years":[2024],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"strength","statement":"250/300 suspension resisted bottoming and stayed consistent when pushed.","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]}],"KTM|150 XC-W":[{"years":[2020,2021,2022,2023],"generation":"TPI fuel injection","summary":"Testers found the TPI 150 XC-W comes on sooner with much more bottom-end torque than the carbureted 150 but signs off early on top. Suspension is set soft for light trail riders, and it needed clearing out after idling.","points":[{"aspect":"engine_low","verdict":"strength","statement":"Comes on sooner with much more bottom-end torque and a strong midrange than the carbureted 150.","years":[2020],"support":1,"strength":"single source"},{"aspect":"engine_top","verdict":"weakness","statement":"Signs off early on top.","years":[2020],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"Set soft for 140-160 lb trail riders; heavier fast riders need stiffer springs at both ends.","years":[2020],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"weakness","statement":"Needed clearing out after idling more than a minute or two.","years":[2020],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]},{"years":[2024,2025,2026],"generation":"TBI fuel injection","summary":"One test found the TBI 150 XC-W pulls well low on map 1 and builds linearly with little over-rev, with flawless fueling; suspension is softer and plusher than on the 250/300, and the undamped clutch means more shifting.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Pulls well low on map 1 and builds linearly with no sharp hit; fueling described as flawless.","years":[2024],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"neutral","statement":"Softer and plusher than the 250/300.","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]}],"KTM|300 XC":[{"years":[2023,2024,2025,2026],"generation":"TBI fuel injection (linkage rear)","summary":"Testers call the TBI 300 XC bold and torquey, tractoring like a four-stroke in slow sections and crisp on top, with more torque than any earlier 300. The 2023 aggressive map was abrupt in technical terrain, and on rocky trails the stiff stock chassis and settings felt harsh, so one long-term owner tamed the power and revalved the suspension.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Bold, torquey engine that tractors through slow sections and turns crisp on top; more torque than any earlier 300.","years":[2023],"support":2,"strength":"consensus"},{"aspect":"mapping","verdict":"weakness","statement":"The 2023 aggressive map was abrupt and hard to control in technical terrain, and the mellow map a big step down.","years":[2023],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"Stiff stock chassis and settings feel harsh on rocky trails.","years":[2023],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Too much power in rocks","fix":"Auto-clutch, slower-turning throttle cam, flywheel weights","result":"More manageable power","support":1},{"problem":"Harsh on rocky trails","fix":"Revalve or replace suspension","result":"Biggest single improvement","support":1}],"disagreements":[]},{"years":[2020,2021,2022],"generation":"TPI fuel injection (linkage rear)","summary":"Testers found the TPI 300 XC very smooth but lethargic off the bottom, with what sounded like low-rpm detonation. The linkage chassis is far more stable at speed than the XC-W but harsher in rocks, and owners riding motocross find the stock shock spring soft near 200 lb.","points":[{"aspect":"engine_low","verdict":"weakness","statement":"Very smooth but lethargic off the bottom, with what sounded like low-rpm detonation.","years":[2021],"support":1,"strength":"single source"},{"aspect":"stability","verdict":"strength","statement":"Linkage rear is far more stable at speed and in big whoops than the XC-W, but harsher on rocks and hangs lower over logs.","years":[2022],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"neutral","statement":"Testers would prefer a spring fork's softer initial stroke for hidden rocks over the air fork.","years":[2021],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"weakness","statement":"Owners riding motocross near 200 lb find the stock 42 N/mm shock spring too soft.","years":[2022],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Lethargic low end","fix":"Race fuel in the mix and a power-valve tool","result":"Livelier engine","support":1},{"problem":"Shock spring soft for 200 lb","fix":"48-50 N/mm spring, 105 mm race sag","result":"Owners report better support","support":1}],"disagreements":[]}],"KTM|250 XC":[{"years":[2020,2021,2022],"generation":"TPI fuel injection","summary":"One owner reported a 2020 250 XC TPI that spluttered at part throttle low to mid and ran rich; a magazine column suggested air-screw and ECU fixes.","points":[{"aspect":"power_delivery","verdict":"weakness","statement":"Spluttery at part throttle from low to mid rpm with a flat top and signs of rich running.","years":[2020],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Part-throttle splutter","fix":"Turn in the throttle-body air screw, get the latest dealer ECU settings, or a replacement ECU/reflash","result":"Reported great results from a tested replacement ECU","support":1}],"disagreements":[]}],"KTM|125 XC":[{"years":[2021,2022],"generation":"carbureted","summary":"In a GNCC race test the carbureted 125 XC pulled well even when lugged in second or third, never felt narrow and needed less clutch than expected; it was raced with only sag set.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Pulls well in second or third even when lugged, never feels narrow and needs less clutch than expected.","years":[2021],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]},{"years":[2025],"generation":"TBI fuel injection","summary":"One tester found the fork plush at first and able to handle all but the biggest motocross hits.","points":[{"aspect":"suspension_front","verdict":"strength","statement":"Fork plush initially and handles all but the biggest track hits.","years":[2025],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]}],"Husqvarna|TE 300":[{"years":[2020,2021,2022,2023],"generation":"TPI fuel injection","summary":"Testers agree the TPI TE 300 makes lots of usable bottom and mid power and is almost impossible to stall, with low vibration and gentle brakes and clutch, though power tapers quickly past the middle. The open-cartridge fork is cushy in rocks but too soft for heavier or aggressive riders and dives under braking. One tester felt a lean tune with light detonation and found the map switch made little difference.","points":[{"aspect":"engine_low","verdict":"strength","statement":"Huge, usable bottom and mid power delivered linearly; very hard to stall and best ridden a gear high.","years":[2020,2021],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Fork too soft for heavier or aggressive riders: dives under braking and bottoms on G-outs, even at maximum preload.","years":[2020,2021],"support":2,"strength":"consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Power tapers quickly past the midrange.","years":[2020],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"strength","statement":"Spring suspension is cushy and excellent in rocks.","years":[2021],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"weakness","statement":"Map switch made a negligible difference; a slightly lean feel and occasional light detonation under low-rpm load were blamed on the emissions tune.","years":[2021],"support":1,"strength":"single source"},{"aspect":"other","verdict":"strength","statement":"Low vibration and reliable electric start; brakes and clutch less grabby than the KTM's.","years":[2020],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Slippery seat cover lets the rider slide back on climbs.","years":[2020],"support":1,"strength":"single source"},{"aspect":"other","verdict":"strength","statement":"Injection improved fuel mileage over the carbureted version (about 7% at sea level, over 20% near 6,000 ft) and cut oil use.","years":[2020,2021,2022,2023],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Fork dives and bottoms, left leg doing most work","fix":"Revalve with rebalanced damping and 15 ml more oil","result":"Bottoming fixed without losing plushness","support":1},{"problem":"Lean, detonating stock tune","fix":"Replacement ECU","result":"Better running and no detonation","support":1}],"disagreements":[]},{"years":[2024,2025,2026],"generation":"TBI fuel injection","summary":"Testers describe the TBI TE 300 as milder at the bottom and stronger in the middle than the TE 250. Its coil fork is cushy at low speed but very soft overall, diving under hard braking, while the shock is good in rocks and stable at speed.","points":[{"aspect":"power_delivery","verdict":"neutral","statement":"Milder bottom and stronger midrange than the TE 250; the aggressive map surges near peak rather than hitting.","years":[2024],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Coil fork is cushy at low speed but very soft overall, diving under hard braking and struggling on G-outs; more compression mostly kills low-speed comfort.","years":[2024],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"strength","statement":"Shock is good in rocks and stable at speed.","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Wants crisper response","fix":"Aftermarket pipe and silencer","result":"Crisper with more bottom-end feel","support":1}],"disagreements":[]}],"Husqvarna|TE 250":[{"years":[2024],"generation":"TBI fuel injection","summary":"One launch test found the TBI TE 250 snappy from the start and clearly stronger than the TE 150.","points":[{"aspect":"power_delivery","verdict":"neutral","statement":"Snappy from the start; much stronger than the TE 150.","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]}],"Husqvarna|TE 150":[{"years":[2024],"generation":"TBI fuel injection","summary":"One launch test found the TBI TE 150 has a strong, four-stroke-like bottom end with two-stroke snap when the clutch is flicked.","points":[{"aspect":"engine_low","verdict":"strength","statement":"Strong, four-stroke-like bottom end with two-stroke snap on a clutch flick.","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]}],"Husqvarna|TX 300":[{"years":[2020,2021,2022],"generation":"TPI fuel injection (cross-country, air fork)","summary":"One magazine found the TPI TX 300 top-end biased, with a soft spot around 7,000 rpm before a strong kick to sign-off, and ran the aggressive map all the time. Testers agree the fuel delivery is its weak spot: it cut out when whipped low on fuel and the in-tank pump occasionally failed. The air fork bottoms below about 144 psi.","points":[{"aspect":"reliability","verdict":"weakness","statement":"Fuel delivery is the weak point: the engine can quit when low on fuel and leaned over, and the in-tank pump occasionally fails.","years":[2020],"support":2,"strength":"consensus"},{"aspect":"power_delivery","verdict":"neutral","statement":"Top-end biased: soft spot around 7,000 rpm, then a strong kick from 8,000 rpm to sign-off; testers ran the aggressive map all the time.","years":[2020],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"neutral","statement":"Below about 144 psi the fork bottoms on big hits; 102-108 mm sag is the sweet spot.","years":[2020],"support":1,"strength":"single source"},{"aspect":"tires","verdict":"weakness","statement":"18-inch rear off-road tire is poor for motocross use.","years":[2020],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"More power","fix":"Aftermarket pipe","result":"About 3 hp more at 7,500 and 9,000 rpm","support":1},{"problem":"Front-end push","fix":"Raise the fork tubes in the clamps","result":"Push cured","support":1}],"disagreements":[]},{"years":[2023,2024,2025,2026],"generation":"TBI fuel injection","summary":"One full test found suspension the main area to improve on the TBI TX 300, with off-road air-fork valving and shorter travel than the KTM 300 XC for a lower seat; its two maps range from mild to very aggressive.","points":[{"aspect":"suspension_front","verdict":"weakness","statement":"Suspension is the main area needing improvement.","years":[2023],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"neutral","statement":"Two bar-switch maps range from mild to very aggressive.","years":[2023],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]}],"GasGas|EX 300":[{"years":[2021,2022,2023],"generation":"TPI fuel injection","summary":"Testers found the TPI EX 300 strong with spot-on throttle response but wanting a smoother bottom for slow trail, with lean spots until fully warm. Its air fork and shock felt stiff and harsh for trail riding and needed constant attention. It ships without a map switch, handguards or skid plate.","points":[{"aspect":"suspension_front","verdict":"weakness","statement":"Air fork and shock feel jarringly stiff for trail riding and deflect in fast chatter; they need constant attention.","years":[2021,2022],"support":2,"strength":"consensus"},{"aspect":"power_delivery","verdict":"neutral","statement":"Plenty of power and spot-on throttle response, but the bottom end could be smoother for slow technical trail and it runs lean until warm.","years":[2022],"support":1,"strength":"single source"},{"aspect":"other","verdict":"weakness","statement":"No handguards or skid plate, vulnerable exhaust and no map switch.","years":[2022],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Harsh fork in fast chatter","fix":"Lower air pressure, more compression clicks out and slower rebound","result":"Comfort with enough hold-up; shock still soft on big hits","support":1},{"problem":"Find the power sweet spot","fix":"Slow the power-valve opening slightly (about a quarter turn)","result":"Delivery suited to the rider","support":1}],"disagreements":[]},{"years":[2024,2025,2026],"generation":"TBI fuel injection","summary":"Testers find the TBI EX 300 pulls from very low revs and can be lugged almost to idle, with most power bottom to mid and the TPI's lean surge mostly gone, though the power-valve tune feels conservative. It lacks a map switch, handguards and skid plate, its Braktec brakes fade sooner than Brembos, and testers note TPS recalibration and a high fuel pickup. Sag runs high stock, so testers shorten the shock or lower it.","points":[{"aspect":"engine_low","verdict":"strength","statement":"Pulls from very low revs and can be lugged almost to idle; most power is bottom to mid and the TPI's low-rpm lean surge is mostly gone.","years":[2024,2025],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"weakness","statement":"Ships without a map switch, handguards or skid plate.","years":[2024,2025],"support":2,"strength":"consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Power-valve tune feels conservative.","years":[2025],"support":1,"strength":"single source"},{"aspect":"brakes","verdict":"weakness","statement":"Braktec brakes fade faster than Brembo, especially the rear.","years":[2025],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"neutral","statement":"Throttle position sensor may need recalibrating every 15-20 hours; fuel pickup sits high and can starve the engine with fuel left.","years":[2025],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"neutral","statement":"Good balance, with occasional bottoming under heavy loads.","years":[2025],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Sag too high (107-108 mm)","fix":"Shorten the shock 1-3 mm internally; fork flush or slightly below in clamps","result":"100-105 mm sag; dropping the fork further cost front grip","support":1},{"problem":"Gearing tall for most riding","fix":"14/50 to 14/52 (14/49 for fast terrain)","result":"Better gear use","support":1}],"disagreements":[]}],"GasGas|EC 300":[{"years":[2021,2022,2023],"generation":"TPI fuel injection (enduro, linkage rear)","summary":"Testers found the TPI EC 300 a little mellower than the carbureted bikes and lean-feeling until warm, but able to tractor through rough terrain. Its coil suspension is trail-oriented and soft for riders over about 170-175 lb, and its front brake is weaker than the KTM and Husqvarna units. Backing out the power-valve adjuster sharpens the midrange.","points":[{"aspect":"suspension_front","verdict":"weakness","statement":"Trail-oriented coil suspension is soft for riders over about 170-175 lb; even a light expert wanted more support on G-outs.","years":[2021,2022],"support":2,"strength":"consensus"},{"aspect":"power_delivery","verdict":"neutral","statement":"A little mellower than the carbureted bikes and slightly lean until warm, but tractors through rugged terrain.","years":[2022],"support":1,"strength":"single source"},{"aspect":"brakes","verdict":"weakness","statement":"Front brake is the weak point: firm lever but less stopping power than the KTM and Husqvarna siblings.","years":[2022],"support":1,"strength":"single source"},{"aspect":"weight_feel","verdict":"weakness","statement":"About 12 lb heavier than a PDS 300 XC-W.","years":[2021],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Wants more midrange hit","fix":"Back the power-valve adjuster out (about two turns)","result":"Opens sooner with a stronger midrange","support":2},{"problem":"Suspension soft for weight","fix":"Stiffer springs both ends or closed-cartridge kit","result":"More support","support":1},{"problem":"Lean, detonating stock tune","fix":"Replacement ECU","result":"Ran better from the bottom up, no detonation","support":1}],"disagreements":[]},{"years":[2024,2025,2026],"generation":"TBI fuel injection (enduro)","summary":"Testers find the TBI EC 300 can crawl at almost closed throttle without stalling, with a stout bottom, crisp midrange and smooth, linear power that no longer lean-pops like the TPI, though it lacks some of the carburetor bikes' snap. It ships without a map switch, and its open-cartridge fork is less consistent than the KTM's and bottoms when pushed.","points":[{"aspect":"engine_low","verdict":"strength","statement":"Crawls at almost closed throttle without stalling; stout bottom and crisp midrange with smooth, linear delivery.","years":[2024],"support":2,"strength":"consensus"},{"aspect":"power_delivery","verdict":"neutral","statement":"Smoother and more four-stroke-like than older carbureted 300s, which hit harder off the bottom.","years":[2024],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Open-cartridge fork is less consistent and less plush over small bumps than the KTM's closed-cartridge fork and bottoms when pushed; fine for casual riding.","years":[2024],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"neutral","statement":"No map switch fitted; the optional switch plugs straight in (white for rock crawling, green for mud and open trail).","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]}],"Suzuki|RM-Z250":[{"years":[2020,2021,2022,2023,2024,2025,2026],"generation":"2019-2026 platform (data covers 2020-2026)","summary":"Testers across every outlet agree the RM-Z250 is sprung far too stiff for typical 250 riders, the fork above all, and that softer springs or a revalve transform it. The engine pulls well low but flattens through the mid and top, it is the least powerful 250 on magazine dynos, and it has placed last in recent shootouts. With the suspension sorted it is rated among the best-cornering 250Fs, and its easy power suits novices and intermediates. The frame feels stiff on chop, the clutch slips when worked hard, and testers run the aggressive white coupler.","points":[{"aspect":"suspension","verdict":"weakness","statement":"Stock fork and shock springs are far too stiff for most riders; the fork deflects and rides harsh on small and dry chop, and some testers found it nearly unrideable.","years":[2020,2021,2022,2023,2024,2025,2026],"support":6,"strength":"strong consensus"},{"aspect":"engine_mid","verdict":"weakness","statement":"Good snap off the bottom, but power flattens through the midrange and signs off on top, so it must be short-shifted and recovers poorly after a short shift.","years":[2020,2021,2023,2024],"support":4,"strength":"strong consensus"},{"aspect":"other","verdict":"weakness","statement":"Finishes last in recent multi-bike 250 shootouts.","years":[2023,2024,2025],"support":3,"strength":"strong consensus"},{"aspect":"chassis","verdict":"weakness","statement":"Aluminum frame feels stiff over chop and slap-downs.","years":[2020,2022,2025],"support":3,"strength":"strong consensus"},{"aspect":"mapping","verdict":"neutral","statement":"Of the plug-in couplers, white is the most aggressive and freest-revving and is the testers' usual pick; the mellow coupler suits newer riders.","years":[2020,2022,2023,2024,2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Lowest peak power in the class on magazine dynos, roughly 4-5 hp behind the leading 250s, and more than a stock rival even after expensive engine work.","years":[2021,2022,2023,2025],"support":2,"strength":"consensus"},{"aspect":"turning","verdict":"strength","statement":"Once the suspension is softened it is rated the best- or among the best-cornering 250Fs, rewarding riders who steer with the front.","years":[2020],"support":2,"strength":"consensus"},{"aspect":"engine_low","verdict":"strength","statement":"Torquey, easy power and a light, nimble feel suit novice to intermediate riders, though it gives away too much on top for advanced classes.","years":[2021],"support":2,"strength":"consensus"},{"aspect":"clutch","verdict":"weakness","statement":"Clutch slips under heavy load or after hard riding, and plates wear quickly.","years":[2020,2021,2023,2024],"support":2,"strength":"consensus"},{"aspect":"mapping","verdict":"strength","statement":"On the RM Army edition, the a tester map with the a tester exhaust is clearly better than stock.","years":[2024,2025],"support":2,"strength":"consensus"},{"aspect":"reliability","verdict":"strength","statement":"No significant failures reported on hard-raced test bikes.","years":[2020,2021],"support":2,"strength":"consensus"},{"aspect":"suspension_rear","verdict":"weakness","statement":"Rear sits high and stiff at stock sag, costing rear traction.","years":[2020],"support":1,"strength":"single source"},{"aspect":"transmission","verdict":"weakness","statement":"Shifts are notchy under load and it vibrates more than other 250s.","years":[2020],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"neutral","statement":"Stock 13/50 gearing is kept unchanged by a tester year after year.","years":[2022,2023,2024,2025,2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Fork and shock too stiff, harsh on chop","fix":"Drop one or two spring rates (about 4.7-4.9 N/mm fork, 50 N/mm shock), set sag around 105-108 mm and back fork compression out 3-5 clicks","result":"More compliance and traction, calmer chassis, better turning and stability","support":6},{"problem":"Stiff suspension even after clicker changes","fix":"Revalve with lighter springs","result":"Comfort without losing bottoming resistance; called a big gain","support":4},{"problem":"Stiff fork when keeping stock springs","fix":"Compression fully out and fork oil level lowered (20-30 cc / about 30 mm per leg)","result":"Usable stopgap; revalve and respring still preferred","support":1},{"problem":"Stiff frame on chop","fix":"More compliant engine mounts (drilled stock mounts or aftermarket)","result":"Softer over chop and slap-downs, more front bite","support":3},{"problem":"Flat midrange and weak top","fix":"Aftermarket exhaust with matching map, or head port, valve job and ECU tuning","result":"Better character; about 10% more mid-top on the dyno with engine work","support":3},{"problem":"Clutch slip","fix":"Stiffer clutch springs or an aftermarket clutch pack","result":"Hooks up under load, lighter pull with the clutch pack","support":2},{"problem":"Feels air-starved when ridden hard","fix":"Trim the side-panel snorkels and open the airbox edges","result":"Better response and pull everywhere; louder and the filter dirties faster","support":1}],"disagreements":[{"topic":"Bottom-end strength","sides":["Strong snap off idle and good low-mid pull","Low-end torque unremarkable, slow throttle response and down on acceleration","Revs hard mid-top but lacks low end, needs frequent shifting"]},{"topic":"Front brake","sides":["Controllable with no fade over a long hilly moto","Front brake weak and fades"]},{"topic":"Rear end at stock settings","sides":["Rear rides high and stiff","Rear feels loose while the front is stiff"]}]}],"Suzuki|RM-Z450":[{"years":[2020,2021,2022,2023,2024,2025,2026],"generation":"2018-2026 platform (data covers 2020-2026)","summary":"Testers consistently praise the RM-Z450's cornering and its smooth, easy powerband, but say it revs out early, is low on peak power and is the heaviest 450, with no electric start or hydraulic clutch. The air-free BFRC shock is the most repeated complaint: hard to tune, harsh over bumps and short on rebound control, so the rear rides high and the bike sits nose-down. The coil fork is usually judged harsh early in the stroke. Common fixes are a longer shock link with more sag, raising the fork in the clamps, a revalve or RM-Z250 shock, and a 13/51 sprocket.","points":[{"aspect":"turning","verdict":"strength","statement":"Sharp turn-in, leans into corners easily, holds ruts and tracks well through every phase of a turn.","years":[2020,2023,2024,2025,2026],"support":5,"strength":"strong consensus"},{"aspect":"suspension_rear","verdict":"weakness","statement":"The air-free BFRC shock is hard to tune (adjusters work in turns), gets harsh over repeated bumps and off-cambers, and lacks rebound control so the rear rises or kicks off the throttle.","years":[2020,2021,2022,2023,2024,2025,2026],"support":5,"strength":"strong consensus"},{"aspect":"balance","verdict":"weakness","statement":"Stock balance is off: the rear sits high and overpowers the front, giving a nose-down stance that makes the front knife on corner entry.","years":[2020,2021,2024],"support":4,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Coil fork is stiff early in the stroke for most riders and benefits from softening or a revalve.","years":[2021,2022,2023,2024,2025],"support":4,"strength":"strong consensus"},{"aspect":"engine_mid","verdict":"strength","statement":"Power is smooth, linear and broad with a strong low-mid; testers say it suits beginners through pros.","years":[2020,2021,2022,2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Revs out early and fades past about 9,000 rpm, so it works best short-shifted.","years":[2020,2022,2023,2025],"support":3,"strength":"strong consensus"},{"aspect":"clutch","verdict":"weakness","statement":"Stock clutch fades or heats when worked hard and has a narrow engagement.","years":[2021,2026],"support":3,"strength":"strong consensus"},{"aspect":"mapping","verdict":"neutral","statement":"Testers prefer the aggressive (white) coupler or an aggressive tuner map for a livelier hit and more exit pull.","years":[2020,2021,2022,2026],"support":3,"strength":"strong consensus"},{"aspect":"reliability","verdict":"strength","statement":"Long-term bikes ran a year or 30+ hours with only routine maintenance.","years":[2020,2021,2025],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Fork can be soft late in the stroke for a 450, diving and bottoming under heavier or faster riders.","years":[2020,2023,2024],"support":2,"strength":"consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Low peak power for the class on magazine dynos (lowest of its group in 2023, lower half of twelve in 2026) and less torque than most rivals.","years":[2023,2026],"support":2,"strength":"consensus"},{"aspect":"weight_feel","verdict":"weakness","statement":"Heaviest 450 on magazine scales, about 238-241 lb without fuel.","years":[2020,2022,2025,2026],"support":2,"strength":"consensus"},{"aspect":"features","verdict":"weakness","statement":"Kick start only and a cable clutch; the kick lever sits high for shorter riders.","years":[2020,2021,2025,2026],"support":2,"strength":"consensus"},{"aspect":"stability","verdict":"weakness","statement":"Rigid chassis gives head shake in successive chop and twitchiness at speed in the rough.","years":[2020,2021,2023,2025],"support":2,"strength":"consensus"},{"aspect":"electronics","verdict":"weakness","statement":"The phone tuning app is clunkier than rivals' and needs an external battery to load maps.","years":[2023,2024],"support":2,"strength":"consensus"},{"aspect":"brakes","verdict":"weakness","statement":"Front brake is powerful but grabby.","years":[2020,2025],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"weakness","statement":"Cold-blooded and rich for the first lap.","years":[2025],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"A lightly used loaner test bike arrived with a leaking shock seal.","years":[2021],"support":1,"strength":"single source"},{"aspect":"tires","verdict":"weakness","statement":"Stock tires lost grip as the track dried.","years":[2024],"support":1,"strength":"single source"},{"aspect":"chassis","verdict":"neutral","statement":"A fresh 2022 felt far more balanced and stable on stock clickers than a used 2021, pointing to wear or unit variation.","years":[2021,2022],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Shuffling between second and third, weak drive out of tight turns","fix":"One or two teeth larger rear sprocket (13/51 instead of 13/50)","result":"Reaches third sooner and drives harder out of turns","support":3},{"problem":"Rear rides high, nose-down stance, front knifes on entry","fix":"Longer (about 1 mm) shock link, sag 105-110 mm, and fork raised 2-5 mm or flush in the clamps","result":"Calmer rear on deceleration, better balance and corner entry","support":4},{"problem":"Shock harsh with little rebound control","fix":"Shock revalve (with softer springs), or fit the RM-Z250 KYB shock","result":"Revalve removed the mid-corner lift; swap suggested by testers","support":4},{"problem":"Shock harsh at stock clickers","fix":"Shock compression about 1-1.25 turns out and rebound 1-1.5 turns out (from about 3)","result":"More comfort while keeping hold-up","support":2},{"problem":"Fork soft late in the stroke","fix":"About 10 cc more oil per leg and more fork compression (about 4 clicks stiffer)","result":"Firmer last part of the travel and better front-rear balance","support":2},{"problem":"Head shake in chop","fix":"Softer-flexing triple clamps, lowering the rear and raising the front, or a revalve","result":"Settled corner entry and less head shake, not fully cured","support":2},{"problem":"Lethargic or weak bottom-end pull","fix":"Aftermarket exhaust, higher-compression piston and aggressive map","result":"Cleaner, longer pull and more exit drive","support":1},{"problem":"Clutch fade","fix":"Full aftermarket clutch kit","result":"Firmer engagement and longer plate life","support":1},{"problem":"Coolant loss in long motos","fix":"Higher-pressure radiator cap (1.8-2.0 kg/cm2)","result":"Stopped the loss","support":1}],"disagreements":[{"topic":"Stock shock","sides":["Works well out of the box","Harsh, hard to tune and short on rebound control"]},{"topic":"Fork stiffness","sides":["Stiff early in the stroke, soften compression","Soft late in the stroke or front softer than rear; add oil and compression","Front suspension rated excellent"]},{"topic":"Stability","sides":["Head shake and twitchiness at speed","Fairly stable; weight and fresh parts add stability"]},{"topic":"Bottom-end strength","sides":["Strong low end with best pull around 7,000-8,800 rpm","Lacks bottom pull and recovers slowly a gear high"]}]}],"Triumph|TF 250-X":[{"years":[2024,2025,2026],"generation":"First generation (2024-2026; 2027 update not yet tested)","summary":"Testers rate the TF 250-X chassis as its best trait: light, stable and very good in corners, though the stock KYB setting is soft and aimed at a mid-weight novice or intermediate rider. The 2024 engine bogged on a hard throttle snap and made its power high in the rev range; the 2025 map update reduced but did not fully cure the low-rpm stumble for every tester. Tall gearing, gaps between 2nd, 3rd and 4th and a stiff, notchy gearbox are the most repeated complaints. Common first changes are less rear sag, a tooth or two more on the rear sprocket, a 110 rear tyre and stiffer springs for heavier riders.","points":[{"aspect":"turning","verdict":"strength","statement":"Chassis is light, nimble and stable, with very good corner speed and a forgiving amount of flex; several testers called it the most fun bike in the class to ride in stock form.","years":[2024,2025,2026],"support":6,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Stock KYB setting is soft and plush, suited to roughly 155-175 lb novice and intermediate riders; faster or heavier riders bottom the shock on big landings and the fork dives under hard braking.","years":[2024,2025,2026],"support":6,"strength":"strong consensus"},{"aspect":"mapping","verdict":"strength","statement":"The 2025 fuel map (also a dealer flash for 2024 bikes) cleaned up much of the low-rpm stumble and added measurable power over the 2024 calibration.","years":[2024,2025],"support":4,"strength":"strong consensus"},{"aspect":"gearing","verdict":"weakness","statement":"Stock 13/48 gearing feels tall with wide 2-3 and 3-4 gaps; most testers went one or two teeth larger on the rear to help third-gear recovery.","years":[2024,2025,2026],"support":4,"strength":"strong consensus"},{"aspect":"transmission","verdict":"weakness","statement":"Shifting is stiff and notchy, especially into third, with occasional false neutrals; it eases somewhat with break-in.","years":[2024,2025,2026],"support":4,"strength":"strong consensus"},{"aspect":"engine_low","verdict":"weakness","statement":"2024 engine is crisp just off idle but bogs or stumbles when the throttle is snapped, then dips and surges into the midrange; low end and midrange were its weakest areas against class leaders.","years":[2024],"support":3,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"neutral","statement":"Power sits high in the range; it works best revved toward the limiter rather than short-shifted, and the gear gaps make that more necessary.","years":[2024,2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"tires","verdict":"weakness","statement":"Stock Pirelli rear in 100/90-19 on a narrow 1.85 rim limits traction and its carcass rolls or folds under load once worn; a 110 rear is the preferred swap.","years":[2024,2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"engine_mid","verdict":"weakness","statement":"On dynos it trails the KTM-family 250s by roughly 1.5-4 hp through most of the midrange and top, landing mid-pack on peak power.","years":[2024,2025],"support":2,"strength":"consensus"},{"aspect":"suspension_rear","verdict":"weakness","statement":"Rear sits low under load at the handbook sag, and the shock wants more end-of-stroke support.","years":[2024,2025],"support":2,"strength":"consensus"},{"aspect":"balance","verdict":"neutral","statement":"Bike is sensitive to fork height, sag and shock high-speed compression changes; small adjustments change its balance noticeably.","years":[2024,2025],"support":2,"strength":"consensus"},{"aspect":"electronics","verdict":"weakness","statement":"The tuning app only loads preset maps; fuel and ignition cannot be edited, which testers see as a limitation versus Japanese tuning apps.","years":[2024,2025],"support":2,"strength":"consensus"},{"aspect":"electronics","verdict":"weakness","statement":"Motocross testers mostly left traction control off because it dulled the power.","years":[2024],"support":2,"strength":"consensus"},{"aspect":"weight_feel","verdict":"strength","statement":"Weighs in among the lightest 250s on magazine scales.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"maintenance","verdict":"weakness","statement":"Torx fasteners throughout mean special tools rather than standard T-handles.","years":[2024,2025],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"neutral","statement":"Placed mid-to-low in group shootouts: seventh of eight in one 2025 test, fourth of seven in a 2026 test.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"turning","verdict":"weakness","statement":"Tends to stand up mid-corner in tight turns, partly blamed on the narrow 100-section stock rear tyre.","years":[2024],"support":1,"strength":"single source"},{"aspect":"stability","verdict":"weakness","statement":"Front can feel busy entering fast, rough corners.","years":[2024],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"weakness","statement":"Clutch can turn notchy, slip under acceleration or drag, attributed to poor oil flow through the stock clutch centre; recall work fits a new hub and plates.","years":[2024,2025],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Isolated owner reports of stalling (including off a jump face) and one bike that jumped cam timing after a slow tip-over.","years":[2024,2025],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Rear rides low and bottoms at the handbook 105 mm sag","fix":"Run 100-104 mm race sag and add shock high-speed compression","result":"Rear holds up under throttle and the bike turns more readily","support":5},{"problem":"Soft fork for faster riders","fix":"Add 2-4 clicks of fork compression and run the fork about 3 mm up (or drop it in the clamps on fast tracks to calm a busy front)","result":"More hold-up and better balance; lowering the fork calmed fast rough corners at some cost to turning","support":3},{"problem":"Stock springs too soft for riders over about 80 kg","fix":"Fit Triumph medium or hard spring sets","result":"Bike could be pushed harder with more confidence on jumps and corners, no clicker changes needed","support":3},{"problem":"Tall gearing and gappy 2nd-3rd","fix":"13/49 or 13/50 rear (KTM rear sprockets fit), chain lengthened as needed","result":"Better third-gear recovery and tighter gear spread","support":4},{"problem":"Low-rpm bog on 2024 bikes","fix":"Dealer flash to the 2025 calibration or the richer Akrapovic map","result":"Bog greatly reduced, though the dip-and-surge shape did not fully disappear for every tester","support":3},{"problem":"Wants more corner-exit pull","fix":"Aftermarket full exhaust (FMF or Akrapovic) with matching map","result":"Stronger 2nd and 3rd gear pull and longer midrange; the FMF system softened the initial crack off idle slightly","support":4},{"problem":"Rear traction and mid-corner stand-up","fix":"Swap to a 110-section rear tyre (often Dunlop MX34)","result":"Better traction for most testers; one test felt little change","support":2}],"disagreements":[{"topic":"How completely the 2025 map fixed the low-rpm stumble","sides":["Hesitation and midrange dip removed","Sputter fixed but some bog remains low down"]},{"topic":"Stock suspension balance","sides":["Well balanced out of the box and needing little tuning","Too soft and bottoms easily","Fork slightly stiffer than the shock"]},{"topic":"Preferred stock map","sides":["Map 1 (standard) is stronger in the midrange","Map 2 (soft) preferred and loses little power"]},{"topic":"Quickshifter","sides":["Helps with the stiff gearbox and works well","Ignition cut is distracting, drops out if the lever is not fully lifted, or shifts irregularly"]},{"topic":"Stock gearing","sides":["13/48 felt right at the launch","Too tall; go 1-2 teeth larger"]},{"topic":"Footpegs packing with mud","sides":["Pegs pack with mud","Mud never packed the peg pivot"]}]}],"Triumph|TF 450-RC Edition / TF 450-X":[{"years":[2025,2026],"generation":"First generation 450 MX (2025 RC Edition, 2026 450-X)","summary":"Testers describe the Triumph 450 as smooth and linear rather than brutal: mild off the bottom in the standard map, strong in the midrange and tapering on top, easy to ride over long motos. The chassis earns the most praise for stability and cornering, while the front end can feel vague or light off the throttle. Stock KYB settings are soft and comfortable for a mid-weight rider, though one shootout found the fork harsh and the shock dead. Tall gearing, notchy shifting with false neutrals on early bikes and a vague stock clutch are the recurring complaints.","points":[{"aspect":"sag","verdict":"neutral","statement":"Testers settled at 100-104 mm race sag rather than the 105 mm standard; the 2026 bike was sensitive to small sag measuring errors.","years":[2025,2026],"support":6,"strength":"strong consensus"},{"aspect":"turning","verdict":"strength","statement":"Stable at speed and under braking, good in ruts and strong in corners; one of the best straight-line 450s and the chassis is its best trait.","years":[2025,2026],"support":5,"strength":"strong consensus"},{"aspect":"front_end","verdict":"weakness","statement":"Front end feels light or vague off the throttle and can push in corners; it is harder to lean in than testers wanted.","years":[2025,2026],"support":4,"strength":"strong consensus"},{"aspect":"gearing","verdict":"weakness","statement":"Stock gearing feels tall and needs extra clutch on tight tracks; a gap between 2nd and 3rd is noticeable.","years":[2025,2026],"support":4,"strength":"strong consensus"},{"aspect":"power_delivery","verdict":"strength","statement":"Delivery is smooth and linear rather than aggressive, easy on the rider over long motos and closer in character to the milder Japanese 450s.","years":[2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"engine_low","verdict":"weakness","statement":"Initial throttle and bottom end feel soft or disconnected in the standard map; testers wanted more bottom-to-mid pull.","years":[2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"neutral","statement":"Stock KYB setting is soft and comfortable, aimed at a roughly 170-175 lb novice or intermediate; faster or heavier riders use up the travel in rough second motos.","years":[2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Top end tapers early and over-rev is rough near the limiter, so it works best shifted earlier than most 450s.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"engine_mid","verdict":"strength","statement":"Measures competitively on dynos (top of one eight-bike test, third of twelve in another) yet feels milder than its numbers because the curve is so smooth.","years":[2026],"support":2,"strength":"consensus"},{"aspect":"mapping","verdict":"strength","statement":"The Carmichael-developed map on the RC Edition is sharper low down with more hit and pull, and testers preferred it to the standard map.","years":[2025],"support":2,"strength":"consensus"},{"aspect":"transmission","verdict":"weakness","statement":"Early bikes shift notchily under power with false neutrals between 2nd-3rd and 3rd-4th; owners report gearbox parts updated by a service bulletin.","years":[2025],"support":2,"strength":"consensus"},{"aspect":"clutch","verdict":"weakness","statement":"Stock clutch feels light and vague with a long, soft engagement.","years":[2025],"support":2,"strength":"consensus"},{"aspect":"weight_feel","verdict":"strength","statement":"Among the lightest 450s on magazine scales.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"reliability","verdict":"neutral","statement":"A 20-hour test bike needed nothing beyond oil changes; early bikes had a water-pump whine that faded after break-in.","years":[2025],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"neutral","statement":"Fork rides high in its stroke despite being soft, which lets riders run more rear preload.","years":[2025],"support":1,"strength":"single source"},{"aspect":"vibration","verdict":"weakness","statement":"More vibration than most Japanese 450s.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"tires","verdict":"strength","statement":"A 120-section rear tyre helped the shock keep the rear on the ground.","years":[2025],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Tall gearing, 2nd-3rd gap","fix":"One or two teeth larger rear (13/49-13/50, longer chain); heavier owners up to 13/52","result":"Better drive out of turns and improved engine and chassis feel","support":4},{"problem":"Front light or pushing in corners","fix":"Less rear sag (100-102 mm), a few clicks more fork compression, fork raised 1-2 mm","result":"Better front-end tracking in ruts and more bite","support":3},{"problem":"Front hard to feel off the throttle","fix":"Aftermarket triple clamps","result":"Improved off-throttle front-end tracking","support":1},{"problem":"Vague clutch with soft bite","fix":"Aftermarket clutch kit with stiffer spring and extra steel plates","result":"Firmer pull, more bite and shorter engagement; noticeable but not dramatic","support":2},{"problem":"Wants more low-mid pull","fix":"FMF full system or opening the stock muffler baffle","result":"FMF gave longer, stronger midrange in 2nd and 3rd with a softer initial crack; baffle mod gave only a small gain","support":2},{"problem":"Heavier riders (195-240 lb) blowing through the fork","fix":"More fork oil (about 10 cc per leg) or stiffer fork springs, plus slightly stiffer compression and slower rebound","result":"Better g-out and jump-face support","support":2},{"problem":"Notchy shifts and false neutrals on early bikes","fix":"Dealer gearbox update; one owner polished gear dogs and shift-fork parts","result":"Owner reported cleaner shifting; bulletin outcome not yet confirmed","support":1}],"disagreements":[{"topic":"Suspension quality on stock settings","sides":["Plush, good hold-up and balanced for a mid-weight rider","Fork harsh and inconsistent, shock dead (all three testers in one 2026 shootout)"]},{"topic":"Bottom-end character","sides":["Soft off the bottom in the standard map","Standard map snappy and abrupt off the bottom","Good pull from just above idle, usable lugged a gear high"]},{"topic":"Carmichael map","sides":["Sharper with more low-end hit","More controllable and linear than the standard map"]},{"topic":"Stock clutch durability","sides":["Plates lasted about 10 hours","Stock clutch held up over 20 hours"]},{"topic":"Overall standing","sides":["Last of eight in a 2026 shootout","Even with a YZ450F head to head","Would have finished near the front of a 2025 shootout"]},{"topic":"Spring rates for lighter riders","sides":["Stock springs suit a 170-175 lb rider","Riders at or under 170 lb may find stock springs too stiff"]}]}],"Triumph|TF 450-C":[{"years":[2026],"generation":"First generation cross-country (2026)","summary":"Few independent tests exist, all from wet clay woods launches. Testers liked the linear, connected roll-on and midrange, and one found it unusually resistant to stalling at low rpm, while another found little bottom end on tight greasy trail. Traction control split opinion, and two testers ran less sag than standard to help tight turning.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Roll-on is linear and connected, with the midrange as its strength.","years":[2026],"support":2,"strength":"consensus"},{"aspect":"electronics","verdict":"strength","statement":"Traction control raised for slick clay limited wheelspin and kept the rear in check.","years":[2026],"support":2,"strength":"consensus"},{"aspect":"engine_low","verdict":"neutral","statement":"Did not stall at low rpm in tight trail the way most 450s do.","years":[2026],"support":1,"strength":"single source"},{"aspect":"suspension","verdict":"strength","statement":"Fork resisted bottoming on fast drop-offs and the shock used its full stroke for a 180 lb rider on stock clickers.","years":[2026],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Engine flamed out at low speed under heavy throttle late in the day, with slow restarts; tester suspected rich mapping.","years":[2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Slow turning in tight switchbacks","fix":"Run 102 mm race sag instead of the 105 mm standard","result":"More front weight bias and better turning","support":2}],"disagreements":[{"topic":"Low-end strength in tight trail","sides":["Little bottom end; needs revs and momentum","Pulls linearly and does not stall at low rpm"]},{"topic":"Traction control","sides":["Useful on slick clay","Made the throttle feel flat; turned off"]},{"topic":"Race sag","sides":["102 mm for tight woods","108 mm on stock clickers"]}]}],"Triumph|TF 250-C":[{"years":[2026],"generation":"First generation cross-country (2026)","summary":"No independent tester or rider findings were found for the TF 250-C. It shares its platform with the TF 250-X, so 250-X engine and chassis findings are the closest reference, but nothing here confirms how the C-specific suspension and mapping ride.","points":[],"common_fixes":[],"disagreements":[]}],"Triumph|TF 250-E":[{"years":[2026],"generation":"First generation enduro (2026)","summary":"Launch testers found the 250-E pulls cleanly from low revs without stalling, with a strong midrange that lets it hold gears longer. The upshift quickshifter can refuse a shift under hard acceleration. Suspension and clutch impressions were mixed between tests.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Pulls smoothly from low revs without stalling or popping, with a stronger midrange than expected that lets it hold each gear longer.","years":[2026],"support":4,"strength":"strong consensus"},{"aspect":"electronics","verdict":"weakness","statement":"Quickshifter works best at high revs and full throttle and sometimes fails to engage the next gear under hard acceleration.","years":[2026],"support":2,"strength":"consensus"},{"aspect":"electronics","verdict":"strength","statement":"Traction control trims wheelspin rather than cutting power and works well in wet conditions.","years":[2026],"support":2,"strength":"consensus"},{"aspect":"engine_low","verdict":"weakness","statement":"On long steep climbs it needed a couple of stops where the 450-E went straight up.","years":[2026],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"neutral","statement":"Difference between the soft and standard maps is noticeable but not extreme; the soft map suits singletrack.","years":[2026],"support":1,"strength":"single source"},{"aspect":"suspension","verdict":"strength","statement":"Baseline is firm but not harsh, and most riders can skip a suspension shop.","years":[2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Handling not settled","fix":"A couple of clicks more compression and 40 mm static sag (set with a KYB technician)","result":"Calmer handling","support":1}],"disagreements":[{"topic":"Clutch feel","sides":["Excellent, can lug up a hill with one finger","Heavy clutch pull"]}]}],"Triumph|TF 450-E":[{"years":[2026],"generation":"First generation enduro (2026)","summary":"Testers describe the 450-E as linear, controllable and easy to lug, with a strong midrange and a light, almost 350-like feel. The main chassis complaint is a fork that is softer than the shock and dives on braking or at speed, which several testers balanced by lowering the rear. The rev limiter is abrupt and the quickshifter can balk under hard acceleration.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Delivery is linear and controllable with a broad torque spread; it lugs well and feels lighter than its size.","years":[2026],"support":5,"strength":"strong consensus"},{"aspect":"mapping","verdict":"neutral","statement":"The soft map is noticeably smoother and suits casual trail riding or mud, while the standard map suits racing.","years":[2026],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Fork is softer than the shock and dives on hard braking or reaches its limits at speed on rough ground.","years":[2026],"support":3,"strength":"strong consensus"},{"aspect":"engine_mid","verdict":"strength","statement":"Midrange is its standout and pulls harder than a typical trail bike.","years":[2026],"support":2,"strength":"consensus"},{"aspect":"electronics","verdict":"weakness","statement":"Quickshifter sometimes fails to engage the next gear under hard acceleration.","years":[2026],"support":2,"strength":"consensus"},{"aspect":"electronics","verdict":"strength","statement":"Traction control keeps slip low in wet conditions.","years":[2026],"support":2,"strength":"consensus"},{"aspect":"suspension_rear","verdict":"weakness","statement":"Shock rebound is a little fast and the rear could use more bottoming resistance in big high-speed whoops.","years":[2026],"support":1,"strength":"single source"},{"aspect":"engine_top","verdict":"weakness","statement":"Rev limiter is abrupt and buzzes the pegs and bars.","years":[2026],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"strength","statement":"Stock 13/51 gearing with six well-spaced ratios felt about right.","years":[2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Fork dives and the bike sits nose-down","fix":"Lower the rear (race sag 105-108 mm), add fork compression and slow fork rebound","result":"Bike levels out and the front holds up better","support":3}],"disagreements":[{"topic":"Suspension baseline","sides":["Firm but not harsh, or balanced and compliant","Fork too soft for fast riding"]},{"topic":"Race sag","sides":["102 mm as recommended by KYB","105-108 mm to level the bike"]},{"topic":"Map choice in the wet","sides":["Soft map plus traction control","Full-power map, since traction control already limits slip","Soft map too soft low down"]},{"topic":"Clutch feel","sides":["Excellent","Heavy pull"]}]}],"Yamaha|YZ250F":[{"years":[2019,2020,2021,2022,2023],"generation":"2019-2023 reverse-head engine, electric start","summary":"Testers treat this generation as the low-to-mid torque specialist of the 250F class: it pulls almost like a bigger bike out of corners and lets riders carry a higher gear, but it runs out of revs earlier than the European bikes, so it needs more shifting. The KYB spring fork is well liked, though it softens after break-in and dives on corner entry for faster or heavier riders. Off-throttle engine braking pitches the chassis, and most testers load a less-engine-braking or top-end map in the app. Recurring owner complaints are a cramped cockpit for tall riders, seat foam that packs down, a soft front brake and an air filter that does not seal well.","points":[{"aspect":"engine_low","verdict":"strength","statement":"Strong bottom-to-mid torque for a 250F; riders can corner a gear higher than on rival bikes.","years":[2019,2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Runs out of pull and over-rev earlier than the KTM-group and Honda bikes, so riders shift more.","years":[2019,2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"strength","statement":"The KYB spring fork is rated among the best stock forks and handles big whoops well.","years":[2019,2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Once broken in the fork goes soft and dives into flat corners and under braking for faster or heavier riders.","years":[2019,2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"handling","verdict":"strength","statement":"Planted, predictable chassis that tracks straight and turns point-and-shoot; less agile than the KTM but forgiving, with a frame that flexes well.","years":[2019,2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"brakes","verdict":"weakness","statement":"Front brake feels mushy or spongy from the factory.","years":[2019,2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"maintenance","verdict":"weakness","statement":"Air filter does not seal well; dirt collects at the back of the airbox. The 2020 filter grommet helped but did not fully cure it.","years":[2019,2020],"support":2,"strength":"consensus"},{"aspect":"engine_low","verdict":"neutral","statement":"The 2021-2023 engine lost a little bottom-end roll-on compared with 2019-2020 while revving more freely.","years":[2021,2022,2023],"support":1,"strength":"single source"},{"aspect":"power_delivery","verdict":"weakness","statement":"Noticeable engine braking makes the chassis pitch on corner entry at stock settings.","years":[2019,2020,2021,2022,2023],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"weakness","statement":"Stock maps feel abrupt for average riders, and a slight hesitation at the first crack of throttle in slow ruts remained even after remapping on the 2023.","years":[2021,2023],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"strength","statement":"At about 105 mm sag the shock balances riders from roughly 150 to 195 lb with good rear traction.","years":[2020],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"strength","statement":"The 2022 update added low-speed fork damping, giving more hold-up, less pitching and better braking-bump compliance.","years":[2022,2023],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Cockpit is cramped for riders around 5'10 and taller, and seat foam packs down within 10-20 hours.","years":[2019,2020,2021,2022,2023],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"neutral","statement":"Stock muffler packing goes raspy after about 10-20 hours.","years":[2020,2021,2022],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Stock lithium batteries failed on a test bike and left the tester stranded.","years":[2019,2020],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"A few owners reported cam chain failures on 2019-2020 bikes; the sample is small.","years":[2019,2020],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"neutral","statement":"A few owners tied hard starting, stalling and fouled plugs to the idle setting.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"weakness","statement":"Cable clutch heats up under hard use and needs free play adjusted between motos.","years":[2021,2022,2023],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"neutral","statement":"Some bikes have too much throttle free play even with the adjuster fully out.","years":[2019,2020,2021],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Chassis pitches on corner entry from engine braking","fix":"Load a less-engine-braking (free-revving) map in the Power Tuner app","result":"Less decel pitching, lighter mid-corner feel and a little more top end","support":1},{"problem":"Runs out of pull on top","fix":"Tuner or factory map aimed at mid and top end","result":"More pull through 2nd and 3rd and the next gear lands in the power; 13/51 stopped forcing short shifts","support":2},{"problem":"Low-to-mid lacks punch on stock exhaust","fix":"Full aftermarket exhaust system","result":"More low-to-mid pull and smoother pull through the gears; top end about the same","support":2},{"problem":"Throttle response and pull","fix":"Vent the airbox lid (drilled holes or vented cover)","result":"More pull and response; intake noise goes up and the filter gets dirtier faster","support":2},{"problem":"Wants more top end and over-rev","fix":"Ported head or engine kit (factory accessory kit or dual-injector setup)","result":"Stronger top-end surge and over-rev, with slightly less low-end response on one kit","support":2},{"problem":"Fork dives and front washes in flat corners","fix":"Stiffer 4.8 N/mm fork springs or 5 cc more fork oil","result":"More hold-up, less pitching and a calmer front under braking","support":1},{"problem":"Cramped rider triangle","fix":"Lower and rearward footpeg mounts (about 5-7 mm down and 5 mm back)","result":"More room for riders 5'8 to 6'2 without losing ground clearance","support":1},{"problem":"Spongy front brake","fix":"Swap to an older KTM Brembo master cylinder with the stock Yamaha caliper","result":"Firmer, more powerful front brake","support":1}],"disagreements":[{"topic":"Where the stock engine is strongest","sides":["Most tests call it the strongest low-to-mid engine in the class","One exhaust test found stock weaker from idle to about 10,000 rpm and stronger only above that"]},{"topic":"Stock shock","sides":["The shock balances a wide rider weight range with good traction","Another test found the shock wallows and turned rebound in"]}]},{"years":[2024,2025,2026],"generation":"2024-2026 YZ450F-based frame and bigger airbox","summary":"The 2024 update moved the YZ250F to a slimmer frame based on the YZ450F, with a bigger, lower airbox. Testers agree it lost low-end snap: there is a lag off the bottom and riders need clutch, while the mid and top got stronger. Tuners blame the larger airbox. The chassis turns and tips into ruts more easily but felt busier at speed, and the 2024 fork was soft and dived. The 2025 linkage and shock changes calmed it. Alternative app maps such as the factory 'Response' map are the usual way to bring back the bottom end, and the bike is loud.","points":[{"aspect":"engine_low","verdict":"weakness","statement":"Weaker, laggy bottom end compared with 2023; slower riders need clutch to get into the power and it can bog a gear too tall.","years":[2024,2025,2026],"support":4,"strength":"strong consensus"},{"aspect":"mapping","verdict":"strength","statement":"Alternative app maps (the factory 'Response' map, test-rider and tester maps) bring back low-end response; the 2025 standard map already feels like the 2024 'Response' map.","years":[2024,2025,2026],"support":4,"strength":"strong consensus"},{"aspect":"noise","verdict":"weakness","statement":"Loud and raspy when revved, with intake noise from the bigger airbox.","years":[2024,2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"turning","verdict":"strength","statement":"Feels slim and light, turns and tips into ruts very easily, with more frame feedback.","years":[2024,2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"The 2024 fork is soft: it dives in corners and under braking and blows through on big hits, and the bike pitches.","years":[2024],"support":3,"strength":"strong consensus"},{"aspect":"balance","verdict":"strength","statement":"The 2025 linkage and settings cut fork dive and pitching, hold the bike higher in the stroke and give a more planted rear.","years":[2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"strength","statement":"Stronger mid and high-rpm pull with the best over-rev this engine has had; suits fast riders who keep it revved.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"engine_low","verdict":"neutral","statement":"Tuners link the softer low end and heavier engine-braking feel to the larger, lower-velocity airbox.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"power_delivery","verdict":"weakness","statement":"Leaves a gap between 2nd and 3rd gear; needs more shifting and corner speed.","years":[2024],"support":2,"strength":"consensus"},{"aspect":"stability","verdict":"weakness","statement":"The 2024 front end feels busy or twitchy on fast, rough straights, and the chassis is stiffer and less comfortable than before.","years":[2024],"support":2,"strength":"consensus"},{"aspect":"clutch","verdict":"weakness","statement":"Cable clutch heats up and needs free play adjusted during or between motos.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"weight_feel","verdict":"strength","statement":"About 3 lb lighter than the 2023.","years":[2024],"support":2,"strength":"consensus"},{"aspect":"ergonomics","verdict":"neutral","statement":"Cockpit is roomier than 2023 with a flatter seat and lower, rearward pegs, yet riders 5'10 and up still found it cramped.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"mapping","verdict":"neutral","statement":"On the 2025, testers preferred the standard map; the performance map added mid and top but took away too much bottom.","years":[2025],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"weakness","statement":"The 2024 shock wallows.","years":[2024],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"Even on 2024-2026 bikes the fork reacts too quickly when loading the front in corners and the front can wash; the rear sits high for riders under about 160 lb.","years":[2024,2025,2026],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"weakness","statement":"The stock filter let dirt into the intake on a test bike; testers fitted an aftermarket filter and cage.","years":[2024,2025,2026],"support":1,"strength":"single source"},{"aspect":"brakes","verdict":"weakness","statement":"Front brake still feels spongy.","years":[2024,2025,2026],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"neutral","statement":"Owner reports on 2024-2025 bikes show no pattern of engine failures so far.","years":[2024,2025],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"strength","statement":"Stock Yamaha wheels ranked toughest of the OEM wheelsets tested.","years":[2025],"support":1,"strength":"single source"},{"aspect":"engine_top","verdict":"neutral","statement":"On one tuner's dyno the 2025 was 6th of 8 for peak power and lowest for torque, with the latest torque peak; the magazine noted its part-throttle feel on track is better than the numbers suggest.","years":[2025],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Weak low end","fix":"Load the 'Response' preset or a test-rider/tester map","result":"Low end comes back, revs can drop and 3rd works in corners; 'Response' hits a little harder","support":3},{"problem":"Low-end lull and long 2nd-to-3rd gap","fix":"One tooth smaller rear sprocket (50 to 49) to lengthen the gears","result":"Helped the lull but did not fix it","support":2},{"problem":"Fork dives and blows through (2024)","fix":"2-3 clicks more fork compression, raise fork tubes about 2.5 mm, or a stiffer revalve","result":"Less dive and more hold-up; one revalve for intermediate/pro riders removed wallow, though vet testers preferred stock","support":3},{"problem":"Front tips in too quickly","fix":"Slide the fork tubes down a few millimetres in the clamps","result":"Calmer turn-in","support":1},{"problem":"Front twitchy at speed","fix":"Aftermarket clamps at 23 mm offset (stock 22)","result":"Calmer entry on choppy ground and less head shake; 22 mm in the aftermarket clamps gave more front traction","support":1},{"problem":"Low-end response","fix":"Fit a 2023-24 YZ450F airbox with a remapped aftermarket ECU","result":"Better low-end pickup and more pull through 2nd-4th; 3rd usable in corners","support":1},{"problem":"Low-end response","fix":"Vented airbox lid","result":"More low response and mid punch; much louder intake","support":1},{"problem":"Fork too quick in corners, rear high for light riders","fix":"Slower rebound both ends and softer shock high-speed compression for riders under 160 lb","result":"Calmer chassis; rear squats on exits and the fork settles on braking bumps","support":1}],"disagreements":[{"topic":"Top-end strength in class","sides":["Testers found the top end strong and the best over-rev Yamaha has made on this engine","A 2024 shootout found it still could not match the KTM, Husqvarna, Kawasaki or GasGas at high rpm"]},{"topic":"2024 stability","sides":["Some testers found the front busy and twitchy at speed","Another test found it nimble with no stability issues"]},{"topic":"Intake noise","sides":["Several tests call the airbox loud","One launch tester found it quieter than before at lower revs"]}]},{"years":[2027],"generation":"2027 all-new (YZ450F-based)","summary":"Only launch impressions exist so far. One heavier tester found it slightly soft right off the bottom but pulling harder and longer as revs rise, turning in willingly, with stock suspension soft over braking bumps for his weight. Another tester's setting changes were aimed at bigger jump landings.","points":[{"aspect":"engine_low","verdict":"weakness","statement":"A touch soft right off the bottom; an accessory intake and a more aggressive map sharpen it.","years":[2027],"support":1,"strength":"single source"},{"aspect":"engine_top","verdict":"strength","statement":"Pulls harder and longer as revs rise, past where riders expect the limiter.","years":[2027],"support":1,"strength":"single source"},{"aspect":"turning","verdict":"strength","statement":"Turns in willingly and holds lines.","years":[2027],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"Stock suspension felt soft over braking bumps for a heavier rider.","years":[2027],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]}],"Yamaha|YZ450F":[{"years":[2018,2019,2020,2021,2022],"generation":"2018-2022 electric-start generation","summary":"Testers liked this generation's engine on the track: broad, linear power with strong pull, though the first crack of throttle can be abrupt and most testers loaded a smoother preset such as the TP map. From 2020 it felt mellower below about 9,000 rpm with lighter engine braking and a more precise chassis. The 2018-2019 felt twitchy at speed. The KYB suspension was praised for comfort across a wide rider weight range, and the cable clutch for its light pull. Recurring complaints were cramped ergonomics for tall riders, seat foam that packs down, an air filter setup that lets dirt in and slow hot restarts.","points":[{"aspect":"power_delivery","verdict":"weakness","statement":"Smooth and linear overall, but the first crack of throttle is abrupt or jerky, especially on hard-pack.","years":[2020,2021,2022],"support":4,"strength":"strong consensus"},{"aspect":"mapping","verdict":"neutral","statement":"Most testers run a smoother factory preset (the TP map) or a mellower custom map instead of the stock map.","years":[2018,2019,2020,2021,2022],"support":4,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"strength","statement":"KYB suspension is comfortable and resists bottoming across a wide rider weight range; most testers stayed close to stock.","years":[2018,2019,2020,2021,2022],"support":4,"strength":"strong consensus"},{"aspect":"engine_mid","verdict":"neutral","statement":"From 2020 the engine feels mellow below about 9,000 rpm and does its best work above it, with lighter engine braking so it coasts into corners.","years":[2020,2021,2022],"support":3,"strength":"strong consensus"},{"aspect":"engine_low","verdict":"strength","statement":"The 2018-2019 engine had a long usable powerband with strong low end and top end and the best throttle response in its class.","years":[2018,2019],"support":3,"strength":"strong consensus"},{"aspect":"handling","verdict":"strength","statement":"From 2020 the chassis feels more precise, agile and lighter, while still steering mainly from the rear.","years":[2020,2021,2022],"support":3,"strength":"strong consensus"},{"aspect":"ergonomics","verdict":"weakness","statement":"Cramped for tall riders, with bars high and seat low on 2018-2019 and a firm seat that packs down.","years":[2018,2019,2020,2021,2022],"support":3,"strength":"strong consensus"},{"aspect":"engine_mid","verdict":"neutral","statement":"On magazine dynos it often trails rivals from about 6,000 to 8,000 rpm and comes alive late, even when peak power is competitive.","years":[2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"stability","verdict":"weakness","statement":"The 2018-2019 felt twitchy and loose at speed and on corner exit compared with the KTM.","years":[2018,2019],"support":2,"strength":"consensus"},{"aspect":"weight_feel","verdict":"weakness","statement":"Feels heavy or vague landing into a lean compared with the KTM and Husqvarna; magazine scales put it 15-17 lb heavier than the KTM.","years":[2018,2019,2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"clutch","verdict":"strength","statement":"The cable clutch was rated the best non-hydraulic clutch in the class with an easy pull.","years":[2018,2019,2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"brakes","verdict":"neutral","statement":"The 2018-2019 brakes had weak initial bite and then grabbed; the 2020 Nissin front is much stronger and touchier.","years":[2018,2019,2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"maintenance","verdict":"weakness","statement":"Air filter setup lets dirt in: the flat filter dries on the backfire screen, and without the screen dirt can drop into the boot during filter changes.","years":[2018,2019,2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"reliability","verdict":"weakness","statement":"Slow hot restarts after a stall and quick overheating at idle.","years":[2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"maintenance","verdict":"weakness","statement":"The wrap-around exhaust is hard to remove and intake noise is loud.","years":[2018,2019,2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"strength","statement":"Won a 2020 450 bracket shootout and was ranked first or second by every tester in another.","years":[2020],"support":2,"strength":"consensus"},{"aspect":"power_delivery","verdict":"weakness","statement":"Spools up fast and spins or wheelies out of hard-pack corners; mapping alone did not fix it.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"Once broken in, the fork dives off throttle and is slightly soft on big bumps at speed.","years":[2020,2021,2022],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"weakness","statement":"The 2020 shock squats and sits low under throttle, with a harsh mid-stroke.","years":[2020],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"strength","statement":"One test bike went 100 hours with basic maintenance.","years":[2021],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Abrupt low-end hit","fix":"Run the smoother TP 3.0 preset or another softer factory map","result":"Linear, easy roll-on that pulls longer; also good for starts","support":3},{"problem":"Abrupt low end for experienced riders","fix":"Ride one gear higher on the stock map","result":"Softens the hit and engine braking and avoids stalling","support":2},{"problem":"Wheelspin on hard-pack exits","fix":"Heavier steel clutch basket","result":"Calmer exits and less wheelspin, with slightly more engine braking","support":1},{"problem":"Rear squats under throttle","fix":"Longer aftermarket link arm plus softer high-speed compression","result":"Flatter decel, better exit traction; firmer if ridden lazily","support":1},{"problem":"Fork dives and shock squats","fix":"Revalve on stock springs","result":"More fork hold-up without deflection, firmer shock that squats less","support":1},{"problem":"Cramped for tall riders","fix":"Taller seat and lower/rearward footpegs","result":"Better attack position and easier sit-to-stand","support":2},{"problem":"Air intake","fix":"Domed filter kit and raised airbox lid, optionally with a tuner map","result":"About 2 hp more at peak and more over-rev on one magazine dyno","support":1},{"problem":"Chassis unsettled on acceleration and braking","fix":"Change gearing from 13/49 to 14/53","result":"Chassis settles and 3rd stays usable","support":1}],"disagreements":[{"topic":"Engine strength vs rivals","sides":["A tester's head-to-head found it ahead of the KX450 at low, mid and top","Magazine dynos put it near the bottom of the class from 6,000 to 8,000 rpm"]},{"topic":"Best map choice","sides":["Most testers preferred the TP preset or a mellower map","One magazine preferred the new 2020 stock map on loose, good-traction tracks"]},{"topic":"Aftermarket exhaust","sides":["One test found both aftermarket systems lost some over-rev against a very good stock system","Other tests found full systems smoothed roll-on and added mid and top"]}]},{"years":[2023,2024,2025],"generation":"2023-2025 all-new engine and frame","summary":"Testers rate this engine among the strongest in the class, but the first crack of throttle is very sharp: it wheelies and breaks traction, and most testers detune it with a richer low-rpm map, a flywheel weight or a smoother exhaust. The 2023-2024 chassis turns sharper than any earlier YZ450F but gives up straight-line stability, with head shake and oversteer. The 2025 linkage and mount changes calmed it for most testers. Recurring complaints are a cable clutch that fades, a thin hard seat, dirt getting past the filter cage and a loud intake.","points":[{"aspect":"power_delivery","verdict":"weakness","statement":"Very sharp first crack of throttle: it pops out of ruts, wheelies and breaks traction; most riders need it detuned.","years":[2023,2024,2025],"support":5,"strength":"strong consensus"},{"aspect":"mapping","verdict":"neutral","statement":"Testers detune it with a richer low-rpm or smoother map; a fully softened map still revs past 11,000 rpm.","years":[2023,2024,2025],"support":4,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"strength","statement":"Very strong, linear pull through the mid and top with a long over-rev; among the most powerful engines in the class.","years":[2023,2024,2025],"support":3,"strength":"strong consensus"},{"aspect":"stability","verdict":"weakness","statement":"Less stable at speed: aggressive turn-in, front-end oversteer and head shake, plus harshness at the edge of the tire.","years":[2023,2024,2025],"support":3,"strength":"strong consensus"},{"aspect":"ergonomics","verdict":"weakness","statement":"Seat is thin, domed and stiff, breaks down within about 8-10 hours, and the side panel catches boots.","years":[2023,2024,2025],"support":3,"strength":"strong consensus"},{"aspect":"turning","verdict":"strength","statement":"The sharpest-turning YZ450F yet, feeling lighter and more agile than 2022.","years":[2023,2024],"support":2,"strength":"consensus"},{"aspect":"balance","verdict":"strength","statement":"The 2025 linkage, mounts and springs make it more planted and less twitchy, with less pitching.","years":[2025],"support":2,"strength":"consensus"},{"aspect":"suspension_rear","verdict":"weakness","statement":"Shock is stiff on high-speed compression relative to a softer fork; on 2023 it also sat low on big hits.","years":[2023,2024],"support":2,"strength":"consensus"},{"aspect":"clutch","verdict":"weakness","statement":"The disc-spring cable clutch fades or slips under hard use and its spring is too soft; plates last 10-12 hours for a rider who covers the clutch.","years":[2023,2024,2025],"support":2,"strength":"consensus"},{"aspect":"ergonomics","verdict":"weakness","statement":"On 2023-2024 the map button sits where the kill button gets pressed, and the throttle position causes thumb blisters.","years":[2023,2024],"support":2,"strength":"consensus"},{"aspect":"maintenance","verdict":"weakness","statement":"Dirt can get past the filter cage at the front edge, and pulling the filter lets dirt drop into the intake.","years":[2023,2024,2025],"support":2,"strength":"consensus"},{"aspect":"noise","verdict":"weakness","statement":"Loud intake roar from the front airbox.","years":[2023,2024,2025],"support":2,"strength":"consensus"},{"aspect":"weight_feel","verdict":"strength","statement":"About 5 lb lighter than the 2022 on magazine scales.","years":[2023,2024,2025],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"The softer 2025 fork springs suit vets and novices, but fast testers found the front too soft.","years":[2025],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"The 2023 front end is light in shallow ruts and pushes when setting up wide.","years":[2023],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Even with the lower, rearward pegs the cockpit is cramped for riders 5'10 and up.","years":[2023,2024,2025],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"weakness","statement":"2nd and 3rd gear are poorly spaced for some riders.","years":[2025],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Several consumer 2025 bikes broke connecting rods.","years":[2025],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"strength","statement":"Stock Yamaha wheels ranked toughest of the OEM wheelsets tested.","years":[2025],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Abrupt low end","fix":"Richer map below about 5,000 rpm, often with a 48-tooth rear sprocket","result":"Calmer exits; taller 2nd pulls longer before 3rd","support":1},{"problem":"Spools fast, wheelies and spins","fix":"Flywheel weight (about 80 g)","result":"Calmer power build, more traction and better lugging without extra engine braking","support":1},{"problem":"Harsh initial hit","fix":"Aftermarket slip-on or full exhaust","result":"Smoother, more linear low end and better rear traction, revving out about as far as stock","support":3},{"problem":"Head shake and oversteer at speed","fix":"Slide forks down in the clamps, snug the steering stem slightly, or fit 23 mm offset clamps","result":"Calmer steering and straighter tracking","support":1},{"problem":"Unstable on braking bumps","fix":"Aftermarket engine mounts","result":"Calmer over braking bumps and more front feel on throttle, slightly heavier turn-in","support":1},{"problem":"Clutch fade","fix":"Factory-accessory hydraulic clutch kit or an aftermarket basket and spring kit","result":"Lighter pull, more consistent engagement and starts","support":2},{"problem":"Rear squat and empty feel under load","fix":"Aftermarket linkage with sag reset to 104-105 mm","result":"Better rear traction and comfort","support":1},{"problem":"Air intake","fix":"Domed filter kit plus a vented airbox cover","result":"Over 2 hp gained and quicker revving; much louder","support":1}],"disagreements":[{"topic":"2025 stability","sides":["One review found the 2025 more planted and less twitchy at speed","A race test still found head shake at speed and tuck on entry until clamps and fork height were changed"]},{"topic":"Factory smooth map","sides":["One magazine's testers mostly chose the factory Smooth Linear map and kept it","Another found it did not tame the low end enough and built a richer custom map"]},{"topic":"Gearing direction","sides":["One magazine went to a 48-tooth rear to soften exits","A tester went to 13/50 on deep East Coast dirt to recover 2nd and reach 3rd sooner"]}]},{"years":[2026],"generation":"2026 update (intake, flywheel, hydraulic clutch, frame stiffness)","summary":"Testers found the 2026 smoother, quieter and easier to ride than 2025, but it gives up some low-rpm snap and peak power and ranked mid-pack or lower on shootout dynos. Several shootouts still rated it highly because the chassis is more stable and balanced than 2023-2025 while turning precisely, although it carves deep ruts and flat turns less well than the best rivals. The fork is the main setup issue: testers found it harsh in the mid-stroke but disagreed on why. The 51-tooth stock rear sprocket makes 2nd gear very short.","points":[{"aspect":"engine_low","verdict":"weakness","statement":"Feels more plugged up or choked down low than 2025 and gives up some peak and quick revving.","years":[2026],"support":4,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Fork feels harsh or stiff in the mid-stroke and can overpower the shock, hurting front traction.","years":[2026],"support":4,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"neutral","statement":"Ranked mid-pack or lower on shootout dynos (about 54-57 hp), roughly 3 hp below the 2025 on one magazine's dyno.","years":[2026],"support":3,"strength":"strong consensus"},{"aspect":"stability","verdict":"strength","statement":"More stable and balanced than 2023-2025 while still turning precisely.","years":[2026],"support":3,"strength":"strong consensus"},{"aspect":"gearing","verdict":"weakness","statement":"The stock 51-tooth rear sprocket makes 2nd gear very short and 3rd can struggle in some corners.","years":[2026],"support":3,"strength":"strong consensus"},{"aspect":"power_delivery","verdict":"strength","statement":"Smoother and easier to ride, with a more linear low-mid and a broader peak.","years":[2026],"support":2,"strength":"consensus"},{"aspect":"turning","verdict":"weakness","statement":"Slides through flat turns more than it carves; weaker in deep ruts and flat-turn traction than the best rivals.","years":[2026],"support":2,"strength":"consensus"},{"aspect":"ergonomics","verdict":"weakness","statement":"Round seat, tall feel and side panels that catch boots.","years":[2026],"support":2,"strength":"consensus"},{"aspect":"vibration","verdict":"strength","statement":"Little to no vibration; least in one 2026 shootout.","years":[2026],"support":2,"strength":"consensus"},{"aspect":"power_delivery","verdict":"weakness","statement":"More engine braking than 2024-2025 makes it harder to roll corners and upsets the chassis on entry.","years":[2026],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"strength","statement":"Shock is much better than the 2025.","years":[2026],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"strength","statement":"The new hydraulic clutch is lighter and needs no mid-moto adjustment.","years":[2026],"support":1,"strength":"single source"},{"aspect":"noise","verdict":"strength","statement":"Noticeably quieter than 2023-2025.","years":[2026],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Exposed stator wire and clutch line, and a low-pressure radiator cap.","years":[2026],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"neutral","statement":"Owners around 230 lb say it needs heavier springs.","years":[2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"2nd gear too short","fix":"Go from 13/51 to 13/50","result":"Usable 2nd for vet riders and 3rd comes in easier; fast riders kept 51","support":2},{"problem":"Engine feels choked","fix":"Fit a 2025-style accessory airbox or raised intake cover with a freer aftermarket or 2025 exhaust","result":"Stronger, more responsive feel with clearer bottom-end gain","support":2},{"problem":"Engine braking upsets corner entry","fix":"App map that relaxes the engine on deceleration","result":"Better corner-entry balance","support":1},{"problem":"Low end lacks excitement","fix":"Optional test-rider or tester maps","result":"More low-end excitement or exit connection","support":1}],"disagreements":[{"topic":"Why the fork feels harsh","sides":["One shootout found it stiff early and overpowering the shock; the fix was raising the fork 2-5 mm and softening compression","A race test found it was actually too soft and riding low where damping ramps up; more shock sag plus 2 clicks stiffer fork compression made it plusher"]},{"topic":"Turning","sides":["One magazine said the new frame turns with less effort","Another shootout found it weaker carving flat turns and ruts"]}]},{"years":[2027],"generation":"2027 update","summary":"Only one day-one magazine test so far. On paper the 2027 fork is softer, but testers found it rode higher in the stroke and harsher than the 2026, and they softened fork compression.","points":[{"aspect":"suspension_front","verdict":"weakness","statement":"Fork rides higher in the stroke and feels harsher than 2026 despite softer specs; testers went 2 clicks softer on compression, and slower riders raised the forks 5 mm.","years":[2027],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]}],"Yamaha|YZ450FX":[{"years":[2019,2020],"generation":"2019-2020","summary":"One outlet tested this generation. Testers found it strong and smooth off the bottom, hard to stall and free-revving, with a plush, stable chassis. On the 2019 the clutch lost bite on sudden release.","points":[{"aspect":"engine_low","verdict":"strength","statement":"Strong, smooth bottom end that is hard to stall, then lively and free-revving through the mid and top.","years":[2019,2020],"support":1,"strength":"single source"},{"aspect":"handling","verdict":"strength","statement":"Plush and stable chassis.","years":[2019,2020],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"weakness","statement":"Clutch lost bite on sudden release on the 2019 test bike.","years":[2019],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Sprint enduro setup","fix":"A little less fork compression, a little more shock high-speed compression, rear ride height kept up, one tooth smaller rear sprocket for tight going","result":"Better balance in tight terrain","support":1}],"disagreements":[]},{"years":[2021,2022,2023],"generation":"2021-2023","summary":"Testers found this FX smooth and torquey down low, able to lug deep without much clutch and stall less than rivals, though the stock map 1 felt too aggressive and jerky off the bottom. The chassis felt more agile than the 2019-2020 but steered heavier in tight trees. Stock suspension suits slow technical terrain but is too soft for fast GP and desert racing.","points":[{"aspect":"mapping","verdict":"weakness","statement":"Stock map 1 feels too aggressive and jerky off the bottom; testers prefer softer maps for tight terrain.","years":[2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Stock suspension is too soft for high-speed GP or desert racing and rides low; it works well in slow technical terrain.","years":[2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"engine_low","verdict":"strength","statement":"Smooth low-end torque that lugs deep with little clutch; stalls less than rivals.","years":[2021,2022,2023],"support":1,"strength":"single source"},{"aspect":"handling","verdict":"neutral","statement":"More agile and precise than 2019-2020 but with longer, heavier steering in tight trees.","years":[2021,2022,2023],"support":1,"strength":"single source"},{"aspect":"engine_mid","verdict":"neutral","statement":"About 53 hp on one magazine's dyno.","years":[2021,2022,2023],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Too soft for desert and GP","fix":"Stiffer fork and shock springs with minor valving changes, and 14/52 gearing","result":"Better bump absorption and bottoming resistance; chassis settles on acceleration and 2nd is usable in corners","support":1},{"problem":"Abrupt in tight terrain","fix":"Softer tester-made map","result":"Can lug with little clutch","support":2}],"disagreements":[]},{"years":[2024,2025,2026],"generation":"2024-2026 (based on the 2023 YZ450F)","summary":"Testers agree the FX is quick and strong through the mid and top, but they disagree on the low end: one magazine called it detuned and manageable, while another found the low-rpm response crisp enough to be unsettling and tuned the maps down. First gear is so low it is rarely used. The most common chassis complaint is a lack of stability at speed, with slight head shake in chop. Opinions on the KYB suspension range from plush and predictable to stiff and race-oriented.","points":[{"aspect":"stability","verdict":"weakness","statement":"Wants more stability at speed; slight head shake over high-speed chop.","years":[2024,2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"gearing","verdict":"neutral","statement":"First gear is extremely low and rarely used; 2nd works in tight woods and 3rd is the key gear.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"handling","verdict":"neutral","statement":"Feels much lighter and more precise than earlier FX models, with a little front squirm under hard braking and less bump compliance.","years":[2024,2025,2026],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"strength","statement":"KYB spring fork rated the most predictable of the off-road 450s: plush and never blows through.","years":[2024],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"A 200 lb tester found the fork soft and sometimes harsh and slowed rebound; stock springs are slightly light for that weight.","years":[2024],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Seat shape, harsh grips and hard-to-grip sides; no stock handguards.","years":[2024,2025,2026],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"neutral","statement":"Cable clutch survived a 10-hour race, but testers preferred the accessory hydraulic kit.","years":[2024],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"neutral","statement":"In tight or muddy terrain testers run the mellow map with the app power slider turned down and traction control on; fast riders keep the stock map.","years":[2024,2025,2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Head shake in high-speed chop","fix":"Two clicks more fork compression, 23.5 mm offset clamps, or a more stretched-out setup for fast races","result":"Head shake gone, more stability and plant; one setup turned worse when seated","support":3},{"problem":"Fast GP and desert","fix":"Fork 5 mm up (stock 8) with more compression, 100 mm sag, 14/52 or 14/53 gearing","result":"More stability at speed","support":1},{"problem":"Throttle jolts and stalling in tight terrain","fix":"Factory-accessory 50 g flywheel weight","result":"Smoother off idle and less stall risk; revs build slower, so 3rd is harder to pull for fast riders","support":1},{"problem":"Rocky GP flats","fix":"Foam mousse inserts","result":"No flats in rocky races","support":1}],"disagreements":[{"topic":"Low-end character","sides":["One race test called it detuned, quick-revving and manageable","Another found crisp, sometimes unsettling low-rpm response, and the 2026 stock map felt aggressive"]},{"topic":"Suspension feel","sides":["Rated plush and the most predictable of the off-road 450s","Found stiff and race-oriented on the 2026, or soft for a 200 lb rider"]}]}],"Yamaha|YZ250FX":[{"years":[2020,2021],"generation":"2020-2021","summary":"Testers liked the FX's strong bottom end and wide-ratio gearbox, which lets riders stay in one gear on most trails, with top-end pull close to the best 250Fs. The stock suspension suits East Coast roots and rocks but is too soft for fast GP, desert or motocross. Starting was a weak point, especially in gear or on hot restarts.","points":[{"aspect":"suspension_front","verdict":"weakness","statement":"Stock suspension is too soft and wallowy for fast GP, desert, motocross or aggressive riders.","years":[2020,2021],"support":3,"strength":"strong consensus"},{"aspect":"engine_low","verdict":"strength","statement":"Strong bottom end that lugs well; the wide-ratio box lets most trail be ridden in one gear.","years":[2020,2021],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"strength","statement":"GNCC-style valving rolls over rocks and roots and suits East Coast woods.","years":[2020,2021],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"weakness","statement":"Hard to start in gear and on hot restarts.","years":[2020,2021],"support":2,"strength":"consensus"},{"aspect":"engine_top","verdict":"strength","statement":"No mid-to-top drop-off, and top-end pull close to the hardest-pulling 250F, though it is not the quickest-revving.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"weakness","statement":"On MX or GP tracks riders hunt between 2nd-3rd and 3rd-4th.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"neutral","statement":"A long-term desert bike needed throttle cables and wheel bearings around 60 hours, clutch plates at 75 and a top end with timing chain around 80; its crank later failed after engine mods and long stretches on the rev limiter.","years":[2020],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Too soft for fast racing","fix":"Stiffer springs, revalve and fork oil raised (295 cc to about 320-365 cc)","result":"More hold-up for braking and turns, smoother bottoming, less see-saw while keeping comfort","support":1},{"problem":"Gaps between gears on MX or GP","fix":"Add 1-2 teeth to the rear sprocket","result":"Less hunting between gears","support":1},{"problem":"Hard starting in gear","fix":"Start in neutral, or crack the throttle while pressing the starter","result":"Starts reliably","support":1}],"disagreements":[]},{"years":[2022,2023,2024],"generation":"2022-2024 engine update","summary":"Mainly one outlet's first impression. Testers found strong low-end torque that lugs and recovers from too tall a gear, a strong midrange and a top end competitive with the highest-revving 250Fs. The stock fork felt firm early and rode high while the shock felt soft, so the bike was unbalanced until the clickers were reset.","points":[{"aspect":"engine_low","verdict":"strength","statement":"Exceptional low-end torque for a 250F that lugs and recovers from too tall a gear, with a strong mid and a competitive top end.","years":[2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"balance","verdict":"weakness","statement":"Fork feels firm early and rides high while the shock is soft, leaving the bike unbalanced at stock settings.","years":[2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"engine_top","verdict":"neutral","statement":"About 38 hp on one magazine's rear-wheel dyno, essentially the same as 2021.","years":[2022,2023,2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Front-to-rear imbalance","fix":"Soften the fork clickers and add shock high-speed compression","result":"Balanced and raceable close to stock","support":1}],"disagreements":[]},{"years":[2025,2026],"generation":"2025-2026 (based on the 2024 YZ250F)","summary":"Testers found a longer, more linear powerband with a strong bottom-end hit, and suspension that stays plush over roots and rocks while resisting bottoming. Two separate tests reported the bike hard to start in gear even when warm.","points":[{"aspect":"other","verdict":"weakness","statement":"Hard to start in gear even when warm; riders restart in neutral.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"strength","statement":"Plush over rocks, roots and whoops yet resists bottoming at stock settings.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"power_delivery","verdict":"strength","statement":"Longer, more linear powerband with a strong bottom-end hit.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"neutral","statement":"One tester sometimes wanted a lower 1st and taller 6th.","years":[2025,2026],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]}],"Yamaha|YZ125":[{"years":[2020,2021],"generation":"2020-2021 (Mikuni carb engine)","summary":"Magazine tests found the older YZ125 pulled harder than the KTM 125 below about 8,000 rpm and was easy to keep on the pipe, but fell well behind it on top. Suspension is set up for light riders.","points":[{"aspect":"engine_low","verdict":"strength","statement":"Pulls harder than the KTM 125 below about 8,000 rpm and is easy to keep on the pipe.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"engine_top","verdict":"weakness","statement":"Clearly slower than the KTM 125 above about 8,000 rpm, roughly 3-4 hp down at peak.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"Set up for light riders; fast or heavy riders need stiffer springs.","years":[2020],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"weakness","statement":"Stock gearing is slightly tall for a lugging style.","years":[2020],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Gearing slightly tall","fix":"13/49 sprocket","result":"More 2nd-gear grunt and earlier 3rd","support":1},{"problem":"Wants more power","fix":"Aftermarket pipe (about 2 hp); porting with raised compression and race gas for more","result":"Pipe choice moves power toward the top or toward the low-mid","support":2}],"disagreements":[]},{"years":[2022,2023,2024,2025,2026,2027],"generation":"2022-on new engine (Keihin carb, power jet)","summary":"The 2022 engine traded bottom end for more mid-to-top: testers found it weaker off the bottom and slower to come on the pipe, so riders slip the clutch out of turns, though pros liked it. On dynos it trails the European 125s. Many owners report rich jetting down low, with plug fouling and bogging, and lean it out. The suspension suits roughly 150-175 lb riders; heavier or faster riders find it soft.","points":[{"aspect":"engine_low","verdict":"weakness","statement":"Weaker off the bottom and slower to come on the pipe than the 2021; riders slip the clutch out of turns and beginners struggle.","years":[2022,2023,2024,2025,2026,2027],"support":3,"strength":"strong consensus"},{"aspect":"jetting","verdict":"weakness","statement":"Stock jetting runs rich low-to-mid: plug fouling on trails, burbling on coast-down and bogs off jump faces.","years":[2022,2023,2024,2025,2026,2027],"support":3,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Makes the least peak power of the current 125s on magazine dynos.","years":[2022,2023,2024,2025,2026,2027],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"neutral","statement":"Suspension suits roughly 150-175 lb riders; heavier or faster riders find it soft, even after the 2025 spring and valving change.","years":[2022,2023,2024,2025,2026,2027],"support":2,"strength":"consensus"},{"aspect":"engine_mid","verdict":"strength","statement":"Stronger from about 7,500 rpm to peak than the old engine; pros liked it.","years":[2022,2023,2024,2025,2026,2027],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"The 2022 springs and valving are too stiff for riders around 155 lb and for novice or vet riders.","years":[2022],"support":1,"strength":"single source"},{"aspect":"tires","verdict":"weakness","statement":"Stock front tire lost grip after 6-8 hours.","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Rich low end, fouling and bog","fix":"Leaner pilot jet and a different needle (Y4 or CCL family), air screw about 1.25-1.75 turns, power jet adjusted","result":"Cleaner low end with no bog for most owners; no single fix works for everyone","support":3},{"problem":"Can't pull 3rd in deep soil or hills","fix":"13/50 rear sprocket","result":"3rd gear usable","support":1},{"problem":"More top end","fix":"Aftermarket pipe and silencer","result":"No change below about 9,500 rpm, then faster build and more over-rev (about 1.4 hp on one dyno)","support":2},{"problem":"Soft low end","fix":"Bolt-on package: pipe, ported cylinder and head, race piston, programmable ignition, reeds","result":"Soft low end gone and strong pull into the over-rev on race fuel","support":1}],"disagreements":[{"topic":"Midrange on track vs dyno","sides":["Dynos put it last among the current 125s","One magazine's riders still rated it strongest in the midrange, crediting its low flywheel effect"]}]}],"Yamaha|YZ250":[{"years":[2020,2021],"generation":"2020-2021 (pre-2022 bodywork)","summary":"The YZ250 engine has been largely unchanged since 2006. A magazine found it makes its best power higher in the revs and does not like being lugged, so riders need the clutch out of corners. The KTM 250 SX was stronger low-mid, but the Yamaha was easier to ride and kept pulling past its peak. Owners often find stock jetting rich down low.","points":[{"aspect":"engine_low","verdict":"weakness","statement":"Doesn't like being lugged and needs clutch out of corners; the KTM 250 SX is about 4 hp stronger around 7,000 rpm.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"engine_top","verdict":"strength","statement":"Keeps pulling past its peak and is easier to ride than the KTM.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"jetting","verdict":"weakness","statement":"Stock pilot runs rich at the bottom near sea level.","years":[2021],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Rich low end","fix":"Leaner pilot (about 45-48) and smaller power jet, needle clip adjusted","result":"Cleaner low end; one trail rider stopped fouling plugs","support":2},{"problem":"Off-idle dip","fix":"Re-time the power-valve governor by changing thrust washers so the valve opens earlier","result":"Fills the dip; needs a leaner power jet","support":1},{"problem":"More power","fix":"Aftermarket pipe","result":"About 2.5 hp more, mostly mid and up; too strong a hit for some vets on hard-pack","support":1}],"disagreements":[]},{"years":[2022,2023,2024,2025,2026,2027],"generation":"2022-on bodywork, airbox and suspension update","summary":"Testers describe a clean bottom and a hard-hitting midrange that needs a careful throttle into turns, pulling steadily to about 8,800 rpm. Lighter, slower and older riders found the stiffer 2022-on suspension harsh, while heavier riders found the stock springs light. The fork dives and pitches after break-in. Owners commonly lean out the jetting and tighten the head's squish.","points":[{"aspect":"suspension_front","verdict":"weakness","statement":"Stock springs are light for riders over about 155-170 lb.","years":[2022,2023,2024,2025,2026,2027],"support":3,"strength":"strong consensus"},{"aspect":"power_delivery","verdict":"neutral","statement":"Clean off idle with a hard-hitting midrange that needs careful throttle into turns; easy to keep in the meat, while the KTM is stronger low-mid but signs off sooner.","years":[2022,2023,2024,2025,2026,2027],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"The stiffer 2022-on valving feels harsh for vets, novices and light riders.","years":[2022,2023,2024,2025,2026,2027],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"After break-in the fork dives under hard braking and pitches the bike forward.","years":[2022,2023],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"strength","statement":"The KYB setup has enough hold-up yet absorbs small bumps and feels balanced for an average rider.","years":[2024],"support":1,"strength":"single source"},{"aspect":"weight_feel","verdict":"strength","statement":"About 217 lb without fuel, roughly 10 lb lighter than a YZ250F.","years":[2022,2023,2024,2025,2026,2027],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"weakness","statement":"The rear-facing airbox scoops let water in when washing, and the 22 mm swingarm axle limits wheel swaps.","years":[2022,2023,2024,2025,2026,2027],"support":1,"strength":"single source"},{"aspect":"jetting","verdict":"weakness","statement":"Owners often find stock jetting rich, even at the magazine's recommended settings.","years":[2025],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Springs too light for heavier riders","fix":"Stiffer springs (about 4.6 N/mm fork, 52 N/mm shock) or a respring with revalve","result":"One revalve fixed a fast-moving, knifing front and harsh mid-stroke while staying plush","support":2},{"problem":"Fork dives and pitches after break-in","fix":"Close up fork compression and rebound","result":"More hold-up","support":1},{"problem":"Rich jetting","fix":"Leaner pilot, smaller power jet and needle clip changes","result":"Cleaner running; adjust for season","support":2},{"problem":"Too much hit","fix":"Longer silencer, milder head insert, a few degrees of ignition retard, earlier power-valve spring or a flywheel weight","result":"More linear delivery; power-valve damper results were mixed","support":1},{"problem":"Large stock squish band","fix":"Mill the head to tighten squish to about 0.045 in on pump fuel","result":"Sharper running; head dowel bores may need deepening","support":1},{"problem":"Aftermarket pipe running rich","fix":"Raise needle one clip and drop the main one size","result":"Correct jetting with the pipe","support":1}],"disagreements":[{"topic":"How aggressive the power is","sides":["A magazine found it hits harder than the KTM in the midrange","Another tester found it smooth and manageable rather than abrupt"]}]}],"Yamaha|YZ125X":[{"years":[2020,2021,2022],"generation":"2020-2022 first generation (Mikuni)","summary":"Testers found the X much more tractable than the YZ125, smooth and torquey down low for a 125, which helps in tight woods. The top end is slower-revving and down on the European 125s. The soft cross-country suspension is plush on small hits but bottoms on big motocross impacts for heavier or faster riders. The small tank and lack of skid plate and handguards were the main practical complaints.","points":[{"aspect":"engine_low","verdict":"strength","statement":"Smooth, controllable bottom end that lugs well for a 125; easier to recover from too tall a gear.","years":[2020,2021,2022],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Soft cross-country settings bottom on big MX-style hits for heavier or faster riders; one tester called it badly undersprung at 190 lb.","years":[2020,2021,2022],"support":3,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Slower-revving and signs off early on top; clearly down on the Husqvarna TC125.","years":[2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"weakness","statement":"Small tank gives roughly 40 minutes of hard riding.","years":[2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"weakness","statement":"No skid plate or handguards; motocross tires work poorly off-road and vice versa.","years":[2020,2021,2022],"support":1,"strength":"single source"},{"aspect":"brakes","verdict":"weakness","statement":"Front brake is only average.","years":[2021],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"strength","statement":"45 hours of riding with only routine maintenance; the cable clutch held up.","years":[2021],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Front vague in chop and tight turns","fix":"Reduce race sag from about 110 mm to 107 mm","result":"More front traction in tight turns","support":1},{"problem":"Soft for MX use","fix":"Stiffer clickers and 10 cc more fork oil, or respring and revalve","result":"Better hold-up; heavier riders still need springs","support":2},{"problem":"Weak front brake","fix":"Oversize rotor and braided line","result":"Stronger front brake","support":1}],"disagreements":[]},{"years":[2023,2024,2025,2026,2027],"generation":"2023-on (Keihin engine)","summary":"Testers found the second-generation X surprisingly torquey for a 125. It has much more low end than the 2022-on YZ125 and less engine braking, but a weaker top end. The soft suspension soaks up rocks and roots, while heavier or faster riders may want it stiffer. There is still no electric start and the tank is small.","points":[{"aspect":"engine_low","verdict":"strength","statement":"Surprisingly torquey; it can lug a taller gear and has much more low end than the motocross YZ125.","years":[2023,2024,2025,2026,2027],"support":2,"strength":"consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Weaker top end; slower than the YZ125.","years":[2023,2024,2025,2026,2027],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"strength","statement":"Softer KYB settings absorb repeated rock, root and braking-bump hits; heavier or faster riders may want it stiffer.","years":[2023,2024,2025,2026,2027],"support":1,"strength":"single source"},{"aspect":"other","verdict":"weakness","statement":"No electric start and a small 1.8 gal tank that limits range.","years":[2023,2024,2025,2026,2027],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Jetting for racing","fix":"Leaner pilot with a different needle and slide cutaway","result":"Cleaner running at race pace","support":1}],"disagreements":[]}],"Yamaha|YZ250X":[{"years":[2020,2021,2022],"generation":"2020-2022","summary":"Mainly one magazine's race test plus owner reports. The X is milder and more tractable than the YZ250, with a perky low-to-mid that suits rocky, tight terrain, but it does not make more power than the YZ250 anywhere. On a motocross track the tall 4th and 5th gears leave gaps, and the soft suspension bottoms on big jumps. Owners note it often finds neutral on 2-to-1 downshifts.","points":[{"aspect":"other","verdict":"weakness","statement":"Small tank and short reserve, no handguards or skid plate, kick start only.","years":[2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"power_delivery","verdict":"strength","statement":"Milder and more tractable than the YZ250 with a perky low-to-mid for rocky, tight terrain; it never out-powers the YZ250.","years":[2020,2021,2022],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"weakness","statement":"Tall 4th and 5th leave big gaps on a motocross track.","years":[2020,2021,2022],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"Soft suspension rides low and bottoms on big jumps for fast riders.","years":[2020,2021,2022],"support":1,"strength":"single source"},{"aspect":"other","verdict":"weakness","statement":"Downshifting from 2nd to 1st on the move often finds neutral.","years":[2021],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"weakness","statement":"Testers liked stiffer clutch springs better than the softer stock ones.","years":[2020,2021,2022],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Stalling and hard hits in tight terrain","fix":"Heavier flywheel, auto-clutch, revalve and respring, 13/51 gearing","result":"Easier trail manners; owners call the carb simple once set up","support":1}],"disagreements":[]},{"years":[2023,2024,2025,2026,2027],"generation":"2023-on","summary":"One outlet's test. The newer intake reduced the on/off feel at the bottom and mid while keeping the two-stroke rush on top. The soft suspension worked in the woods and on an MX track without bottoming.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Smooth, strong low end with less on/off feel, but still revs out like a 250 two-stroke.","years":[2023,2024,2025,2026,2027],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"strength","statement":"Softer than the YZ250 and absorbs roots and acceleration bumps without bottoming; go stiffer for fast western terrain.","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]}],"Yamaha|WR250F":[{"years":[2020,2021],"generation":"2020-2021","summary":"Little tester feedback exists for these years. The US bike ships restricted, and owners uncork it. Tall stock gearing made 2nd hard to hold in slow corners on one test bike.","points":[{"aspect":"engine_mid","verdict":"neutral","statement":"About 3 hp less than the YZ250F on the same magazine dyno in US form.","years":[2021],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Restricted US engine","fix":"Remove throttle stop, muffler restrictor and intake restrictor; pair with the competition ECU and a little more fuel if the tailpipe comes out","result":"Engine runs closer to YZ-FX output","support":1},{"problem":"2nd gear runs out in slow corners","fix":"13/48 instead of 13/50 plus a slip-on and header","result":"Holds 2nd through slow corners; sharper response but less grip in slick going","support":1}],"disagreements":[]},{"years":[2022,2023,2024],"generation":"2022-2024 (YZ250F-derived frame)","summary":"One European test. Testers found the 2022 stronger across the range, especially mid to top where it revs freely. Stalling and slow hot restarts were still a trait. The small oil capacity calls for frequent oil changes.","points":[{"aspect":"engine_top","verdict":"strength","statement":"Stronger across the range, especially mid to top, revving freely so gears can be held longer.","years":[2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"other","verdict":"weakness","statement":"Still stalls more readily than a two-stroke in technical going, and hot restarts are awkward; a softer map reduces stalling.","years":[2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"neutral","statement":"Small engine oil capacity, so testers advise frequent changes.","years":[2022,2023,2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Restricted US engine","fix":"Remove throttle stop and restrictors and fit the competition ECU","result":"Stronger running; the ECU alone did not change off-idle response","support":1}],"disagreements":[]},{"years":[2025,2026,2027],"generation":"2025-on","summary":"Testers found the 2025 lively, with a bigger midrange kick and a smooth climb to a high rev limit. The softer handlebar map tames it. The KYB suspension splits opinion: firm and precise at speed, but stiff on slow technical trails for some, while a 90 kg rider rated it excellent without changes. It is still a little easy to stall, and hot restarts can be slow.","points":[{"aspect":"engine_mid","verdict":"strength","statement":"Lively, with a bigger midrange kick than before and smooth all the way to a high rev limit.","years":[2025,2026,2027],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Fork feels stiff on slow technical trails, though firm and precise at speed.","years":[2025,2026,2027],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"weakness","statement":"A little easy to stall, and hot restarts can take several seconds, worse after a stall on a hill.","years":[2025,2026,2027],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Fork transmits jolts through the arms over bigger chop for fast riders.","years":[2025],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"strength","statement":"Six-speed spread works from tight singletrack to fire roads.","years":[2025],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"weakness","statement":"The linkage collects dirt, and the right-side axle marks are hidden, so align the wheel from the left.","years":[2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Chassis balance","fix":"Run less race sag than usual (about 95-100 mm)","result":"Better-balanced chassis","support":1},{"problem":"Slick conditions","fix":"Use the softer second map","result":"Flatter midrange with some traction-control effect","support":1}],"disagreements":[{"topic":"Stock suspension","sides":["Firm or stiff on slow technical trails","A 90 kg tester rated it a standout with no changes on grass track, enduro loops and trails"]}]}],"Yamaha|WR450F":[{"years":[2019,2020,2021,2022,2023],"generation":"2019-2023","summary":"In US form testers found the WR450F docile and torquey, great on slow, tight trails but short of punch in sand, hills and open terrain. Uncorking it and fitting the competition ECU transforms it to near-YZ450FX performance. The trail-valved suspension is soft early and progressive deeper and needs firming up for fast desert. Unrestricted Australian bikes felt the opposite, too aggressive on hard-pack.","points":[{"aspect":"power_delivery","verdict":"neutral","statement":"US-spec bike is docile and torquey with no real 450 hit; great on tight trails but struggles in sand, hills and open terrain.","years":[2019,2020,2021,2022,2023],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"neutral","statement":"Same KYB hardware as the FX with softer trail valving: soft early, progressive deeper; firm it up for fast desert.","years":[2019,2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"weakness","statement":"Stock bikes can stumble, cough or die when leaned over at low rpm.","years":[2021],"support":1,"strength":"single source"},{"aspect":"other","verdict":"weakness","statement":"Fuel range is far below claims when ridden hard; one test ran dry at 35 miles in sand.","years":[2023],"support":1,"strength":"single source"},{"aspect":"power_delivery","verdict":"weakness","statement":"Australian-spec 2019 felt too aggressive and tiring on hard-pack and rocks; the handlebar soft map did not calm it enough.","years":[2019],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Restricted, docile US engine","fix":"Remove throttle stop and intake/muffler restrictors and install the competition ECU, optionally with a slip-on","result":"Engine package close to the YZ450FX; one magazine estimated almost 20 hp more","support":2},{"problem":"Low-rpm stumble when leaned over","fix":"Remap through the communication unit","result":"Cured, even with the stock quiet pipe","support":1},{"problem":"Too aggressive (unrestricted bikes)","fix":"Softer app maps","result":"Far less aggressive in tight terrain","support":1}],"disagreements":[{"topic":"Stalling","sides":["One test found the stock bike stumbling and dying at low rpm when leaned over","Another 2021 test reported no stalling"]}]},{"years":[2024,2025,2026],"generation":"2024-2026 (YZ450F-derived chassis)","summary":"Testers find the newer WR450F punchy and willing to rev, with a very low first gear and enough torque in 2nd and 3rd to pull out of corners with little clutch. The app and mellow map can tame it a lot. Stock suspension felt firm at slow pace, so testers softened it with the fork knobs. The flameout trait of older WRs is mostly gone.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Punchy and willing to rev from mid to top with good low-speed traction; the app and mellow map tame it for slick going or beginners.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Stock suspension feels firm at slow pace; testers softened compression.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"neutral","statement":"Flameout is mostly gone, but bogging it in too high a gear can still make it sputter.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Tall seat.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"weakness","statement":"Clutch pull felt heavy at first; moving the perch outward helped.","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Slick conditions","fix":"Start on the mellow map and switch to full power as the ground dries","result":"Better traction","support":1}],"disagreements":[]}]};
